#!/usr/bin/env node
'use strict';

/* ═══════════════════════════════════════════════════════════════════════════
   APEX + WYCKOFF FIX — applied inside this file. The engine functions are
   module-scoped, so a separate patch module cannot reach them.
   Every changed line is tagged [APEX-FIX] or [WYCKOFF-FIX]. Each tunable is
   an env var. The "old" value is what this file used before the fix, so
   setting the env var to that value restores the previous behaviour.

   APEX  pivot wing 3 (old) → 2                       APEX_PIVOT_WING
         swing lookback 30 → 60 bars                  APEX_SWING_LOOKBACK_BARS
         sweep/displacement lookahead 6 → 8 bars      APEX_SWEEP_LOOKAHEAD_BARS
         next-candle tolerance 0 → 0.10 ATR           APEX_NEXT_CANDLE_ATR_TOL
         FVG search 1 → 3 bars back, size per bar    APEX_FVG_SEARCH_BACK
         sweep ATR 0.15 → 0.10 · recovery 0.5 → 0.35 APEX_SWEEP_MIN_ATR / _CLOSE_RECOVERY
         displacement body 0.6 → 0.5, range 1.5 → 1.2 ATR, volume 1.3 → 1.1×
         FVG min size 0.10 → 0.06 ATR                 APEX_FVG_MIN_SIZE_ATR
         BOS window 20 → 35 bars                      APEX_BOS_MAX_AGE
         chase allowance 0.35 → 0.60 R                APEX_CHASE_RISK_MULT
         base min score 78 → 70                       APEX_MIN_SCORE
         retest window unchanged (15)                 APEX_FVG_MAX_AGE
         Sovereign regime floors trend/range/transition 82/76/85 → 78/74/78
                                                      SOV_TREND_/SOV_RANGE_/SOV_TRANSITION_MIN_SCORE
         Sovereign grade floors S/A/B 90/82/74 → 88/78/70 (SOV_SCORE_S/A/B)

   WYCKOFF  pre-break entries: old always on → blocked. WYCKOFF_ALLOW_PRE_BREAK_ENTRY=1 allows.
            trap guard: old opt-in → on. WYCKOFF_TRAP_GUARD_WIRE=0 disables.
            spring = lowest low / highest high of the event window, and the next
              candle may not extend it by more than 0.02 ATR.
            LPS pullback must be a separate, earlier candle than the LPS.
            target: old nearest cluster → deepest cluster. WYCKOFF_TARGET_MODE=nearest restores.
            macro bias must be known, non-neutral and not opposed. WYCKOFF_REQUIRE_MACRO=0 disables.
            min RR 1.5 / 1.8 → 2.0 (WYCKOFF_MIN_RR, WYCKOFF_TRAP_MIN_RR).
            exit ladder TP3 = setup TAKE PROFIT (one exit source).
            trap-guard stage READY_LPS_CONFIRMED → READY_RETEST (alert labels).

   Entry freshness (APEX v3): an alert is sent only when the LIVE price, re-read just before sending, is on the pre-entry
   side of the entry (PENDING LIMIT) or at it (ENTER NOW). It is suppressed when price has traded through the entry
   against the trade, breached the stop, passed the target, or run more than APEX_LIVE_CHASE_RISK_MULT R (default 3R)
   away. BOS must be within APEX_MAX_BARS_SINCE_BOS bars (default 6). APEX_FRESHNESS_FIX_ENABLED=0 turns it off.
   Take-profit (APEX): deepest tested opposing liquidity cluster beyond the BOS close, capped at APEX_TP_MAX_R
   (8R). TP2/TP3 sit at least 1R and 2R beyond TP1. APEX_TP_MODE=nearest restores the old nearest-pool target.
   Operator commands: /apexfix-status · /apexraw SYMBOL · /apexdiagnostics
                      /wyckofffix-status · /wyckoffaudit SYMBOL [BUY|SELL]
   ═══════════════════════════════════════════════════════════════════════════ */

// =========================
// ALL REQUIRES FIRST — before any class or function uses them
// This fixes: ReferenceError: Cannot access 'path' before initialization
// =========================
const fs      = require('fs');
const path    = require('path');
const https   = require('https');
const crypto  = require('crypto');
const { exec, execSync } = require('child_process');
const { promisify }      = require('util');
const zlib    = require('zlib');
const execAsync = promisify(exec);

// Third-party modules
const express   = require('express');
const WebSocket = require('ws');
const axios     = require('axios');
const dotenv    = require('dotenv');

// Load environment variables immediately
try {
  if (fs.existsSync('.env')) dotenv.config();
} catch (_) { /* no .env file — use Render env vars */ }

/* ═══════════════════════════════════════════════════════════════════════════
   [NEON-PATCH] Persistent state via Postgres (Neon / Supabase / any PG)
   ═══════════════════════════════════════════════════════════════════════════ */
let _pg = null;
let _pgAvailable = false;

function _neonGetClient() {
  if (_pg !== null) return _pg;
  const url = String(process.env.DATABASE_URL || '').trim();
  if (!url) {
    _pg = false;
    _pgAvailable = false;
    console.warn('[NEON] DATABASE_URL unset — running with in-memory state only');
    return false;
  }
  try {
    const postgres = require('postgres');
    _pg = postgres(url, {
      ssl: 'require',
      max: 5,
      idle_timeout: 20,
      connect_timeout: 10,
      prepare: false,
      onnotice: () => {},
    });
    _pgAvailable = true;
    console.log('[NEON] Postgres client initialised');
    return _pg;
  } catch (err) {
    console.error('[NEON] Failed to init Postgres client:', err.message);
    _pg = false;
    _pgAvailable = false;
    return false;
  }
}

const _neonMirror = new Map();
const _neonDirty  = new Set();
let   _neonHydrated = false;

function _neonKeyOf(filePath) {
  return path.basename(String(filePath || ''));
}

async function _neonHydrate() {
  if (_neonHydrated) return;
  if (String(process.env.NEON_HYDRATE_ON_BOOT || '1') === '0') {
    _neonHydrated = true;
    return;
  }
  const sql = _neonGetClient();
  if (!sql) { _neonHydrated = true; return; }
  try {
    // Retired Keras-brain keys are skipped so their old rows are not loaded.
    const rows = await sql`SELECT key, payload FROM state_store WHERE key NOT IN ('replay_buffer.json', 'brain_metrics.json')`;
    for (const row of rows) _neonMirror.set(row.key, row.payload);
    _neonHydrated = true;
    console.log(`[NEON] Hydrated ${rows.length} state row(s) from Postgres`);
  } catch (err) {
    console.error('[NEON] Hydration failed (continuing with empty state):', err.message);
    _neonHydrated = true;
  }
}

function _neonQueueWrite(filePath, value) {
  const key = _neonKeyOf(filePath);
  _neonMirror.set(key, value);
  _neonDirty.add(key);
}

async function _neonFlush() {
  if (!_pgAvailable || _neonDirty.size === 0) return;
  const sql = _neonGetClient();
  if (!sql) return;
  const keys = [..._neonDirty];
  _neonDirty.clear();
  try {
    const rows = keys.map(key => ({
      key,
      payload: sql.json(_neonMirror.get(key) ?? {}),
    }));
    await sql`
      INSERT INTO state_store ${sql(rows, 'key', 'payload')}
      ON CONFLICT (key) DO UPDATE
        SET payload = EXCLUDED.payload, updated_at = NOW()
    `;
  } catch (err) {
    for (const k of keys) _neonDirty.add(k);
    console.error('[NEON] Flush failed:', err.message);
  }
}

function _neonRead(filePath) {
  return _neonMirror.get(_neonKeyOf(filePath));
}

setInterval(() => { _neonFlush().catch(() => {}); },
  Math.max(1000, Number(process.env.NEON_FLUSH_INTERVAL_MS || 5000))
).unref();

globalThis.__neonState = {
  get client()   { return _neonGetClient(); },
  get available(){ return _pgAvailable; },
  hydrate: _neonHydrate,
  read:    _neonRead,
  flush:   _neonFlush,
  mirror:  _neonMirror,
  dirty:   _neonDirty,
};

// =========================
// BOUNDED FILE STORAGE
// =========================
// All app-owned JSON state is overwritten atomically and kept below a
// per-file budget. This prevents partial writes, orphaned temp files, and
// slow disk growth during long-running Render deployments.
const STORAGE_DIR = path.resolve(
  process.env.DATA_DIR || process.env.STORAGE_DIR || path.join(process.cwd(), 'data')
);
// Keep application state isolated from node_modules and the deployment
// checkout. Render's ephemeral disk is limited, so the app-owned data budget
// is deliberately conservative and configurable.
const STORAGE_TOTAL_MAX_BYTES = Math.max(
  64 * 1024 * 1024,
  parseInt(process.env.STORAGE_TOTAL_MAX_MB || '4096', 10) * 1024 * 1024
);
const STORAGE_DEFAULT_MAX_BYTES = Math.max(
  64 * 1024,
  parseInt(process.env.STORAGE_DEFAULT_MAX_KB || '512', 10) * 1024
);
const STORAGE_LIMITS = {
  'quantum_state.json':          512 * 1024,
  'market_microstructure.json': 256 * 1024,
  'options_flow.json':           128 * 1024,
  'liquidation_heatmap.json':    256 * 1024,
  'trade_history.json':          192 * 1024,
  'signal_journal.json':         128 * 1024,
  'postliq_history.json':        512 * 1024,
  'ob_memory.json':              256 * 1024,
  'epigenetic.json':             128 * 1024,
  'calibration.json':            128 * 1024,
  'adaptive_agent_weights.json':  64 * 1024,
  'recovery_signals.json':        64 * 1024,
  'bot_config.json':              64 * 1024,
  'smart_money_tracking.json':   128 * 1024,
};

/* Pullback Engine: deterministic continuation entries plus adaptive outcomes. */
// storagePath is declared below; use the already-initialised STORAGE_DIR here
// because this module loads pullback state before the helper declaration.
const _pbAdaptationFile = path.join(STORAGE_DIR, 'brain_direction_adaptation.json');
const _pbAdaptation = { symbols: {}, events: [] };
try {
  if (fs.existsSync(_pbAdaptationFile)) {
    const saved = JSON.parse(fs.readFileSync(_pbAdaptationFile, 'utf8'));
    if (saved?.symbols) Object.assign(_pbAdaptation.symbols, saved.symbols);
    if (Array.isArray(saved?.events)) _pbAdaptation.events.push(...saved.events.slice(-1000));
  }
} catch (e) { console.warn('Pullback adaptation load:', e.message); }

function _pbSave() {
  writeJsonBounded(_pbAdaptationFile, _pbAdaptation, { maxBytes: 256 * 1024 });
}
function _pbEma(values, period) {
  if (!values.length) return 0;
  const k = 2 / (period + 1);
  return values.slice(1).reduce((last, value) => last + (value - last) * k, values[0]);
}
function _pbFmt(value) {
  const n = Number(value);
  return !Number.isFinite(n) ? 'N/A' : String(n >= 1 ? Number(n.toPrecision(7)) : Number(n.toPrecision(9)));
}
function _pbCalculate(symbol, dir, price, candles) {
  const bars = (Array.isArray(candles) ? candles : []).filter(c =>
    Number.isFinite(Number(c?.h)) && Number.isFinite(Number(c?.l)) &&
    Number.isFinite(Number(c?.c))).slice(-48);
  if (bars.length < 20) throw new Error(`Not enough 1h candles for ${symbol}.`);
  const closes = bars.map(c => Number(c.c));
  const bullish = _pbEma(closes, 20) >= _pbEma(closes, 50);
  // Use the latest 24 completed candles. The limit is deliberately placed
  // deeper than the previous near-market version so a normal 2% sweep does
  // not immediately invalidate the continuation setup.
  const sample = bars.slice(-24);
  const high = Math.max(...sample.map(c => Number(c.h)));
  const low = Math.min(...sample.map(c => Number(c.l)));
  const range = high - low;
  if (!(range > 0)) throw new Error(`The recent impulse for ${symbol} is too small.`);
  const last = sample[sample.length - 1];
  const atr = sample.slice(-14).reduce((sum, c) => sum + (Number(c.h) - Number(c.l)), 0) / 14;
  // Exhaustion band: at least 2%, at most 3% from live price. The 78.6%
  // OTE/fib candidate chooses where inside that band the limit belongs.
  // This is a risk-control band, never a claim of guaranteed safety.
  const rawFib = dir === 'BUY' ? high - range * 0.786 : low + range * 0.786;
  const rawDistance = Math.abs(price - rawFib) / price;
  const safePct = Math.min(0.03, Math.max(0.02, rawDistance));
  const nearMarket = dir === 'BUY' ? price * (1 - safePct) : price * (1 + safePct);
  const recentRetrace = dir === 'BUY'
    ? Math.min(...sample.slice(-6).map(c => Number(c.l)))
    : Math.max(...sample.slice(-6).map(c => Number(c.h)));
  const entry = dir === 'BUY'
    ? Math.min(price * 0.98, Math.max(price * 0.97, nearMarket))
    : Math.max(price * 1.02, Math.min(price * 1.03, nearMarket));
  const impulseLabel = dir === 'BUY'
    ? (bullish ? 'bullish impulse → near-market bearish pullback' : 'near-market BUY pullback')
    : (!bullish ? 'bearish impulse → near-market bullish pullback' : 'near-market SELL pullback');
  const retraceHigh = Math.max(...sample.slice(-6).map(c => Number(c.h)));
  const retraceLow = Math.min(...sample.slice(-6).map(c => Number(c.l)));
  return {
    symbol, dir, price, setup: true, high, low, retracement: safePct, entry,
    retraceHigh, retraceLow, impulseLabel, rawFib,
    deepEntry: dir === 'BUY' ? price * 0.97 : price * 1.03,
    invalidation: dir === 'BUY' ? entry - atr * 1.25 : entry + atr * 1.25,
    target: dir === 'BUY' ? Math.max(high, price) + atr * 1.5 : Math.min(low, price) - atr * 1.5,
    trend: dir === 'BUY' ? 'BUY CONTINUATION' : 'SELL CONTINUATION',
    confidence: 'EXHAUSTION BAND',
    note: `${impulseLabel}; 78.6% exhaustion candidate clamped to ${(safePct * 100).toFixed(2)}% from live price.`,
  };
}
function _pbStats(symbol, dir) {
  const row = _pbAdaptation.symbols[symbol] || (_pbAdaptation.symbols[symbol] = {});
  return row[dir] || (row[dir] = { wins: 0, losses: 0, score: 0 });
}
function _pbLog(symbol, dir, outcome) {
  const stats = _pbStats(symbol, dir);
  stats[outcome === 'WIN' ? 'wins' : 'losses']++;
  stats.score = Number((Number(stats.score || 0) * 0.85 + (outcome === 'WIN' ? 1 : -1)).toFixed(4));
  _pbAdaptation.events.push({ symbol, dir, outcome, ts: Date.now() });
  if (_pbAdaptation.events.length > 1000) _pbAdaptation.events.splice(0, _pbAdaptation.events.length - 1000);
  _pbSave();
  return stats;
}
function _pbBias(symbol) {
  const buy = _pbStats(symbol, 'BUY'), sell = _pbStats(symbol, 'SELL');
  if (buy.score > sell.score + 0.25) return `BUY bias (${buy.score.toFixed(2)} vs SELL ${sell.score.toFixed(2)})`;
  if (sell.score > buy.score + 0.25) return `SELL bias (${sell.score.toFixed(2)} vs BUY ${buy.score.toFixed(2)})`;
  return `NEUTRAL (BUY ${buy.score.toFixed(2)} / SELL ${sell.score.toFixed(2)})`;
}
function _pbRender(r) {
  if (!r.setup) {
    return [
      `⏳ <b>${r.symbol} ${r.dir} PULLBACK — WAIT</b>`,
      `Live: <code>${_pbFmt(r.price)}</code>`,
      '',
      r.reason,
      '',
      `Required sequence: ${r.dir === 'BUY'
        ? 'bullish impulse → bearish retracement → BUY continuation'
        : 'bearish impulse → bullish retracement → SELL continuation'}`,
      '<i>No limit is issued until that sequence exists.</i>',
    ].join('\n');
  }
  const p = x => `<code>${_pbFmt(x)}</code>`;
  return [
    `📐 <b>${r.symbol} ${r.dir} PULLBACK</b>`,
    `Live: ${p(r.price)} · Trend: <b>${r.trend}</b> · Confidence: <b>${r.confidence}</b>`,
    `48h impulse: ${p(r.low)} → ${p(r.high)}`,
    `Retracement rule: <b>${(r.retracement * 100).toFixed(1)}%</b>`, '',
    `🎯 <b>Exact continuation entry: ${p(r.entry)}</b>`,
    `🧲 Deep entry: ${p(r.deepEntry)}`,
    `🛑 Invalidation: ${p(r.invalidation)}`,
    `🚀 Measured target: ${p(r.target)}`, '',
    r.note, `Direction adaptation: ${_pbBias(r.symbol)}`,
    '', '<i>Calculated from the latest 48 completed 1h candles; not a guaranteed fill.</i>',
  ].join('\n');
}

process.nextTick(() => {
  try {
const _pbPreviousHandler = EnhancedQuantumTelegramInterface.prototype.handleEnhancedCommand;
EnhancedQuantumTelegramInterface.prototype.handleEnhancedCommand = async function(message) {
  const text = String(message?.text || '').trim();
  const parts = text.split(/\s+/);
  const cmd = (parts[0] || '').toLowerCase().replace(/@[^\s]+$/, '');
  const chatId = message?.chat?.id;
  // This feature wrapper is installed from process.nextTick(), so it runs
  // outside the final prototype guard below. Protect the commands handled
  // here as well; all other commands delegate to the guarded chain.
  if (['/pullback', '/brainloss/win', '/brainloss/loss'].includes(cmd) &&
      (message?._telegramUpdateId !== undefined || message?.message_id !== undefined)) {
    if (!this._handledTelegramCommands) this._handledTelegramCommands = new Map();
    const _pbKey = message?._telegramUpdateId !== undefined
      ? `update:${String(message._telegramUpdateId)}`
      : `message:${String(chatId)}:${String(message.message_id)}`;
    const _pbNow = Date.now();
    for (const [_seenKey, _seenAt] of this._handledTelegramCommands) {
      if (_pbNow - _seenAt > 10 * 60 * 1000) this._handledTelegramCommands.delete(_seenKey);
    }
    if (this._handledTelegramCommands.has(_pbKey)) {
      console.warn(`⏭️ Duplicate Telegram command ignored (${_pbKey})`);
      return;
    }
    this._handledTelegramCommands.set(_pbKey, _pbNow);
  }
  if (cmd === '/pullback') {
    if (!isAdminMessage(message)) return;
    const symbol = String(parts[1] || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
    const dir = String(parts[2] || '').toUpperCase();
    if (!symbol || !['BUY', 'SELL'].includes(dir)) {
      await this.sendMessage(chatId, 'Usage: <code>/pullback SYMBOL BUY|SELL</code>');
      return;
    }
    try {
      await this.sendMessage(chatId, `📡 Mapping exact ${symbol} ${dir} continuation pullback...`);
      const [priceRaw, candles] = await Promise.all([
        fetchLivePrice(symbol), fetchCandlesCached(symbol, '1h', 120),
      ]);
      const price = Number(priceRaw);
      if (!Number.isFinite(price) || price <= 0) throw new Error('Live price unavailable.');
      await this.sendMessage(chatId, _pbRender(_pbCalculate(symbol, dir, price, candles)));
    } catch (e) { await this.sendMessage(chatId, `❌ Pullback error: ${e.message}`); }
    return;
  }
  if (cmd === '/brainloss/win' || cmd === '/brainloss/loss') {
    if (!isAdminMessage(message)) return;
    const symbol = String(parts[1] || '').toUpperCase().replace(/\//g, '');
    const dir = String(parts[2] || '').toUpperCase();
    if (!symbol || !['BUY', 'SELL'].includes(dir)) {
      await this.sendMessage(chatId, `Usage: <code>${cmd} SYMBOL BUY|SELL</code>`);
      return;
    }
    const won = cmd === '/brainloss/win';
    const existing = _mbRecordOutcome(symbol, dir, won);
    const stats = _pbLog(symbol, dir, won ? 'WIN' : 'LOSS');
    await this.sendMessage(chatId, [
      `${won ? '✅ WIN' : '❌ LOSS'} recorded for <b>${symbol} ${dir}</b>`,
      existing ? `Main Brain plan: <code>${existing.id}</code>` : 'Generic signal outcome logged.',
      `Direction adaptation updated: ${_pbBias(symbol)}`,
      `${dir} stats: ${stats.wins}W / ${stats.losses}L · score ${stats.score.toFixed(2)}`,
    ].join('\n'));
    return;
  }
  return _pbPreviousHandler.call(this, message);
};
console.log('✅ Pullback Engine loaded: /pullback, /brainloss/win, /brainloss/loss');
  } catch (e) {
    console.error('Pullback wrapper install failed:', e.message);
  }
});
const STORAGE_STATE_FILES = Object.keys(STORAGE_LIMITS);

function storagePath(filePath) {
  return path.isAbsolute(filePath) ? filePath : path.join(STORAGE_DIR, filePath);
}

function storageLimit(filePath, requested) {
  return Math.max(
    16 * 1024,
    requested || STORAGE_LIMITS[path.basename(filePath)] || STORAGE_DEFAULT_MAX_BYTES
  );
}

function trimJsonToBudget(value, maxBytes) {
  let current = value;
  for (let attempt = 0; attempt < 16; attempt++) {
    const serialized = JSON.stringify(current);
    if (Buffer.byteLength(serialized, 'utf8') <= maxBytes) return current;

    if (Array.isArray(current)) {
      if (current.length <= 1) return current;
      current = current.slice(Math.ceil(current.length / 2));
      continue;
    }

    if (current && typeof current === 'object') {
      const keys = Object.keys(current);
      if (!keys.length) return current;
      const next = {};
      // Prefer shrinking nested arrays/objects before dropping top-level
      // sections, which preserves the shape of state files where possible.
      for (const key of keys) {
        const item = current[key];
        if (Array.isArray(item) && item.length > 1) {
          next[key] = item.slice(Math.ceil(item.length / 2));
        } else if (item && typeof item === 'object' && !Array.isArray(item)) {
          const childKeys = Object.keys(item);
          next[key] = childKeys.length > 20
            ? Object.fromEntries(childKeys.slice(-Math.ceil(childKeys.length / 2))
                .map(childKey => [childKey, item[childKey]]))
            : item;
        } else {
          next[key] = item;
        }
      }
      const nextSerialized = JSON.stringify(next);
      if (Buffer.byteLength(nextSerialized, 'utf8') < Buffer.byteLength(serialized, 'utf8')) {
        current = next;
      } else {
        current = Object.fromEntries(keys.slice(-Math.ceil(keys.length / 2))
          .map(key => [key, current[key]]));
      }
      continue;
    }

    return value;
  }
  return current;
}

function writeJsonBounded(filePath, value, options = {}) {
  const target = storagePath(filePath);

  try {
    if (globalThis.__neonState && globalThis.__neonState.available) {
      globalThis.__neonState.mirror.set(path.basename(target), value);
      globalThis.__neonState.dirty.add(path.basename(target));
    }
  } catch (_) { /* never let DB mirror break disk path */ }

  const maxBytes = storageLimit(target, options.maxBytes);
  const dir = path.dirname(target);
  const temp = path.join(
    dir,
    `.${path.basename(target)}.tmp-${process.pid}-${Date.now()}`
  );

  try {
    fs.mkdirSync(dir, { recursive: true });
    // Do not allow state writes to consume the whole Render disk. Individual
    // files are bounded below as well, but this protects against future state
    // files or model artifacts being added without a matching limit.
    const currentStorageBytes = getDirectorySize(STORAGE_DIR);
    if (currentStorageBytes > STORAGE_TOTAL_MAX_BYTES) {
      throw new Error(
        `application storage is ${Math.round(currentStorageBytes / 1024 / 1024)}MB; ` +
        `limit is ${Math.round(STORAGE_TOTAL_MAX_BYTES / 1024 / 1024)}MB`
      );
    }
    const bounded = trimJsonToBudget(value, maxBytes);
    const serialized = JSON.stringify(bounded);
    if (Buffer.byteLength(serialized, 'utf8') > maxBytes) {
      throw new Error(`${path.basename(target)} cannot fit within ${maxBytes} bytes`);
    }
    fs.writeFileSync(temp, serialized, { encoding: 'utf8', mode: 0o600 });
    fs.renameSync(temp, target);
    return true;
  } catch (error) {
    try { if (fs.existsSync(temp)) fs.unlinkSync(temp); } catch (_) {}
    console.warn(`Storage save skipped for ${target}:`, error.message);
    return false;
  }
}

function pruneKnownStorageFiles() {
  for (const fileName of STORAGE_STATE_FILES) {
    const target = storagePath(fileName);
    const tempPrefix = `.${path.basename(target)}.tmp-`;
    try {
      if (fs.existsSync(target) && fs.statSync(target).size > storageLimit(target)) {
        const parsed = JSON.parse(fs.readFileSync(target, 'utf8'));
        writeJsonBounded(target, parsed);
      }
      const dirEntries = fs.existsSync(path.dirname(target))
        ? fs.readdirSync(path.dirname(target))
        : [];
      for (const entry of dirEntries) {
        if (entry.startsWith(tempPrefix)) {
          try { fs.unlinkSync(path.join(path.dirname(target), entry)); } catch (_) {}
        }
      }
    } catch (error) {
      console.warn(`Storage cleanup skipped for ${target}:`, error.message);
    }
  }
}

function getDirectorySize(dirPath) {
  if (!fs.existsSync(dirPath)) return 0;
  let total = 0;
  for (const entry of fs.readdirSync(dirPath, { withFileTypes: true })) {
    const target = path.join(dirPath, entry.name);
    try {
      total += entry.isDirectory() ? getDirectorySize(target) : fs.statSync(target).size;
    } catch (_) {}
  }
  return total;
}

