const CONTROL_TOKEN = process.env.HTTP_CONTROL_TOKEN || process.env.CONTROL_TOKEN || '';

function hasValidControlToken(req) {
  if (!CONTROL_TOKEN) return false;
  const supplied = req.get('x-control-token') ||
    (req.get('authorization') || '').replace(/^Bearer\s+/i, '');
  if (!supplied || supplied.length !== CONTROL_TOKEN.length) return false;
  try {
    return crypto.timingSafeEqual(
      Buffer.from(supplied, 'utf8'),
      Buffer.from(CONTROL_TOKEN, 'utf8')
    );
  } catch (_) {
    return false;
  }
}

function requireControlToken(req, res, next) {
  if (!hasValidControlToken(req)) {
    return res.status(CONTROL_TOKEN ? 401 : 503).json({
      ok: false,
      error: CONTROL_TOKEN ? 'Unauthorized' : 'HTTP control disabled: set HTTP_CONTROL_TOKEN',
    });
  }
  next();
}

