/* ──────────────── 1. SIGNAL JOURNAL ──────────────────────────────── */
const SIGNAL_JOURNAL      = [];
const SIGNAL_JOURNAL_FILE = storagePath('signal_journal.json');
const JOURNAL_MAX         = 300; // STORAGE-OPT: was 500 — reduced to keep journal.json under ~200KB

try {
  if (typeof fs !== 'undefined' && fs.existsSync(SIGNAL_JOURNAL_FILE)) {
    const _jd = JSON.parse(fs.readFileSync(SIGNAL_JOURNAL_FILE, 'utf8'));
    SIGNAL_JOURNAL.push(..._jd.slice(-JOURNAL_MAX));
    console.log(`📓 Journal loaded: ${SIGNAL_JOURNAL.length} entries`);
  }
} catch(_je) { console.warn('Journal load:', _je.message); }

function logSignalFired(symbol, consensus, instCtx, scored) {
  try {
    const b = consensus?.bestSig;
    _calibRecordFired(symbol, consensus, instCtx);
    // logTradeOutcome tracks every fired signal for expectancy/journal
    if (b?.entry && consensus?.consensusDirection) {
      logTradeOutcome(symbol, consensus.consensusDirection, b.entry, 0, 0,
        consensus.certaintyScore || 0, b.stop_loss || 0, b.take_profits?.[0] || 0);
    }
    const entry = {
      symbol,
      dir:     consensus?.consensusDirection || 'NEUTRAL',
      cert:    consensus?.certaintyScore     || 0,
      conv:    consensus?.convictionPct      || 0,
      tradeT:  consensus?.tradeType          || 'INTRADAY',
      verdict: scored?.verdict || '?',
      score:   scored?.score   || 0,
      mtfTier: consensus?.mtfTier || 'SPECULATIVE',
      entry:   b?.entry       || 0,
      sl:      b?.stop_loss   || 0,
      tp1:     b?.take_profits?.[0] || 0,
      wyckoff: instCtx?.wyckoff?.phase    || 'UNKNOWN',
      trapped: instCtx?.trap?.trapped     || false,
      trapDir: instCtx?.trap?.direction   || 'NONE',
      session: instCtx?.kz?.name          || 'OFF_SESSION',
      pillars: [
        instCtx?.wyckoff?.bias === (consensus?.consensusDirection),
        instCtx?.struct?.choch || instCtx?.struct?.bos,
        instCtx?.trap?.direction === (consensus?.consensusDirection),
        instCtx?.kz?.active,
      ].filter(Boolean).length,
      preInst:  instCtx?.preInst?.type    || null,
      cvd:      instCtx?.vol?.main?.cvdTrend || null,
      newsSent: instCtx?.news?.sentiment  || 'NEUTRAL',
      newsRisk: instCtx?.news?.riskLevel  || 'NORMAL',
      ts:       Date.now(),
      outcome:  null,
      pnl:      null,
    };
    SIGNAL_JOURNAL.push(entry);
    if (SIGNAL_JOURNAL.length > JOURNAL_MAX)
      SIGNAL_JOURNAL.splice(0, SIGNAL_JOURNAL.length - JOURNAL_MAX);
    try {
      if (typeof fs !== 'undefined')
        writeJsonBounded(SIGNAL_JOURNAL_FILE, SIGNAL_JOURNAL);
    } catch(_) {}
    return entry;
  } catch(e) { console.warn('logSignalFired:', e.message); }
}

function recoveryHistoryPrice(value) {
  const number = Number(value);
  return Number.isFinite(number) && number > 0
    ? String(Number(number.toPrecision(9)))
    : 'not recorded';
}

// ── begin calibration lab ──
// Measures the bot's own signals from real prices, 24/7. Nothing here sends a message.
//   LIMITBOT  every READY Limitbot plan at any quality, so the 80 threshold can be tested
//   FIRED     signals that went through the HTF and intraday paths
//   CANDIDATE every Single Brain candidate, including ones that never reach Telegram
// Each record waits for its entry, then the first of stop or target to be touched in the
// candles the scanners already fetch. /calibration prints the result.
const CALIB_FILE         = 'calibration_lab.json';
const CALIB_MAX_PENDING  = 200;
const CALIB_MAX_RESOLVED = 400;
const CALIB_COST_PCT     = Math.max(0, Number(process.env.SIGNAL_COST_PCT || 0.12));
const CALIB_DEDUPE_MS    = 4 * 3600 * 1000;
const CALIB_MIN_WL       = 50;
const CALIB_MIN_BUCKET   = 30;
const CALIB_PERSIST      = String(process.env.CALIBRATION_PERSIST || 'disk').toLowerCase() === 'db' ? 'db' : 'disk';
const CALIB_HOLD_DAYS    = { '15min': 2, '1h': 4, '4h': 10, '8h': 15, '1day': 30, '2day': 60, '1week': 120 };
const _calib = {
  pending: [], resolved: [], loaded: false, dirty: false, lastSave: 0,
  layoutWarned: new Set(), stats: { recorded: 0, deduped: 0, invalid: 0 },
};
const _CALIB_BUCKETS = [
  { label: 'under 60', test: c => c < 60 },
  { label: '60-69',    test: c => c >= 60 && c < 70 },
  { label: '70-79',    test: c => c >= 70 && c < 80 },
  { label: '80-89',    test: c => c >= 80 && c < 90 },
  { label: '90+',      test: c => c >= 90 },
];

function _calibHoldMs(tf) {
  return (CALIB_HOLD_DAYS[tf] || 10) * 24 * 3600 * 1000;
}
function _calibLoad() {
  if (_calib.loaded) return;
  _calib.loaded = true;
  try {
    const file = storagePath(CALIB_FILE);
    if (fs.existsSync(file)) {
      const d = JSON.parse(fs.readFileSync(file, 'utf8'));
      _calib.pending  = Array.isArray(d.pending)  ? d.pending.slice(-CALIB_MAX_PENDING)   : [];
      _calib.resolved = Array.isArray(d.resolved) ? d.resolved.slice(-CALIB_MAX_RESOLVED) : [];
      console.log(`🧪 Calibration lab loaded: ${_calib.pending.length} pending, ${_calib.resolved.length} resolved`);
    }
  } catch (e) {
    console.warn('Calibration lab load skipped:', e.message);
  }
}
function _calibSave(force = false) {
  if (!_calib.dirty && !force) return;
  if (!force && Date.now() - _calib.lastSave < 60 * 1000) return;
  _calib.lastSave = Date.now();
  _calib.dirty = false;
  const payload = { version: 1, savedAt: new Date().toISOString(), pending: _calib.pending, resolved: _calib.resolved };
  try {
    if (CALIB_PERSIST === 'db') {
      writeJsonBounded(CALIB_FILE, payload, { maxBytes: 160 * 1024 });
      return;
    }
    const file = storagePath(CALIB_FILE);
    fs.mkdirSync(path.dirname(file), { recursive: true });
    const tmp = `${file}.tmp-${process.pid}`;
    fs.writeFileSync(tmp, JSON.stringify(payload));
    fs.renameSync(tmp, file);
  } catch (e) {
    console.warn('Calibration lab save skipped:', e.message);
  }
}

// ── recording ──
function _calibRecord(rec, sent) {
  _calibLoad();
  const same = r => r.group === rec.group && r.sym === rec.sym && r.dir === rec.dir
    && Math.abs(r.ts - rec.ts) < CALIB_DEDUPE_MS;
  const existing = _calib.pending.find(same) || _calib.resolved.find(same);
  if (existing) {
    if (sent && !existing.sent) { existing.sent = true; _calib.dirty = true; }
    _calib.stats.deduped++;
    return;
  }
  _calib.pending.push({ ...rec, sent: !!sent });
  if (_calib.pending.length > CALIB_MAX_PENDING) {
    _calib.pending.splice(0, _calib.pending.length - CALIB_MAX_PENDING);
  }
  _calib.stats.recorded++;
  _calib.dirty = true;
}
function _calibRecordIfValid(rec, sent, inst) {
  try {
    const numeric = [rec.entry, rec.sl, rec.tp, rec.conf].every(Number.isFinite);
    if (!numeric || (rec.dir !== 'BUY' && rec.dir !== 'SELL') || !rec.sym || !(rec.ts > 0)) {
      _calib.stats.invalid++;
      return;
    }
    const apex = inst?._apexResult;
    rec.apex   = apex ? Math.round(Number(apex.apexScore) || 0) : null;
    rec.apexOk = apex ? apex.approved === true : null;
    rec.conf   = Math.round(rec.conf);
    _calibRecord(rec, sent);
  } catch (e) {
    console.warn('Calibration record skipped:', e.message);
  }
}
function _calibRecordCandidate(sig) {
  if (!sig || !sig.symbol) return;
  _calibRecordIfValid({
    group: 'CANDIDATE', sym: String(sig.symbol).toUpperCase(), dir: String(sig.direction || '').toUpperCase(),
    tf: String(sig.timeframe || 'unknown'), conf: Number(sig.confidence),
    entry: Number(sig.entry), sl: Number(sig.stopLoss), tp: Number(sig.takeProfit),
    fill: 'MARKET', ts: Number(sig.timestamp) || Date.now(),
  }, false, sig._instCtx || sig._consensus?._instCtx);
}
function _calibRecordFired(symbol, consensus, instCtx) {
  const b = consensus?.bestSig;
  _calibRecordIfValid({
    group: 'FIRED', sym: String(symbol || '').toUpperCase(), dir: String(consensus?.consensusDirection || '').toUpperCase(),
    tf: String(consensus?.tradeType || b?.timeframe || 'unknown'), conf: Number(consensus?.certaintyScore),
    entry: Number(b?.entry), sl: Number(b?.stop_loss), tp: Number(b?.take_profits?.[0]),
    fill: 'MARKET', ts: Date.now(),
  }, true, instCtx || consensus?._instCtx);
}
function _calibRecordLimitbot(result, sent) {
  if (!result || result.status !== 'READY') return;
  const p = Number(result.moveProbability);
  _calibRecordIfValid({
    group: 'LIMITBOT', sym: String(result.symbol || '').toUpperCase(), dir: String(result.direction || '').toUpperCase(),
    tf: '4h', conf: Number(result.signalQuality),
    entry: Number(result.limitEntry), sl: Number(result.slPrice), tp: Number(result.tp1Price),
    fill: 'LIMIT', ts: Date.now(), pMove: Number.isFinite(p) && p >= 0 ? p : null,
  }, !!sent, null);
}

// ── resolving from cached candles: each candle is [openTimeMs, open, high, low, close, volume] ──
function _calibCandleOk(c) {
  const t = Number(c[0]), o = Number(c[1]), h = Number(c[2]), l = Number(c[3]), cl = Number(c[4]);
  return t > 1e12 && [o, h, l, cl].every(v => Number.isFinite(v) && v > 0)
    && h >= l && h + 1e-9 >= Math.max(o, cl) && l - 1e-9 <= Math.min(o, cl);
}
function _calibCandleSets(sym) {
  const sets = [];
  for (const [key, val] of _candleCache.entries()) {
    if (!key.startsWith(`${sym}_`)) continue;
    const raw = val && Array.isArray(val.data) ? val.data : null;
    if (!raw || raw.length < 3) continue;
    const candles = raw.filter(c => Array.isArray(c) && c.length >= 5)
      .slice().sort((a, b) => Number(a[0]) - Number(b[0]));
    if (candles.length < 3) continue;
    const bar = Number(candles[1][0]) - Number(candles[0][0]);
    if (!(bar > 0)) continue;
    sets.push({ key, candles, bar });
  }
  return sets.sort((a, b) => a.bar - b.bar); // finest bars first: the most precise path
}
function _calibResolveOne(rec, now) {
  const risk = Math.abs(rec.entry - rec.sl);
  const reward = Math.abs(rec.tp - rec.entry);
  const geometryOk = rec.dir === 'BUY'
    ? (rec.sl < rec.entry && rec.entry < rec.tp)
    : (rec.tp < rec.entry && rec.entry < rec.sl);
  if (!geometryOk || !(risk > 0) || !(reward > 0)) return { drop: true };
  const sign = rec.dir === 'BUY' ? 1 : -1;
  const costR = (rec.entry * CALIB_COST_PCT / 100) / risk;
  const hold = _calibHoldMs(rec.tf);
  const age = now - rec.ts;
  const stopOut = t => ({ out: 'LOSS', exit: rec.sl, exitTs: t, rG: -1, rN: -1 - costR });
  for (const set of _calibCandleSets(rec.sym)) {
    if (Number(set.candles[0][0]) > rec.ts) continue; // this window does not start before the signal
    if (!set.candles.every(_calibCandleOk)) {
      if (!_calib.layoutWarned.has(set.key)) {
        _calib.layoutWarned.add(set.key);
        console.warn(`🧪 Calibration: candle layout check failed for ${set.key}; its prices are not used`);
      }
      continue;
    }
    let filled = rec.fill === 'MARKET';
    let lastT = null;
    let lastClose = null;
    for (const c of set.candles) {
      const t = Number(c[0]), h = Number(c[2]), l = Number(c[3]), cl = Number(c[4]);
      if (t + set.bar <= rec.ts) continue; // bar closed before the signal
      lastT = t;
      lastClose = cl;
      const stopHit = rec.dir === 'BUY' ? l <= rec.sl : h >= rec.sl;
      const targetHit = rec.dir === 'BUY' ? h >= rec.tp : l <= rec.tp;
      if (!filled) {
        const fillHit = rec.dir === 'BUY' ? l <= rec.entry : h >= rec.entry;
        if (!fillHit) continue;
        filled = true;
        if (stopHit) return stopOut(t); // filled and stopped in the same bar: count the stop
        continue;                       // the target counts from the next bar on
      }
      if (stopHit) return stopOut(t);   // same bar touching both: the stop is counted first
      if (targetHit) {
        const rG = reward / risk;
        return { out: 'WIN', exit: rec.tp, exitTs: t, rG, rN: rG - costR };
      }
    }
    const fresh = lastT !== null && lastT + 2 * set.bar >= now;
    if (age > hold) {
      if (fresh) {
        if (!filled) return { out: 'NOFILL', exit: null, exitTs: lastT, rG: null, rN: null };
        const rG = sign * (lastClose - rec.entry) / risk;
        return { out: 'EXPIRED', exit: lastClose, exitTs: lastT, rG, rN: rG - costR };
      }
      if (age > 2 * hold) return { out: 'UNRESOLVED', exit: null, exitTs: now, rG: null, rN: null };
    }
    return null;
  }
  if (age > 2 * hold) return { out: 'UNRESOLVED', exit: null, exitTs: now, rG: null, rN: null };
  return null;
}
function _calibResolveAll() {
  _calibLoad();
  const now = Date.now();
  const keep = [];
  for (const rec of _calib.pending) {
    const r = _calibResolveOne(rec, now);
    if (r === null) { keep.push(rec); continue; }
    _calib.dirty = true;
    if (r.drop) { _calib.stats.invalid++; continue; }
    _calib.resolved.push({ ...rec, out: r.out, exit: r.exit, exitTs: r.exitTs, rG: r.rG, rN: r.rN });
  }
  _calib.pending = keep;
  if (_calib.resolved.length > CALIB_MAX_RESOLVED) {
    _calib.resolved.splice(0, _calib.resolved.length - CALIB_MAX_RESOLVED);
  }
  _calibSave();
}

// ── statistics ──
function _calibWilson(wins, n, z = 1.96) {
  if (!n) return [0, 0];
  const p = wins / n;
  const z2 = z * z;
  const denom = 1 + z2 / n;
  const centre = (p + z2 / (2 * n)) / denom;
  const half = z * Math.sqrt(p * (1 - p) / n + z2 / (4 * n * n)) / denom;
  return [Math.max(0, centre - half), Math.min(1, centre + half)];
}
function _calibSummary(rows) {
  const wl = rows.filter(r => r.out === 'WIN' || r.out === 'LOSS');
  const n = wl.length;
  const wins = wl.filter(r => r.out === 'WIN').length;
  const [lo, hi] = _calibWilson(wins, n);
  return {
    n, wins,
    wr: n ? wins / n : null,
    lo: n ? lo : null,
    hi: n ? hi : null,
    meanR: n ? wl.reduce((s, r) => s + r.rN, 0) / n : null,
  };
}
function _calibZ(a, b) {
  if (!a.n || !b.n) return 0;
  const p = (a.wins + b.wins) / (a.n + b.n);
  const se = Math.sqrt(p * (1 - p) * (1 / a.n + 1 / b.n));
  return se > 0 ? (a.wins / a.n - b.wins / b.n) / se : 0;
}
function _calibLine(label, g) {
  const pct = x => (x === null || x === undefined) ? '  n/a' : `${(x * 100).toFixed(1)}%`;
  const rr = x => (x === null || x === undefined) ? '  n/a' : `${x >= 0 ? '+' : ''}${x.toFixed(2)}R`;
  return `${label.padEnd(9)} n=${String(g.n).padStart(4)}  WR ${pct(g.wr).padStart(6)}  95% ${pct(g.lo)}-${pct(g.hi)}  E ${rr(g.meanR)}`;
}
function _calibVerdict(rows, dimension) {
  const s = _calibSummary(rows);
  if (s.n < CALIB_MIN_WL) {
    return `not enough yet (${s.n} of ${CALIB_MIN_WL} resolved wins and losses). Nothing is decided before then.`;
  }
  const pop = _CALIB_BUCKETS
    .map(b => ({ label: b.label, g: _calibSummary(rows.filter(r => b.test(r.conf))) }))
    .filter(x => x.g.n >= CALIB_MIN_BUCKET);
  if (pop.length < 2) {
    return `each ${dimension} bucket needs ${CALIB_MIN_BUCKET}+ resolved trades before buckets can be compared.`;
  }
  const lo = pop[0];
  const hi = pop[pop.length - 1];
  const z = _calibZ(hi.g, lo.g);
  const detail = `${hi.label} ${(hi.g.wr * 100).toFixed(1)}% vs ${lo.label} ${(lo.g.wr * 100).toFixed(1)}%, z ${z.toFixed(2)}`;
  if (Math.abs(z) < 1.96) {
    return `no reliable difference yet (${detail}). The ${dimension} is not separating winners from losers in this sample.`;
  }
  if (z > 0) return `higher ${dimension} wins more often here (${detail}). Keep collecting before trusting it.`;
  return `higher ${dimension} wins LESS often here (${detail}). Treat the ${dimension} as inverted until more data says otherwise.`;
}
function _calibVerdictTwo(a, b, nameA, nameB) {
  const ga = _calibSummary(a);
  const gb = _calibSummary(b);
  if (ga.n < CALIB_MIN_BUCKET || gb.n < CALIB_MIN_BUCKET) {
    return `needs ${CALIB_MIN_BUCKET}+ resolved trades in each group (${nameA} ${ga.n}, ${nameB} ${gb.n}).`;
  }
  const z = _calibZ(ga, gb);
  const detail = `${nameA} ${(ga.wr * 100).toFixed(1)}% vs ${nameB} ${(gb.wr * 100).toFixed(1)}%, z ${z.toFixed(2)}`;
  if (Math.abs(z) < 1.96) return `no reliable difference yet (${detail}).`;
  if (z > 0) return `${nameA} wins more often here (${detail}).`;
  return `${nameB} wins more often here (${detail}). The gate is not helping in this sample.`;
}

// ── the /calibration report (plain text, no HTML) ──
function _calibReportText() {
  _calibLoad();
  const rows = _calib.resolved;
  const cnt = o => rows.filter(r => r.out === o).length;
  const now = Date.now();
  const ages = _calib.pending.map(r => now - r.ts);
  const oldestH = ages.length ? Math.round(Math.max(...ages) / 3600000) : 0;
  const L = [];
  L.push(`🧪 CALIBRATION LAB: real prices, fees and slippage ${CALIB_COST_PCT}% round trip`);
  L.push(`Resolved: ${cnt('WIN') + cnt('LOSS')} wins and losses · ${cnt('EXPIRED')} expired · ${cnt('NOFILL')} limit never filled · ${cnt('UNRESOLVED')} unresolved`);
  L.push(`Pending: ${_calib.pending.length}${ages.length ? ` (oldest ${oldestH} h)` : ''} · recorded ${_calib.stats.recorded} · duplicates skipped ${_calib.stats.deduped} · invalid ${_calib.stats.invalid}`);
  L.push('');
  L.push('WIN RATE BY CONFIDENCE (wins / wins+losses)');
  for (const grp of ['LIMITBOT', 'FIRED', 'CANDIDATE']) {
    const gRows = rows.filter(r => r.group === grp);
    const sentNote = grp === 'LIMITBOT' ? ` · ${gRows.filter(r => r.sent).length} sent to Telegram` : '';
    L.push(`${grp} (${_calibSummary(gRows).n} resolved${sentNote})`);
    for (const b of _CALIB_BUCKETS) {
      L.push('  ' + _calibLine(b.label, _calibSummary(gRows.filter(r => b.test(r.conf)))));
    }
  }
  L.push('');
  L.push('LIMITBOT THRESHOLD TEST (quality at least T)');
  const lb = rows.filter(r => r.group === 'LIMITBOT');
  for (const T of [60, 70, 80, 90]) {
    L.push('  ' + _calibLine(`${T}+`, _calibSummary(lb.filter(r => r.conf >= T))));
  }
  const apexRows = rows.filter(r => r.group !== 'LIMITBOT' && r.apexOk !== null && r.apexOk !== undefined);
  L.push('');
  L.push('APEX GATE (FIRED and CANDIDATE with an APEX read)');
  L.push('  ' + _calibLine('approved', _calibSummary(apexRows.filter(r => r.apexOk === true))));
  L.push('  ' + _calibLine('rejected', _calibSummary(apexRows.filter(r => r.apexOk === false))));
  const mp = lb.filter(r => Number.isFinite(r.pMove) && (r.out === 'WIN' || r.out === 'LOSS'));
  if (mp.length) {
    const predicted = mp.reduce((s, r) => s + (r.pMove > 1 ? r.pMove : r.pMove * 100), 0) / mp.length;
    const realised = mp.filter(r => r.out === 'WIN').length / mp.length * 100;
    L.push(`LIMITBOT move probability: predicted ${predicted.toFixed(1)}% vs realised ${realised.toFixed(1)}% (n=${mp.length})`);
  }
  L.push('');
  L.push('VERDICT');
  L.push('- LIMITBOT quality: ' + _calibVerdict(lb, 'quality'));
  L.push('- Confidence (FIRED and CANDIDATE): ' + _calibVerdict(rows.filter(r => r.group !== 'LIMITBOT'), 'confidence'));
  L.push('- APEX: ' + _calibVerdictTwo(apexRows.filter(r => r.apexOk === true), apexRows.filter(r => r.apexOk === false), 'approved', 'rejected'));
  return L.join('\n');
}
// ── end calibration lab ──

setInterval(() => {
  try { _calibResolveAll(); } catch (e) { console.warn('Calibration resolve skipped:', e.message); }
}, 5 * 60 * 1000).unref();
process.on('exit', () => { try { _calibSave(true); } catch (_) {} });

function logSignalOutcome(symbol, dir, entryPrice, won) {
  for (let i = SIGNAL_JOURNAL.length - 1; i >= 0; i--) {
    const e = SIGNAL_JOURNAL[i];
    if (e.symbol === symbol && e.dir === dir && e.outcome === null &&
        (!entryPrice || Math.abs(e.entry - entryPrice) / (entryPrice || 1) < 0.015)) {
      e.outcome = won ? 'WIN' : 'LOSS';
      e.outcomeTs = Date.now();
      try { if (typeof fs !== 'undefined') writeJsonBounded(SIGNAL_JOURNAL_FILE, SIGNAL_JOURNAL); } catch(_) {}
      return e;
    }
  }
  return null;
}

function getJournalStats(days = 30) {
  const cutoff = Date.now() - days * 864e5;
  const recent = SIGNAL_JOURNAL.filter(e => e.ts >= cutoff);
  const done   = recent.filter(e => e.outcome !== null);
  const wins   = done.filter(e => e.outcome === 'WIN').length;
  const losses = done.filter(e => e.outcome === 'LOSS').length;

  const bySymbol = {}, bySession = {}, byPillar = {4:0,3:0,2:0,1:0,0:0};
  done.forEach(e => {
    if (!bySymbol[e.symbol]) bySymbol[e.symbol] = {w:0,l:0};
    e.outcome==='WIN' ? bySymbol[e.symbol].w++ : bySymbol[e.symbol].l++;
    if (!bySession[e.session]) bySession[e.session] = {w:0,l:0};
    e.outcome==='WIN' ? bySession[e.session].w++ : bySession[e.session].l++;
    if (e.outcome==='WIN') byPillar[e.pillars] = (byPillar[e.pillars]||0)+1;
  });
  const piDone = done.filter(e=>e.preInst), piWins = piDone.filter(e=>e.outcome==='WIN').length;
  // Simple win-rate-based expectancy (no PnL data stored, so use 1:1 R assumption).
  // expectancy = winRate% × 1 − lossRate% × 1  (as a signed dollar-equivalent ratio)
  const _wr = done.length > 0 ? wins / done.length : 0;
  const expectancy = done.length > 0 ? parseFloat(((_wr - (1 - _wr)) * 1).toFixed(2)) : 0;
  return {
    total: recent.length, done: done.length, wins, losses,
    winRate: done.length > 0 ? Math.round(wins/done.length*100) : 0,
    bySymbol, bySession, byPillar,
    preInstWR: piDone.length > 0 ? Math.round(piWins/piDone.length*100) : null,
    avgCert:   recent.length ? Math.round(recent.reduce((s,e)=>s+e.cert,0)/recent.length) : 0,
    expectancy,
  };
}

function formatJournalMessage(days = 7) {
  const s = getJournalStats(days);
  const recent = SIGNAL_JOURNAL.slice(-10).reverse();
  const L = [`📓 <b>Signal Journal — last ${days}d</b>`, ''];
  L.push(`Signals: <b>${s.total}</b> | With outcome: <b>${s.done}</b>`);
  L.push(`Win rate: <b>${s.winRate}%</b> (${s.wins}W/${s.losses}L) | Avg cert: ${s.avgCert}%`);
  if (s.preInstWR !== null) L.push(`Pre-inst entries: <b>${s.preInstWR}%</b> win rate`);
  const top = Object.entries(s.bySymbol).filter(([,v])=>v.w+v.l>=2)
    .map(([sym,v])=>({sym,wr:Math.round(v.w/(v.w+v.l)*100)}))
    .sort((a,b)=>b.wr-a.wr).slice(0,3);
  if (top.length) L.push(`Top symbols: ${top.map(t=>`${t.sym} ${t.wr}%`).join(' · ')}`);
  const sess = Object.entries(s.bySession).filter(([,v])=>v.w+v.l>=2)
    .map(([n,v])=>`${n.replace('_',' ')} ${Math.round(v.w/(v.w+v.l)*100)}%`);
  if (sess.length) L.push(`Sessions: ${sess.join(' · ')}`);
  L.push('', '<b>Last 10:</b>');
  recent.forEach(e => {
    const ic = e.outcome==='WIN'?'✅':e.outcome==='LOSS'?'❌':'⏳';
    const t  = new Date(e.ts).toISOString().slice(11,16);
    L.push(`${ic} ${e.symbol} ${e.dir} [${e.cert}%] ${e.verdict} — ${t} UTC`);
  });
  return L.join('\n');
}

async function sendWeeklyJournalIfDue() {
  if (!TELEGRAM_CHAT_ID) return;
  const now = new Date();
  if (now.getUTCDay() !== 1 || now.getUTCHours() !== 8) return;
  const last = LAST_ALERT.get('weekly_journal') || 0;
  if (Date.now() - last < 20 * 3600 * 1000) return;
  LAST_ALERT.set('weekly_journal', Date.now());
  try {
    await tg('sendMessage', { chat_id: TELEGRAM_CHAT_ID,
      text: formatJournalMessage(7), parse_mode: 'HTML', disable_web_page_preview: true });
    console.log('📓 Weekly journal sent');
  } catch(e) { console.warn('Weekly journal:', e.message); }
}

/* ──────────────── 2. CORRELATION ENGINE ──────────────────────────── */
const CORR_CACHE     = new Map();
const CORR_CACHE_TTL = 5 * 60 * 1000;

async function getCorrelationBias(symbol, dir) {
  const key = `corr_${symbol}_${dir}`;
  const hit = CORR_CACHE.get(key);
  if (hit && Date.now() - hit.ts < CORR_CACHE_TTL) return hit.data;
  try {
    // BTCDominance() already exists in this file
    const dom      = typeof BTCDominance === 'function' ? await BTCDominance() : 52;
    const isBTC    = symbol.startsWith('BTC');
    const isAlt    = !isBTC && !symbol.startsWith('ETH');
    const altSeason = dom < 45, btcSeason = dom > 55;
    let certBoost = 0, warning = null;
    if (isAlt  && dir === 'BUY')  { if (btcSeason) { certBoost = -10; warning = `BTC dominance ${dom.toFixed(1)}% — alts underperform`; } else if (altSeason) certBoost = +8; }
    if (isAlt  && dir === 'SELL') { if (altSeason) { certBoost = -8;  warning = `Alt season — short risk`; } else if (btcSeason) certBoost = +5; }
    if (isBTC  && dir === 'BUY'  && btcSeason) certBoost = +6;
    if (isBTC  && dir === 'SELL' && altSeason) certBoost = +5;
    const data = {
      dom: Math.round(dom * 10) / 10, altSeason, btcSeason,
      certBoost, warning,
      label: altSeason ? '🔥 Alt season' : btcSeason ? '₿ BTC season' : '⚖️ Balanced',
    };
    CORR_CACHE.set(key, { data, ts: Date.now() });
    return data;
  } catch(e) { return { dom: 52, certBoost: 0, warning: null, label: '⚖️ Balanced' }; }
}

function formatCorrelationContext(ctx) {
  if (!ctx) return '';
  const L = ['\n━━━ 🔗 CORRELATION ━━━'];
  L.push(`BTC dominance: <b>${ctx.dom}%</b> — ${ctx.label}`);
  if (ctx.certBoost !== 0) L.push(`Cert ${ctx.certBoost > 0 ? '+' : ''}${ctx.certBoost}% from sector bias`);
  if (ctx.warning) L.push(`⚠️ ${ctx.warning}`);
  return L.join('\n');
}

/* ──────────────── 3. ON-CHAIN DATA ───────────────────────────────── */
const ONCHAIN_CACHE     = new Map();
const ONCHAIN_CACHE_TTL = 10 * 60 * 1000;

async function fetchOnChainData(symbol) {
  const coin = symbol.replace('USDT','').replace('1000','').toLowerCase();
  const key  = `oc_${coin}`;
  const hit  = ONCHAIN_CACHE.get(key);
  if (hit && Date.now() - hit.ts < ONCHAIN_CACHE_TTL) return hit.data;
  const data = { fundingRate: null, oiChange: null, lsRatio: null, whaleSignal: 'NEUTRAL' };
  try {
    const r = await quantumFetch(
      `https://open-api.coinglass.com/public/v2/indicator/funding_rates_oi?symbol=${coin.toUpperCase()}&interval=h4`,
      { timeout: 8000 }).catch(()=>null);
    if (r?.data?.[0]) {
      data.fundingRate = parseFloat(r.data[0].fundingRate || 0) * 100;
      data.oiChange    = parseFloat(r.data[0].oiChangePercent24h || 0);
    }
  } catch(_) {}
  try {
    const r2 = await quantumFetch(
      `https://open-api.coinglass.com/public/v2/indicator/long_short_account?symbol=${coin.toUpperCase()}&interval=h4&limit=1`,
      { timeout: 8000 }).catch(()=>null);
    if (r2?.data?.[0]) data.lsRatio = parseFloat(r2.data[0].longShortRatio || 1);
  } catch(_) {}
  if (data.fundingRate !== null) {
    if (data.fundingRate < -0.05)    data.whaleSignal = 'BEARISH';
    else if (data.fundingRate > 0.08) data.whaleSignal = 'REVERSAL_RISK';
    else if (data.fundingRate > 0.03) data.whaleSignal = 'BULLISH';
  }
  ONCHAIN_CACHE.set(key, { data, ts: Date.now() });
  return data;
}

function onChainAgreesWithSignal(oc, dir) {
  if (!oc) return true;
  if (dir === 'BUY'  && oc.lsRatio > 1.8)   return false; // crowded longs
  if (dir === 'SELL' && oc.lsRatio < 0.6)    return false; // crowded shorts
  if (dir === 'BUY'  && oc.fundingRate > 0.1) return false; // everyone already long
  return true;
}

function formatOnChainContext(oc, dir) {
  if (!oc || (oc.fundingRate === null && oc.lsRatio === null)) return '';
  const L = ['\n━━━ ⛓️ ON-CHAIN ━━━'];
  if (oc.fundingRate !== null) {
    const ic = Math.abs(oc.fundingRate) > 0.05 ? '🔴' : Math.abs(oc.fundingRate) > 0.02 ? '🟡' : '🟢';
    L.push(`${ic} Funding: <b>${oc.fundingRate > 0 ? '+' : ''}${oc.fundingRate.toFixed(4)}%</b>`);
  }
  if (oc.oiChange !== null) L.push(`OI 24h: ${oc.oiChange > 0 ? '+' : ''}${oc.oiChange.toFixed(1)}%`);
  if (oc.lsRatio !== null) {
    const ic = oc.lsRatio > 1.5 || oc.lsRatio < 0.7 ? '⚠️' : '✅';
    L.push(`${ic} L/S ratio: <b>${oc.lsRatio.toFixed(2)}</b>${oc.lsRatio > 1.5 ? ' — crowded longs' : oc.lsRatio < 0.7 ? ' — crowded shorts' : ''}`);
  }
  if (!onChainAgreesWithSignal(oc, dir)) L.push(`⚠️ On-chain conflicts with ${dir} signal`);
  return L.join('\n');
}

/* ──────────────── 4. SOCIAL SENTIMENT ────────────────────────────── */
const SOCIAL_CACHE     = new Map();
const SOCIAL_CACHE_TTL = 8 * 60 * 1000;

async function fetchEnhancedSocialSentiment(symbol) {
  const coin = symbol.replace('USDT','').replace('1000','').toLowerCase();
  const key  = `soc_${coin}`;
  const hit  = SOCIAL_CACHE.get(key);
  if (hit && Date.now() - hit.ts < SOCIAL_CACHE_TTL) return hit.data;
  const data = { score: null, volume: null, spike: false, sentiment: 'NEUTRAL', warning: null };
  try {
    const r = await quantumFetch(
      `https://lunarcrush.com/api4/public/coins/${coin}/v1`,
      { timeout: 8000 }).catch(()=>null);
    if (r?.data) {
      const d = r.data;
      data.score     = d.galaxy_score ? Math.round(d.galaxy_score) : null;
      data.volume    = d.social_volume_24h || null;
      data.sentiment = d.sentiment >= 3.5 ? 'BULLISH' : d.sentiment <= 2.5 ? 'BEARISH' : 'NEUTRAL';
      if (d.social_volume_24h && d.average_sentiment) {
        const ratio = d.social_volume_24h / (d.average_sentiment * 1000 + 1);
        data.spike   = ratio > 3;
        if (data.spike) data.warning = `Social spike ${ratio.toFixed(1)}x avg — retail FOMO/panic`;
      }
    }
  } catch(_) {}
  SOCIAL_CACHE.set(key, { data, ts: Date.now() });
  return data;
}

/* ──────────────── 5. BACKTESTER ──────────────────────────────────── */
async function backtestSymbol(symbol, lookbackDays = 30) {
  try {
    const lim      = Math.min(200, lookbackDays * 24);
    const [c1h, c4h] = await Promise.all([
      fetchCandlesCached(symbol, '1h', lim).catch(()=>null),
      fetchCandlesCached(symbol, '4h', Math.floor(lim/4)).catch(()=>null),
    ]);
    if (!c1h || c1h.length < 50) return null;
    let wins = 0, losses = 0, skipped = 0;
    for (let i = 30; i < c1h.length - 10; i++) {
      const sl    = c1h.slice(0, i);
      const price = sl[sl.length-1].c;
      const wy    = getWyckoffContext(c4h ? c4h.slice(0, Math.floor(i/4)) : sl);
      const st    = getStructureContext(sl);
      const tr    = getFailureTrapContext(sl);
      const bull  = wy.bias==='BUY' || st.choch || (tr.trapped && tr.direction==='BUY');
      const bear  = wy.bias==='SELL'|| (tr.trapped && tr.direction==='SELL');
      if (!bull && !bear) { skipped++; continue; }
      const dir = bull ? 'BUY' : 'SELL';
      const atr = sl.slice(-14).reduce((a,c)=>a+(c.h-c.l),0)/14;
      const slv = dir==='BUY' ? price-atr*1.5 : price+atr*1.5;
      const tp  = dir==='BUY' ? price+atr*3.75 : price-atr*3.75;
      let out = 'PENDING';
      for (let j = i+1; j < Math.min(i+11, c1h.length); j++) {
        const fc = c1h[j];
        if (dir==='BUY')  { if(fc.l<=slv){out='LOSS';break;} if(fc.h>=tp){out='WIN';break;} }
        else              { if(fc.h>=slv){out='LOSS';break;} if(fc.l<=tp){out='WIN';break;} }
      }
      if (out==='WIN') wins++; else if (out==='LOSS') losses++; else skipped++;
    }
    const total = wins+losses;
    return { symbol, wins, losses, total, winRate: total>0?Math.round(wins/total*100):0, skipped, period: `${lookbackDays}d`, candles: c1h.length };
  } catch(e) { console.warn('Backtest error:', e.message); return null; }
}

function formatBacktestResult(bt) {
  if (!bt) return '❌ Backtest failed — insufficient data';
  return [
    `🧪 <b>Backtest: ${bt.symbol}</b> (${bt.period}, ${bt.candles} candles)`,
    `Trades: <b>${bt.total}</b> | Skipped: ${bt.skipped}`,
    `Wins: <b>${bt.wins}</b> | Losses: <b>${bt.losses}</b>`,
    `Win rate: <b>${bt.winRate}%</b>`,
    ``,
    `<i>Wyckoff + structure + trap rules on 1h. 1:2.5 R:R.</i>`,
  ].join('\n');
}

