// ── Wrap quantumConsensus to use adaptive weights ──────────────────────────
// Stores the current regime on the instance so quantumConsensus can access it
// (regime is passed down from generateEnhancedQuantumSignal's macroRegime var)

const _origQuantumConsensus = EnhancedQuantumSignalGenerator.prototype.quantumConsensus;
EnhancedQuantumSignalGenerator.prototype.quantumConsensus = function(agents, regime) {
  // If adaptive weights have enough training data, substitute them
  const weights = getAdaptiveWeights(regime || this._currentRegime);

  // Override the hardcoded agentWeights inside the original method
  // by temporarily patching the instance
  this._adaptiveWeights = weights;
  const result = _origQuantumConsensus.call(this, agents);
  return result;
};

// Patch the original quantumConsensus to check for adaptive weights
const _patchedQC = function(agents) {
  const agentWeights = this._adaptiveWeights || {
    PriceAction:2.5,Structure:2.2,OrderFlow:1.8,Volume:1.5,Momentum:1.3,
    Quantum:1.0,Volatility:0.3,OrderBlock:2.8,CVD:2.4,Wyckoff:2.0,
    FundingRate:1.6,HiddenDiv:1.4,Deception:3.2,Reflexivity:2.2,
    EntropyGradient:1.8,CriticalState:1.6,Adversarial:1.5,CIF:1.3,
    RQA:2.6,Thermodynamic:2.4,LempelZiv:2.0,Kuramoto:2.2,
    StochasticResonance:1.8,TickBias:1.1,SMCI:2.6,OrderBookImbalance:2.0,
  };

  let buyScore = 0, sellScore = 0, totalWeight = 0;
  let votingAgentCount = 0;
  const breakdown = {};

  for (const agent of agents) {
    if (!agent || !agent.label) continue;
    const w = agentWeights[agent.label] || 1.0;
    const voted = agent.direction !== 'NEUTRAL' && (agent.confidence || 0) > 0;
    if (voted) {
      const effectiveWeight = w * agent.confidence;
      totalWeight += w;
      votingAgentCount++;
      if (agent.direction === 'BUY')  buyScore  += effectiveWeight;
      else if (agent.direction === 'SELL') sellScore += effectiveWeight;
    }
    breakdown[agent.label] = { dir: agent.direction, conf: agent.confidence || 0, w };
  }

  if (totalWeight === 0 || votingAgentCount === 0) {
    return { direction: 'NEUTRAL', confidence: 0, breakdown, delta: 0 };
  }

  const buyNorm  = buyScore  / totalWeight;
  const sellNorm = sellScore / totalWeight;
  const delta    = Math.abs(buyNorm - sellNorm);

  let direction = 'NEUTRAL', confidence = 0, signal_tier = 'NEUTRAL';

  if (buyNorm > sellNorm) {
    direction  = 'BUY';
    confidence = clamp(buyNorm, 0, 1);
  } else if (sellNorm > buyNorm) {
    direction  = 'SELL';
    confidence = clamp(sellNorm, 0, 1);
  } else {
    direction  = 'NEUTRAL';
    confidence = Math.max(buyNorm, sellNorm);
  }

  signal_tier = delta > 0.55 ? 'STRONG'
              : delta > 0.35 ? 'MODERATE'
              : delta > 0.15 ? 'EARLY_WARNING'
              : 'SPECULATIVE';

  return { direction, confidence, delta, signal_tier, breakdown, votingAgentCount, totalWeight };
};

EnhancedQuantumSignalGenerator.prototype.quantumConsensus = _patchedQC;

// ── Patch generateEnhancedQuantumSignal to:
//    A) Store current regime for adaptive weights
//    B) Add OrderBookImbalance agent (Upgrade 4)
//    C) Apply precision position sizing (Upgrade 5)
//    D) Apply verdict calibration boost to quantum_confidence (Upgrade 2)
const _origGenSignal = EnhancedQuantumSignalGenerator.prototype.generateEnhancedQuantumSignal;
EnhancedQuantumSignalGenerator.prototype.generateEnhancedQuantumSignal = async function(symbol, timeframe) {
  // A) Fetch macro regime and expose to quantumConsensus via instance property
  try {
    const mr = await macro2Y(symbol).catch(() => null);
    this._currentRegime = mr?.regime || null;
  } catch(_) {
    this._currentRegime = null;
  }

  // B) Pre-fetch order book imbalance agent BEFORE calling original
  const obAgent = getOrderBookImbalanceAgent(symbol);

  // Call original signal generation
  const signal = await _origGenSignal.call(this, symbol, timeframe);
  if (!signal) return null;

  try {
    // Add OB agent to agent_breakdown for Bayesian learning
    if (signal.agent_breakdown) {
      signal.agent_breakdown['OrderBookImbalance'] = {
        dir:        obAgent.direction,
        conf:       obAgent.confidence,
        w:          getAdaptiveWeights(this._currentRegime)['OrderBookImbalance'] || 2.0,
        imbalance:  obAgent.imbalance,
        source:     obAgent.source,
      };
    }

    // D) Verdict calibration boost — use the signal tier as a proxy for verdict
    const verdictProxy   = signal.signal_tier || 'SPECULATIVE';
    const verdictCal     = getVerdictCalibration(verdictProxy, 8);
    const verdictCalBoost = verdictCal.calibrationBoost || 0;

    // Blend calibration into quantum_confidence (capped to ±15%)
    if (verdictCalBoost !== 0) {
      signal.quantum_confidence = clamp(
        signal.quantum_confidence + verdictCalBoost,
        0, 100
      );
      signal.verdict_calibration = {
        verdict:      verdictProxy,
        accuracy:     verdictCal.accuracy,
        sampleSize:   verdictCal.sampleSize,
        boost:        verdictCalBoost,
      };
    }

    // C) Precision position sizing
    const precisionSize = computePrecisionPositionSize(
      signal.position_size,
      signal.quantum_confidence,
      verdictProxy,
      signal.agent_breakdown,
      this._currentRegime
    );
    signal.position_size           = precisionSize.finalSize;
    signal.precision_size_breakdown = precisionSize.breakdown;
    signal.precision_size_label     = precisionSize.label;
    signal.size_multiplier          = precisionSize.multiplier;

    // Track for /status display
    PRECISION_SIZING_STATS.lastMultiplier = precisionSize.multiplier;
    PRECISION_SIZING_STATS.lastVerdict    = verdictProxy;
    PRECISION_SIZING_STATS.lastCert       = signal.quantum_confidence;
    PRECISION_SIZING_STATS.count++;

    // Store macro regime on signal for Bayesian learning later
    signal.macro_regime = this._currentRegime;
    signal.adaptive_weights_active = ADAPTIVE_WEIGHTS.tradeCount >= MIN_TRADES_TO_ADAPT;
    signal.adaptive_trade_count    = ADAPTIVE_WEIGHTS.tradeCount;

  } catch(patchErr) {
    console.error('Adaptive suite patch error:', patchErr.message);
  }

  return signal;
};

