/* ████████████████████████████████████████████████████████████████████████████
   ADVANCED APEX TOTAL LIQUIDITY ENGINE (ATLAS)
   ─────────────────────────────────────────────────────────────────────────
   The most sophisticated liquidity intelligence system ever built.
   Detects the TOTAL ACCUMULATED LIQUIDITY across all timeframes,
   all price levels, and all market participants before the real
   institutional long-term move begins.

   This goes beyond pool detection. It quantifies:
   ▸ STOP ORDER DENSITY   — volume of stops at each price cluster
   ▸ LEVERAGE OVERHANG    — total leveraged positions that need to be liquidated
   ▸ RETAIL TRAP DENSITY  — how many retail traders are positioned incorrectly
   ▸ OPTIONS MAX PAIN     — where options dealers will force price to expire
   ▸ WEEKLY/MONTHLY LEVELS — macro liquidity that institutions are targeting
   ▸ CUMULATIVE ORDER IMBALANCE — bid/ask imbalance over time = directional fuel
   ▸ SMART MONEY ACCUMULATION INDEX — on-chain + CVD evidence of institutional loading

   ATLAS OUTPUT:
   totalLiquidityScore  0-100  (how much fuel is available)
   sweepCompletionPct   0-100  (how much of that fuel is already consumed)
   realMoveReadiness    0-100  (combined: are we at the start of the real move?)
   institutionalTarget  price  (where institutions are actually targeting)
   expectedMoveSize     %      (how large the real move will be)
   ████████████████████████████████████████████████████████████████████████████ */

const ATLAS_CACHE     = new Map();
const ATLAS_CACHE_TTL = 90 * 1000; // 90 seconds

async function computeATLAS(symbol, price, dir, candles, instCtx) {
  const key = `atlas_${symbol}_${dir}_${instCtx ? 'context' : 'liquidity'}`;
  const hit = ATLAS_CACHE.get(key);
  if (hit && Date.now() - hit.ts < ATLAS_CACHE_TTL) return hit.data;

  try {
    if (!candles || candles.length < 30 || !price) return null;

    const atr    = candles.slice(-14).reduce((a, c) => a + (c.h - c.l), 0) / 14;
    const avgVol = candles.slice(-20).reduce((s, c) => s + (c.v || 0), 0) / 20 || 1;
    if (!atr || atr <= 0) return null;

    // ── Layer 1: Multi-TF Stop Order Density Map ──────────────────────────
    // Build pool map from 3 timeframes simultaneously
    const liqMap = await buildFullLiquidityMap(symbol, price, dir).catch(() => ({
      pools: [], totalPools: 0, strongPools: [],
    }));

    const allPools    = liqMap.pools || [];
    const strongPools = liqMap.strongPools || [];

    // Total stop density: sum of pool strength weighted by proximity
    let stopDensityTotal = 0;
    let stopDensityMap   = [];
    for (const pool of allPools) {
      const distPct  = Math.abs(price - pool.level) / price;
      // Proximity weight: closer pools = more pressure on current price
      const proxW    = Math.max(0.1, 1 - distPct * 6);
      const density  = pool.strength * proxW * pool.weight;
      stopDensityTotal += density;
      stopDensityMap.push({ level: pool.level, density: Math.round(density * 10) / 10, sources: pool.sources });
    }
    const normalizedStopDensity = Math.min(100, stopDensityTotal / 2);

    // ── Layer 2: Leverage Overhang Index ──────────────────────────────────
    // Estimated from: funding rate × open interest trend × position skew
    const fundingData = await fetchFundingRateAndOI(symbol).catch(() => null);
    const frPct       = (fundingData?.fundingRate || 0) * 100;
    const oi          = fundingData?.openInterest || 0;

    // Funding rate intensity: how extreme is current leverage imbalance?
    const frIntensity   = Math.min(100, Math.abs(frPct) / 0.12 * 100);
    // OI growth proxy: high OI relative to price volatility = leverage overhang
    const oiOverhang    = Math.min(100, (oi / (price || 1)) * atr * 0.5);
    const leverageScore = (frIntensity * 0.6 + oiOverhang * 0.4);

    // ── Layer 3: Retail Trap Density ──────────────────────────────────────
    // Retail traps = levels where price formed obvious patterns that retail
    // entered in the wrong direction. When swept → cascading exits.
    let retailTrapScore = 0;

    // Double top / double bottom proximity
    const recentHighs = candles.slice(-40).map(c => c.h).sort((a, b) => b - a).slice(0, 3);
    const recentLows  = candles.slice(-40).map(c => c.l).sort((a, b) => a - b).slice(0, 3);

    // If recent highs are clustered (double top) = retail sold there = buy liquidity above
    const highCluster = recentHighs[0] > 0 && (recentHighs[0] - recentHighs[1]) / recentHighs[0] < 0.015;
    const lowCluster  = recentLows[0]  > 0 && (recentLows[1]  - recentLows[0])  / recentLows[0]  < 0.015;

    if (dir === 'BUY'  && lowCluster)  retailTrapScore += 40; // retail sold the double bottom
    if (dir === 'SELL' && highCluster) retailTrapScore += 40; // retail bought the double top

    // Round numbers = retail stop magnets
    const nearestRound = Math.round(price / (atr * 5)) * (atr * 5);
    const distToRound  = Math.abs(price - nearestRound) / price;
    if (distToRound < 0.03) retailTrapScore += 25; // within 3% of a round number
    if (distToRound < 0.01) retailTrapScore += 15; // within 1% = very close

    // Retail FOMO indicator: recent fast move = retail chasing = stops above/below
    const priceVelocity = Math.abs(candles[candles.length-1].c - candles[candles.length-8].c) / price;
    if (priceVelocity > 0.05) retailTrapScore += 20; // 5%+ fast move = retail trapped

    const normalizedRetailTrap = Math.min(100, retailTrapScore);

    // ── Layer 4: Cumulative Order Flow Imbalance ──────────────────────────
    // CVD over last 20 candles tells us: is institutional money accumulating?
    const cvdScore = (() => {
      let cvd = 0;
      for (const c of candles.slice(-20)) {
        const body = c.c - c.o;
        cvd += body * (c.v || 0);
      }
      // Normalize: positive CVD = buying pressure (bullish)
      const maxPossible = candles.slice(-20).reduce((s, c) => s + Math.abs(c.c - c.o) * (c.v || 0), 0) || 1;
      return (cvd / maxPossible) * 100; // -100 to +100
    })();

    // Align CVD with direction
    const cvdAligned = dir === 'BUY' ? cvdScore : -cvdScore;
    const normalizedCVD = Math.max(0, Math.min(100, 50 + cvdAligned * 0.5));

    // ── Layer 5: Smart Money Accumulation Index ───────────────────────────
    // Volume absorption pattern: high volume at the bottom/top + price NOT moving
    // = smart money absorbing retail panic = pre-move loading
    let smartMoneyScore = 0;
    const last5Vols  = candles.slice(-5).map(c => c.v || 0);
    const last5Moves = candles.slice(-5).map(c => Math.abs(c.c - c.o) / (c.h - c.l || 1));

    for (let i = 0; i < 5; i++) {
      // High volume + small body = absorption (smart money catching retail orders)
      if (last5Vols[i] > avgVol * 1.5 && last5Moves[i] < 0.35) {
        smartMoneyScore += 20; // absorption candle
      }
    }

    // Wick rejection at key level
    const lastC = candles[candles.length - 1];
    const lastWickRatio = dir === 'BUY'
      ? (lastC.c - lastC.l) / (lastC.h - lastC.l || 1)
      : (lastC.h - lastC.c) / (lastC.h - lastC.l || 1);
    if (lastWickRatio > 0.70) smartMoneyScore += 25; // strong rejection wick

    const normalizedSmartMoney = Math.min(100, smartMoneyScore);

    // ── ATLAS Composite Score ─────────────────────────────────────────────
    const atlasScore = Math.round(
      normalizedStopDensity  * 0.28 +   // stop density = 28%
      leverageScore          * 0.22 +   // leverage overhang = 22%
      normalizedRetailTrap   * 0.18 +   // retail traps = 18%
      normalizedCVD          * 0.17 +   // order flow = 17%
      normalizedSmartMoney   * 0.15     // smart money = 15%
    );

    // ── Sweep Completion % ────────────────────────────────────────────────
    // Clamp exchange/context counts to the observed pool count; missing context
    // is treated as unknown, never as a successful institutional confirmation.
    const lepdData = instCtx?.lepd || null;
    const rmeeData = instCtx?.rmee || null;
    const totalPoolsMapped = allPools.length;
    const rawSwept = Number(rmeeData?.poolsSwept ?? lepdData?.poolsSwept ?? 0);
    const poolsSweptCount = Number.isFinite(rawSwept)
      ? Math.max(0, Math.min(totalPoolsMapped, rawSwept)) : 0;
    const sweepCompletionPct = totalPoolsMapped > 0
      ? Math.round((poolsSweptCount / totalPoolsMapped) * 100) : 0;

    // ── Real Move Readiness (fixed 100-point evidence model) ───────────────
    const lepdState = String(lepdData?.state || '').toUpperCase();
    const rmeeMode = String(rmeeData?.mode || '').toUpperCase();
    const lepdPerfect = ['PERFECT_EXHAUSTION', 'STRONG_EXHAUSTION'].includes(lepdState);
    const lepdPartial = !!lepdData && /EXHAUST|SWEEP|PARTIAL/.test(lepdState);
    const rmeeConfirmed = rmeeMode === 'REAL_MOVE_CONFIRMED';
    const rmeePartial = !!rmeeData && rmeeMode !== 'UNKNOWN' && rmeeMode !== 'NONE';
    const macro2YDir = String(instCtx?.macro2Y?.direction || 'NEUTRAL').toUpperCase();
    const macroKnown = !!instCtx?.macro2Y?.direction;
    const macroAligned = macro2YDir === dir;
    const sweepPoints = totalPoolsMapped > 0 ? sweepCompletionPct * 0.30 : 0;
    const lepdPoints = lepdPerfect ? 20 : lepdPartial ? 8 : 0;
    const rmeePoints = rmeeConfirmed ? 20 : rmeePartial ? 8 : 0;
    const macroPoints = macroKnown && macroAligned ? 10 : 0;
    const cvdPoints = Math.max(0, Math.min(10, ((cvdAligned + 100) / 200) * 10));
    const smartMoneyPoints = normalizedSmartMoney * 0.10;
    const realMoveReadiness = Math.round(Math.max(0, Math.min(100,
      sweepPoints + lepdPoints + rmeePoints + macroPoints + cvdPoints + smartMoneyPoints
    )));
    const readinessDataComplete = totalPoolsMapped > 0 && !!lepdData && !!rmeeData && macroKnown;
    const readinessReasons = [];
    if (!totalPoolsMapped) readinessReasons.push('No mapped liquidity pools');
    if (!lepdData) readinessReasons.push('LEPD confirmation unavailable');
    else if (!lepdPerfect) readinessReasons.push('LEPD exhaustion not confirmed');
    if (!rmeeData) readinessReasons.push('RMEE confirmation unavailable');
    else if (!rmeeConfirmed) readinessReasons.push('Real-move confirmation pending');
    if (!macroKnown) readinessReasons.push('Two-year macro context unavailable');
    else if (!macroAligned) readinessReasons.push('Two-year macro not aligned');
    if (cvdAligned <= 0) readinessReasons.push('Directional order flow not positive');

    // ── Directional Institutional Target ───────────────────────────────────
    // The original target incorrectly selected the liquidity pool behind price
    // (below price for BUY / above price for SELL). Select opposing liquidity
    // in the projected move direction instead.
    const targetMap = await buildFullLiquidityMap(symbol, price, dir === 'BUY' ? 'SELL' : 'BUY').catch(() => ({ pools: [], strongPools: [] }));
    const targetPools = (targetMap?.strongPools?.length ? targetMap.strongPools : (targetMap?.pools || []))
      .filter(p => Number.isFinite(Number(p.level)) && (dir === 'BUY' ? Number(p.level) > price : Number(p.level) < price))
      .sort((a, b) => dir === 'BUY' ? Number(a.level) - Number(b.level) : Number(b.level) - Number(a.level));
    const liquidityTarget = targetPools[0]?.level || null;
    const fallbackTarget = dir === 'BUY' ? price + atr * 2.5 : price - atr * 2.5;
    const institutionalTarget = liquidityTarget || fallbackTarget;
    const targetDistance = Math.abs(institutionalTarget - price);
    const expectedAtrMultiple = Math.round((targetDistance / atr) * 10) / 10;
    const expectedMovePct = Math.round((targetDistance / price) * 100 * 100) / 100;
    const realMoveTarget = Math.round(institutionalTarget * 100000) / 100000;

    // ── ATLAS Tier Classification ──────────────────────────────────────────
    let atlasTier, atlasLabel, atlasCertBoost;

    if (readinessDataComplete && atlasScore >= 80 && realMoveReadiness >= 70) {
      atlasTier      = 'APEX_PRIME';
      atlasCertBoost = 25;
      atlasLabel     = `🏔️🔥 APEX PRIME — Total liquidity ${atlasScore}/100 + ${realMoveReadiness}% ready. THIS IS THE REAL MOVE ZONE.`;
    } else if (readinessDataComplete && atlasScore >= 65 && realMoveReadiness >= 50) {
      atlasTier      = 'APEX';
      atlasCertBoost = 18;
      atlasLabel     = `🏔️ APEX — ${atlasScore}/100 fuel | ${realMoveReadiness}% ready. Massive institutional setup loading.`;
    } else if (atlasScore >= 50) {
      atlasTier      = 'HIGH';
      atlasCertBoost = 10;
      atlasLabel     = `🔥 HIGH FUEL — ${atlasScore}/100 | ${realMoveReadiness}% ready. Significant move expected post-sweep.`;
    } else if (atlasScore >= 30) {
      atlasTier      = 'MODERATE';
      atlasCertBoost = 4;
      atlasLabel     = `📊 MODERATE — ${atlasScore}/100 fuel. Standard move expected.`;
    } else {
      atlasTier      = 'LOW';
      atlasCertBoost = 0;
      atlasLabel     = `💧 LOW FUEL — ${atlasScore}/100. Limited liquidity for institutional interest.`;
    }

    // Top stop levels by density
    const topLevels = stopDensityMap
      .sort((a, b) => b.density - a.density)
      .slice(0, 4);

    const data = {
      symbol,
      atlasScore,
      atlasTier,
      atlasCertBoost,
      atlasLabel,
      sweepCompletionPct,
      realMoveReadiness,
      readinessDataComplete,
      readinessReasons,
      institutionalTarget:  Math.round((institutionalTarget || price) * 100000) / 100000,
      expectedMovePct,
      expectedAtrMultiple,
      realMoveTarget,
      topLevels,
      components: {
        stopDensity:     Math.round(normalizedStopDensity),
        leverageOverhang: Math.round(leverageScore),
        retailTrap:      Math.round(normalizedRetailTrap),
        orderFlow:       Math.round(normalizedCVD),
        smartMoney:      Math.round(normalizedSmartMoney),
      },
      fundingRate:    Math.round(frPct * 1000) / 1000,
      totalPools:     totalPoolsMapped,
      poolsSwept:     poolsSweptCount,
      macroAligned,
      rmeeConfirmed,
      lepdConfirmed: lepdPerfect,
      cvdAligned:     Math.round(cvdAligned),
      direction:      dir,
    };

    ATLAS_CACHE.set(key, { data, ts: Date.now() });
    return data;
  } catch(e) {
    console.warn('computeATLAS error:', e.message);
    return null;
  }
}

async function buildATLASTradePlan(symbol) {
  const price = await fetchLivePrice(symbol).catch(() => null);
  const candles = await fetchCandlesCached(symbol, '1h', 100).catch(() => null);
  if (!price || !candles || candles.length < 30) {
    return { ok: false, reason: 'Live price or sufficient 1h candle history is unavailable.' };
  }
  const atr = candles.slice(-14).reduce((sum, c) => sum + (Number(c.h) - Number(c.l)), 0) / 14;
  if (!Number.isFinite(atr) || atr <= 0) return { ok: false, reason: 'ATR could not be calculated from current candles.' };

  const candidates = await Promise.all(['BUY', 'SELL'].map(async direction => {
    const instCtx = await buildInstitutionalContextFull(symbol, price, direction).catch(() => null);
    const atlas = await computeATLAS(symbol, price, direction, candles, instCtx);
    return { direction, instCtx, atlas };
  }));
  const ranked = candidates.filter(x => x.atlas).sort((a, b) =>
    (b.atlas.realMoveReadiness * 0.65 + b.atlas.atlasScore * 0.35) -
    (a.atlas.realMoveReadiness * 0.65 + a.atlas.atlasScore * 0.35)
  );
  if (!ranked.length) return { ok: false, reason: 'ATLAS could not calculate both directional reports.' };
  const chosen = ranked[0];
  const other = ranked[1];
  const atlas = chosen.atlas;
  const direction = chosen.direction;
  const combined = atlas.realMoveReadiness * 0.65 + atlas.atlasScore * 0.35;
  const otherCombined = other ? other.atlas.realMoveReadiness * 0.65 + other.atlas.atlasScore * 0.35 : 0;
  if (atlas.atlasScore < 50) return { ok: false, reason: `Liquidity fuel is only ${atlas.atlasScore}/100; minimum for a manual setup is 50.` , candidates };
  if (atlas.realMoveReadiness < 55) return { ok: false, reason: `Readiness is ${atlas.realMoveReadiness}/100; minimum is 55. ${atlas.readinessReasons?.slice(0,3).join('; ') || ''}`, candidates };
  if (combined - otherCombined < 7) return { ok: false, reason: 'BUY and SELL readings are too close; direction is ambiguous. Wait for clearer separation.', candidates };
  if (atlas.cvdAligned < 10) return { ok: false, reason: `Directional order flow is not aligned (CVD alignment ${atlas.cvdAligned}).`, candidates };

  const inst = _institutionalDirectionConfirmation(chosen.instCtx, direction);
  if (!inst.phaseConfirmed && !inst.structureConfirmed) {
    return { ok: false, reason: `Neither institutional phase nor market structure confirms ${direction}. ${inst.detail}`, candidates };
  }
  const regimeCandles = chosen.instCtx?.candles || candles;
  const regime = regimeCandles.length >= 30 ? assessMarketRegime(regimeCandles, direction) : null;
  if (regime?.tradeable === false) return { ok: false, reason: `Market regime blocks the entry: ${regime.regime || 'untradeable'} — ${regime.reason || 'wait for better conditions'}.`, candidates };

  // Market entry uses the live quote. Structural stop sits beyond the recent
  // 12-bar swing with a volatility buffer; no entry is emitted if geometry fails.
  const recent = candles.slice(-12);
  const entry = Number(price);
  const stop = direction === 'BUY'
    ? Math.min(...recent.map(c => Number(c.l))) - atr * 0.25
    : Math.max(...recent.map(c => Number(c.h))) + atr * 0.25;
  const risk = Math.abs(entry - stop);
  const riskPct = risk / entry * 100;
  if (!(entry > 0 && stop > 0 && risk > 0)) return { ok: false, reason: 'Could not build valid entry/stop geometry.', candidates };
  if (riskPct > 2.5) return { ok: false, reason: `Structural stop is too wide (${riskPct.toFixed(2)}%); maximum allowed for this intraday plan is 2.50%.`, candidates };

  const targetMap = await buildFullLiquidityMap(symbol, price, direction === 'BUY' ? 'SELL' : 'BUY').catch(() => ({ pools: [], strongPools: [] }));
  const pools = (targetMap?.strongPools?.length ? targetMap.strongPools : (targetMap?.pools || []))
    .filter(p => Number.isFinite(Number(p.level)) && (direction === 'BUY' ? Number(p.level) > entry : Number(p.level) < entry))
    .sort((a, b) => direction === 'BUY' ? Number(a.level) - Number(b.level) : Number(b.level) - Number(a.level));
  const rrFor = target => Math.abs(Number(target) - entry) / risk;
  const liquidityTP = pools.find(p => rrFor(p.level) >= 1.5)?.level || null;
  const tp1 = direction === 'BUY' ? entry + risk : entry - risk;
  const tp2 = direction === 'BUY' ? entry + risk * 2 : entry - risk * 2;
  const tp3 = liquidityTP || (direction === 'BUY' ? entry + risk * 3 : entry - risk * 3);
  const rr = rrFor(tp3);
  if (rr < 1.5) return { ok: false, reason: 'The nearest usable liquidity target does not provide at least 1.5R. No trade plan issued.', candidates };
  const roundPrice = n => Number(Number(n).toPrecision(8));
  return {
    ok: true, symbol, direction, price: roundPrice(entry), entry: roundPrice(entry), stopLoss: roundPrice(stop),
    takeProfits: [roundPrice(tp1), roundPrice(tp2), roundPrice(tp3)],
    riskPct: Number(riskPct.toFixed(2)), riskReward: Number(rr.toFixed(2)),
    targetSource: liquidityTP ? 'nearest qualifying opposing liquidity pool' : '3R structural fallback',
    atlas, combinedScore: Math.round(combined), institutional: inst, regime,
  };
}

function formatATLAS(atlas, dir) {
  if (!atlas) return '';

  const L = ['\n━━━ 🏔️ ATLAS: TOTAL LIQUIDITY ENGINE ━━━'];
  L.push(`<b>${atlas.atlasLabel}</b>`);

  // Score bars
  const scoreBar = '█'.repeat(Math.max(0,Math.min(10,Math.round(Number(atlas.atlasScore)||0)/10))) + '░'.repeat(Math.max(0,10-Math.max(0,Math.min(10,Math.round(Number(atlas.atlasScore)||0)/10))));
  const readyBar = '█'.repeat(Math.max(0,Math.min(10,Math.round(Number(atlas.realMoveReadiness)||0)/10))) + '░'.repeat(Math.max(0,10-Math.max(0,Math.min(10,Math.round(Number(atlas.realMoveReadiness)||0)/10))));
  L.push(`Fuel:     [${scoreBar}] ${atlas.atlasScore}/100`);
  L.push(`Readiness:[${readyBar}] ${atlas.realMoveReadiness}/100`);

  // Sweep progress
  L.push(`Sweep: ${atlas.poolsSwept}/${atlas.totalPools} pools consumed (${atlas.sweepCompletionPct}%)`);
  L.push(`Readiness evidence: ${atlas.readinessDataComplete ? 'complete' : 'partial / missing context'}`);
  if (atlas.readinessReasons?.length) L.push(`Pending: ${atlas.readinessReasons.slice(0, 4).join(' · ')}`);

  // Components
  const c = atlas.components;
  L.push(`📊 Stop density: ${c.stopDensity} | Leverage: ${c.leverageOverhang} | Retail traps: ${c.retailTrap}`);
  L.push(`📊 Order flow: ${c.orderFlow} | Smart money: ${c.smartMoney} | Macro: ${atlas.macroAligned ? '✅' : '❌'}`);

  // Key levels
  if (atlas.topLevels?.length) {
    L.push(`🎯 Key sweep targets: ${atlas.topLevels.slice(0,3).map(l=>`<code>${l.level}</code>[${l.sources||'?'}]`).join(' → ')}`);
  }

  // Institutional target and real move size
  L.push(`🏛️ Institutional target: <code>${atlas.institutionalTarget}</code>`);
  L.push(`📈 Expected real move: <b>${dir==='BUY'?'+':'−'}${atlas.expectedMovePct}%</b> (${atlas.expectedAtrMultiple}× ATR) → <code>${atlas.realMoveTarget}</code>`);

  // APEX PRIME alert
  if (atlas.atlasTier === 'APEX_PRIME') {
    L.push(`\n🏔️🔥 <b>APEX PRIME CONFLUENCE:</b>`);
    L.push(`All liquidity layers aligned + sweep ${atlas.sweepCompletionPct}% complete.`);
    L.push(`When RMEE confirms REAL_MOVE_CONFIRMED: this is the highest-conviction setup on earth.`);
  }

  return L.join('\n');
}


/* ── Wire ATLAS into buildInstitutionalContextFull ──────────────────────── */
const _origBuildInst_atlas = buildInstitutionalContextFull;
buildInstitutionalContextFull = async function(symbol, price, dir) {
  const base = await _origBuildInst_atlas(symbol, price, dir);
  try {
    const candles = base?._sharedCandles || await fetchCandlesCached(symbol, '1h', 80).catch(() => null);
    if (candles && price && dir) {
      const atlas = await computeATLAS(symbol, price, dir, candles, base).catch(() => null);
      if (base && atlas) {
        base.atlas  = atlas;
        base._atlas = true;
      }
    }
  } catch(e) { console.warn('ATLAS wiring error:', e.message); }
  return base;
};

/* ── Wire ATLAS into formatInstitutionalContext ─────────────────────────── */
const _origFormat_atlas = formatInstitutionalContext;
formatInstitutionalContext = function(ctx, dir) {
  let msg = '';
  try { msg = _origFormat_atlas(ctx, dir) || ''; }
  catch (e) { console.warn('inst-ctx[atlas-upstream] error:', e.message); }
  try { if (ctx?.atlas) msg += formatATLAS(ctx.atlas, dir); }
  catch (e) { console.warn('inst-ctx[atlas] render error:', e.message); }
  return msg;
};

/* ── Wire ATLAS into analyseSignalInternal ──────────────────────────────── */
const _origAnalyse_atlas = analyseSignalInternal;
analyseSignalInternal = function(consensus, instCtx, scored) {
  let result = _origAnalyse_atlas(consensus, instCtx, scored);
  if (!result) return result;

  const atlas = instCtx?.atlas;
  if (!atlas) return result;

  try {
    const dir = consensus?.consensusDirection || 'NEUTRAL';

    if (atlas.atlasTier === 'APEX_PRIME' && atlas.realMoveReadiness >= 75) {
      const apexBlock = [
        '\n━━━━━━━━━━━━━━━━━━━━━━',
        `🏔️🔥 <b>ATLAS: APEX PRIME — TOTAL LIQUIDITY CONFIRMED</b>`,
        ``,
        `${atlas.atlasScore}/100 fuel | ${atlas.sweepCompletionPct}% swept | ${atlas.realMoveReadiness}% ready`,
        `Institutional target: <code>${atlas.institutionalTarget}</code>`,
        `Expected real move: ${dir==='BUY'?'+':'-'}${atlas.expectedMovePct}% → <code>${atlas.realMoveTarget}</code>`,
        `All 5 liquidity layers confirm ${dir} direction.`,
        '━━━━━━━━━━━━━━━━━━━━━━',
      ].join('\n');

      const firstSep = result.indexOf('━━━━━━━━━━━━━━━━━━━━━━');
      if (firstSep >= 0) result = result.slice(0, firstSep) + apexBlock + '\n' + result.slice(firstSep);
      else result = apexBlock + '\n' + result;
    } else if (atlas.atlasTier === 'APEX' || atlas.atlasTier === 'HIGH') {
      const note = `\n🏔️ <b>ATLAS ${atlas.atlasTier}:</b> ${atlas.atlasScore}/100 fuel | ${atlas.realMoveReadiness}% ready | Target: <code>${atlas.institutionalTarget}</code> | Expected: ${dir==='BUY'?'+':'-'}${atlas.expectedMovePct}%\n`;
      result += note;
    }
  } catch(e) { console.warn('ATLAS analyseSignalInternal error:', e.message); }

  return result;
};

/* ── Wire ATLAS into pos/neg + effectiveCert ────────────────────────────── */
// ATLAS certBoost injected via override on analyseSignalInternal scoring section
const _origAnalyse_atlas2 = analyseSignalInternal;
analyseSignalInternal = function(consensus, instCtx, scored) {
  // Inject ATLAS certBoost into instCtx so the existing scoring sees it
  if (instCtx && instCtx.atlas) {
    instCtx._atlasCertBoost = instCtx.atlas.atlasCertBoost || 0;
    instCtx._atlasPos = instCtx.atlas.atlasScore >= 75 ? 5
                      : instCtx.atlas.atlasScore >= 55 ? 3
                      : instCtx.atlas.atlasScore >= 35 ? 1 : 0;
  }
  return _origAnalyse_atlas2(consensus, instCtx, scored);
};


/* ════════════════════════════════════════════════════════════════════════════
   RECOVERY SIGNAL SYSTEM — UPGRADE v2
   ─────────────────────────────────────────────────────────────────────────
   Improvements over the base system:
   1. Scans ALL 90 assets every check (not just registered ones)
   2. /recovery 5h, /recovery 10h, /recovery 1d — flexible time window
   3. Shows ATLAS + LEPD + RMEE state for every asset
   4. Auto-fires when sweep completes REGARDLESS of prior registration
   5. Summary card shows ALL assets ranked by readiness score
   6. /postliq — dedicated command for post-liquidity signals only
   ════════════════════════════════════════════════════════════════════════════ */

// MAX_RECOVERY_AGE already defined above (72h)

const POSTLIQ_HISTORY_FILE = storagePath('postliq_history.json');
const POSTLIQ_HISTORY_MAX = 600;
const POSTLIQ_HISTORY_RETENTION_MS = 120 * 60 * 60 * 1000;
const POSTLIQ_HISTORY = [];
try {
  if (fs.existsSync(POSTLIQ_HISTORY_FILE)) {
    const saved = JSON.parse(fs.readFileSync(POSTLIQ_HISTORY_FILE, 'utf8'));
    if (Array.isArray(saved)) POSTLIQ_HISTORY.push(...saved.slice(-POSTLIQ_HISTORY_MAX));
  }
} catch (error) {
  console.warn('PostLiq history load skipped:', error.message);
}

function recordBitgetPostLiqHistory(rows, scannedAt = Date.now()) {
  const timestamp = Number(scannedAt) || Date.now();
  const byKey = new Map(POSTLIQ_HISTORY.map((record, index) => [
    `${record.symbol}_${record.direction}`,
    index,
  ]));
  let recorded = 0;

  for (const row of Array.isArray(rows) ? rows : []) {
    const symbol = String(row?.symbol || '').toUpperCase();
    const direction = String(row?.direction || '').toUpperCase();
    const entry = Number(row?.entry);
    if (!/^[A-Z0-9]+USDT$/.test(symbol) ||
        !['BUY', 'SELL'].includes(direction) ||
        !Number.isFinite(entry) || entry <= 0 ||
        !['EXECUTE_LIMIT', 'WAIT_SWEEP', 'WAIT_VOLUME'].includes(row?.postLiqDecision)) {
      continue;
    }

    const key = `${symbol}_${direction}`;
    const priorIndex = byKey.get(key);
    const prior = priorIndex == null ? null : POSTLIQ_HISTORY[priorIndex];
    const record = {
      symbol,
      direction,
      price: Number(row.price) || 0,
      entry,
      entrySource: String(row.entrySource || 'PostLiq').slice(0, 24),
      postLiqDecision: row.postLiqDecision,
      postLiqRationale: String(row.postLiqRationale || '').slice(0, 260),
      postLiqPoolCount: Number(row.postLiqPoolCount) || 0,
      postLiqSweepDistPct: Number(row.postLiqSweepDistPct) || 0,
      lepdState: String(row.lepdState || 'N/A').slice(0, 40),
      lepdConfidence: Number(row.lepdConfidence) || 0,
      lepdPoolsSwept: Number(row.lepdPoolsSwept) || 0,
      lepdPoolsTotal: Number(row.lepdPoolsTotal) || 0,
      rmeeMode: String(row.rmeeMode || 'N/A').slice(0, 40),
      rmeePoolsSwept: Number(row.rmeePoolsSwept) || 0,
      rmeePoolsTotal: Number(row.rmeePoolsTotal) || 0,
      rmeeSweepPct: Number(row.rmeeSweepPct) || 0,
      atlasTier: String(row.atlasTier || 'N/A').slice(0, 32),
      atlasScore: Number(row.atlasScore) || 0,
      readiness: Number(row.readiness) || 0,
      source: 'Bitget',
      firstSeenAt: Number(prior?.firstSeenAt) || timestamp,
      lastSeenAt: timestamp,
    };

    if (priorIndex == null) {
      POSTLIQ_HISTORY.push(record);
      byKey.set(key, POSTLIQ_HISTORY.length - 1);
    } else {
      POSTLIQ_HISTORY[priorIndex] = record;
    }
    recorded++;
  }

  const cutoff = timestamp - POSTLIQ_HISTORY_RETENTION_MS;
  for (let index = POSTLIQ_HISTORY.length - 1; index >= 0; index--) {
    if (Number(POSTLIQ_HISTORY[index]?.lastSeenAt) < cutoff) POSTLIQ_HISTORY.splice(index, 1);
  }
  if (POSTLIQ_HISTORY.length > POSTLIQ_HISTORY_MAX) {
    POSTLIQ_HISTORY.splice(0, POSTLIQ_HISTORY.length - POSTLIQ_HISTORY_MAX);
  }
  writeJsonBounded(POSTLIQ_HISTORY_FILE, POSTLIQ_HISTORY, { maxBytes: 512 * 1024 });
  return recorded;
}

async function runBitgetPostLiqScan(bitgetRows) {
  const symbols = [...new Map((Array.isArray(bitgetRows) ? bitgetRows : [])
    .map((row, index) => {
      const symbol = String(row?.symbol || '').toUpperCase();
      if (!/^[A-Z0-9]+USDT$/.test(symbol) || (typeof isForex === 'function' && isForex(symbol))) return null;
      return [symbol, { symbol, price: Number(row?.price), rank: index }];
    })
    .filter(Boolean)).values()];

  if (!symbols.length) return [];

  const results = [];
  let nextIndex = 0;
  const worker = async () => {
    while (true) {
      const index = nextIndex++;
      if (index >= symbols.length) return;

      const row = symbols[index];
      const { symbol } = row;
      const price = Number.isFinite(row.price) && row.price > 0
        ? row.price
        : Number(await fetchLivePrice(symbol).catch(() => 0));
      if (!Number.isFinite(price) || price <= 0) continue;

      try {
        const candles = await fetchCandlesCached(symbol, '1h', 100).catch(() => null);
        if (!candles || candles.length < 20) continue;

        for (const direction of ['BUY', 'SELL']) {
          try {
            const [exhaustionResult, rmeeResult] = await Promise.allSettled([
              Promise.resolve().then(() =>
                detectLiquidityExhaustion(candles, price, direction, null)
              ),
              getRealMoveEntry(symbol, candles, price, direction, null),
            ]);
            const exhaustion = exhaustionResult.status === 'fulfilled'
              ? exhaustionResult.value
              : null;
            const rmee = rmeeResult.status === 'fulfilled'
              ? rmeeResult.value
              : null;
            const atlas = await computeATLAS(
              symbol,
              price,
              direction,
              candles,
              { lepd: exhaustion, rmee }
            ).catch(() => null);

            const pools = Array.isArray(exhaustion?.allPools)
              ? exhaustion.allPools.map(Number).filter(level => Number.isFinite(level) && level > 0)
              : [];
            const liqCtx = direction === 'BUY'
              ? { below: pools.filter(level => level < price), above: [] }
              : { below: [], above: pools.filter(level => level > price) };
            const directionalPools = direction === 'BUY' ? liqCtx.below : liqCtx.above;

            let postLiq = null;
            if (directionalPools.length) {
              // Force a fresh PostLiq calculation instead of reusing the
              // engine's three-minute result from an earlier command.
              POST_LIQ_CACHE.delete(`postliq_${symbol}_${direction}`);
              postLiq = await getPostLiquidityEntry(
                symbol, candles, price, direction, liqCtx, null
              ).catch(() => null);
            }

            const postLiqDecision = postLiq?.decision || 'NO_ENTRY';
            const lepdState = exhaustion?.state || 'NO_DATA';
            const rmeeMode = rmee?.mode || 'NO_DATA';
            const hasLePDReadiness = [
              'PERFECT_EXHAUSTION',
              'STRONG_EXHAUSTION',
              'PARTIAL_EXHAUSTION',
              'WEAK_EXHAUSTION',
              'DEEPER_POOLS_EXIST',
              'SWEEPING',
              'SWEPT_NO_ABSORPTION',
              'PRE_SWEEP',
            ].includes(lepdState);
            const hasRmeeReadiness = [
              'PRE_CALC',
              'IN_SWEEP',
              'SWEPT_AWAITING',
              'CONFIRMING',
              'REAL_MOVE_CONFIRMED',
            ].includes(rmeeMode);
            const hasPostLiqReadiness = [
              'EXECUTE_LIMIT',
              'WAIT_SWEEP',
              'WAIT_VOLUME',
            ].includes(postLiqDecision);
            if (!hasLePDReadiness && !hasRmeeReadiness && !hasPostLiqReadiness) continue;

            const _isValidEntry = value => Number.isFinite(Number(value)) && Number(value) > 0;
            let entry = null;
            let entrySource = 'N/A';
            if (_isValidEntry(postLiq?.entry)) {
              entry = Number(postLiq.entry);
              entrySource = 'PostLiq';
            } else if (_isValidEntry(rmee?.realEntry)) {
              entry = Number(rmee.realEntry);
              entrySource = 'RMEE real';
            } else if (_isValidEntry(rmee?.preCalcEntry)) {
              entry = Number(rmee.preCalcEntry);
              entrySource = 'RMEE pre-calc';
            } else if (_isValidEntry(exhaustion?.precisionLimit)) {
              entry = Number(exhaustion.precisionLimit);
              entrySource = 'LEPD';
            }

            const lepdScore = lepdState === 'PERFECT_EXHAUSTION' ? 40
              : lepdState === 'STRONG_EXHAUSTION' ? 28
              : ['IN_SWEEP', 'SWEEPING'].includes(lepdState) ? 15
              : 0;
            const rmeeScore = rmeeMode === 'REAL_MOVE_CONFIRMED' ? 35
              : rmeeMode === 'CONFIRMING' ? 20
              : ['SWEPT_AWAITING', 'IN_SWEEP'].includes(rmeeMode) ? 10
              : 0;
            const atlasTier = atlas?.atlasTier || 'N/A';
            const atlasScore = atlasTier === 'APEX_PRIME' ? 25
              : atlasTier === 'APEX' ? 15
              : atlasTier === 'HIGH' ? 8
              : 0;
            const postLiqScore = postLiqDecision === 'EXECUTE_LIMIT' ? 30
              : postLiqDecision === 'WAIT_SWEEP' ? 15
              : postLiqDecision === 'WAIT_VOLUME' ? 8
              : 0;

            results.push({
              symbol,
              direction,
              price,
              entry,
              entrySource,
              postLiqDecision,
              postLiqRationale: postLiq?.rationale || postLiq?.reason || '',
              postLiqPoolCount: Number(postLiq?.poolCount) || directionalPools.length,
              postLiqSweepDistPct: Number(postLiq?.sweepDistPct) || 0,
              lepdState,
              lepdConfidence: Number(exhaustion?.confidence) || 0,
              lepdPoolsSwept: Number(exhaustion?.poolsSwept) || 0,
              lepdPoolsTotal: Array.isArray(exhaustion?.allPools) ? exhaustion.allPools.length : 0,
              rmeeMode,
              rmeePoolsSwept: Number(rmee?.poolsSwept) || 0,
              rmeePoolsTotal: Number(rmee?.totalPools) || 0,
              rmeeSweepPct: Number(rmee?.sweepPct) || 0,
              atlasTier,
              atlasScore: Number(atlas?.atlasScore) || 0,
              readiness: lepdScore + rmeeScore + atlasScore + postLiqScore,
              rank: row.rank,
            });
          } catch (error) {
            console.warn(`Bitget PostLiq calculation skipped ${symbol} ${direction}:`, error.message);
          }
        }
      } catch (error) {
        console.warn(`Bitget PostLiq scan skipped ${symbol}:`, error.message);
      }
    }
  };

  await Promise.all(Array.from(
    { length: Math.min(6, symbols.length) },
    () => worker()
  ));

  return results.sort((a, b) =>
    b.readiness - a.readiness ||
    a.rank - b.rank ||
    a.symbol.localeCompare(b.symbol) ||
    a.direction.localeCompare(b.direction)
  );
}

async function sendBitgetPostLiqSummary(chatId, sendMessage) {
  try {
    const universe = await fetchAllBitgetFuturesSymbols();
    if (!Array.isArray(universe) || universe.length === 0) {
      await sendMessage('❌ Bitget returned no ranked USDT-M symbols. No WATCH-list fallback was used.');
      return [];
    }

    const results = await runBitgetPostLiqScan(universe);
    const entries = results.filter(row =>
      ['EXECUTE_LIMIT', 'WAIT_SWEEP', 'WAIT_VOLUME'].includes(row.postLiqDecision) &&
      Number.isFinite(Number(row.entry)) && Number(row.entry) > 0
    );
    recordBitgetPostLiqHistory(entries);
    if (!entries.length) {
      await sendMessage(
        '♻️ <b>PostLiq — 0 setups found</b>\n' +
        'Bitget USDT-M | Sorted by readiness\n\n' +
        'No ranked Bitget PostLiq entries with a calculable entry.'
      );
      return entries;
    }

    const lines = entries.slice(0, 8).map(row => {
      const icon = row.lepdState === 'PERFECT_EXHAUSTION' ? '🏆'
        : row.lepdState === 'STRONG_EXHAUSTION' ? '✅'
        : row.rmeeMode === 'REAL_MOVE_CONFIRMED' ? '🎯'
        : row.rmeeMode === 'CONFIRMING' ? '⚡'
        : row.atlasTier === 'APEX_PRIME' ? '🏔️🔥'
        : '📍';
      return `${icon} <b>${row.symbol}</b> ${row.direction} → ` +
        `<code>${recoveryHistoryPrice(row.entry)}</code> | ` +
        `LEPD:${row.lepdState} | RMEE:${row.rmeeMode}`;
    });
    const summary = [
      `♻️ <b>PostLiq — ${entries.length} setup(s) found</b>`,
      'Bitget USDT-M | postliq | Sorted by readiness',
      '',
      ...lines,
    ];
    if (entries.length > lines.length) summary.push(`+${entries.length - lines.length} more...`);
    await sendMessage(summary.join('\n'));
    return entries;
  } catch (error) {
    console.error('Bitget /postliq scan failed:', error.message);
    try {
      await sendMessage(
        `❌ Bitget /postliq scan failed: ${String(error.message || 'unknown error').replace(/[<>&]/g, '')}`
      );
    } catch (_) {}
    return [];
  }
}

async function runFullRecoveryScan(hoursBack = 12, filter = 'all', thresholdOverrides = null) {
  // thresholdOverrides: { certMin, avgMin, convMin, pillarMin } — when supplied,
  // the per-symbol candidates are pre-screened so callers only get setups that
  // would actually pass the user's gate. Card-level pass also runs later.
  const results = [];
  const symbols = Array.from(WATCH.keys());
  const cutoff  = Date.now() - hoursBack * 3600 * 1000;

  for (const symbol of symbols) {
    try {
      const price   = await fetchLivePrice(symbol).catch(() => null);
      if (!price) continue;

      const candles = await fetchCandlesCached(symbol, '1h', 100).catch(() => null);
      if (!candles || candles.length < 20) continue;

      // Check both BUY and SELL
      for (const dir of ['BUY', 'SELL']) {
        try {
          const [lepd, rmee, atlas] = await Promise.allSettled([
            Promise.resolve(detectLiquidityExhaustion(candles, price, dir, null)),
            getRealMoveEntry(symbol, candles, price, dir, null),
            computeATLAS(symbol, price, dir, candles, null),
          ]);

          const lepdData  = lepd.status  === 'fulfilled' ? lepd.value  : null;
          const rmeeData  = rmee.status  === 'fulfilled' ? rmee.value  : null;
          const atlasData = atlas.status === 'fulfilled' ? atlas.value : null;

          // Compute readiness
          const lepdScore = lepdData?.state === 'PERFECT_EXHAUSTION' ? 40
                          : lepdData?.state === 'STRONG_EXHAUSTION'  ? 28
                          : lepdData?.state === 'IN_SWEEP' || lepdData?.state === 'SWEEPING' ? 15
                          : 0;
          const rmeeScore = rmeeData?.mode === 'REAL_MOVE_CONFIRMED' ? 35
                          : rmeeData?.mode === 'CONFIRMING' ? 20
                          : rmeeData?.mode === 'SWEPT_AWAITING' ? 10
                          : 0;
          const atlasScore = atlasData?.atlasTier === 'APEX_PRIME' ? 25
                           : atlasData?.atlasTier === 'APEX' ? 15
                           : atlasData?.atlasTier === 'HIGH' ? 8 : 0;

          const readiness = lepdScore + rmeeScore + atlasScore;
          // Keep the dedicated PostLiq feed exhaustive. WAIT_SWEEP and
          // WAIT_VOLUME are valid PostLiq states even when other readiness
          // pillars are still quiet.
          if (filter !== 'postliq' && readiness < 15) continue;

          // ── postLiq precision entry: build minimal liqCtx from LEPD pool data ──
          let postLiqData = null;
          if (filter === 'postliq' || lepdScore >= 15 || rmeeScore >= 10) {
            try {
              const _lepdPools = lepdData?.allPools || [];
              const _minLiqCtx = dir === 'BUY'
                ? { below: _lepdPools.filter(p => p < price), above: [] }
                : { below: [], above: _lepdPools.filter(p => p > price) };
              if ((_minLiqCtx.below.length > 0 || _minLiqCtx.above.length > 0)) {
                postLiqData = await getPostLiquidityEntry(symbol, candles, price, dir, _minLiqCtx, null).catch(() => null);
              }
            } catch(_plErr) { /* skip postliq errors */ }
          }

          // ── postliq score: actionable postLiq decision adds weight ──
          const postLiqScore = postLiqData?.decision === 'EXECUTE_LIMIT' ? 30
                             : postLiqData?.decision === 'WAIT_SWEEP'    ? 15
                             : postLiqData?.decision === 'WAIT_VOLUME'   ? 8
                             : 0;
          const totalReadiness = readiness + postLiqScore;

          // Filter. The PostLiq command includes every PostLiq state,
          // including sweep and volume-wait states.
          if (filter === 'postliq') {
            if (!postLiqData?.decision || postLiqData.decision === 'NO_POOLS') continue;
          }
          if (filter === 'confirmed' && rmeeData?.mode !== 'REAL_MOVE_CONFIRMED') continue;

          results.push({
            symbol, dir, price,
            readiness:    totalReadiness,
            lepdState:    lepdData?.state          || 'N/A',
            rmeeMode:     rmeeData?.mode           || 'N/A',
            atlasTier:    atlasData?.atlasTier      || 'N/A',
            atlasScore:   atlasData?.atlasScore     || 0,
            postLiqDecision: postLiqData?.decision  || null,
            postLiqEntry: postLiqData?.entry        || null,
            postLiqPools: postLiqData?.poolCount     || 0,
            confidence:   Math.round(totalReadiness),
            preCalcEntry: postLiqData?.entry || rmeeData?.preCalcEntry || lepdData?.precisionLimit || null,
            realEntry:    postLiqData?.decision === 'EXECUTE_LIMIT'
                            ? (postLiqData?.entry || rmeeData?.realEntry || lepdData?.precisionLimit)
                            : (rmeeData?.realEntry || lepdData?.precisionLimit || null),
            sweepPct:     rmeeData?.sweepPct         || 0,
            expectedMove: atlasData?.expectedMovePct || 0,
            instTarget:   atlasData?.institutionalTarget || null,
          });
        } catch(_) {}
      }

      await new Promise(res => setTimeout(res, 50)); // small delay per symbol
    } catch(e) {
      console.warn(`Recovery scan error for ${symbol}:`, e.message);
    }
  }

  // Sort by readiness score descending
  results.sort((a, b) => b.readiness - a.readiness);
  return results;
}

/* ── Enhanced /recovery /missed /postliq Telegram handler ───────────────── */
const _origHandleLegacy_atlas = EnhancedQuantumTradingSystem.prototype.handleLegacyCommand;
EnhancedQuantumTradingSystem.prototype.handleLegacyCommand = async function(message) {
  const text   = (message?.text || '').trim();
  const chatId = message?.chat?.id;
  const parts  = text.split(' ');
  const cmd    = parts[0].toLowerCase().replace(/@[^\s]+$/, '');

  // /recovery [cert] [avg] [conv] [Nh | Nd] [all | postliq | confirmed]
  // /missed  [Nh]
  // /postliq [Nh]
  if (cmd === '/postliq') {
    await sendBitgetPostLiqSummary(
      chatId,
      messageText => tg('sendMessage', {
        chat_id: chatId,
        text: messageText,
        parse_mode: 'HTML',
      })
    );
    return;
  }

  if (['/recovery', '/missed'].includes(cmd)) {
    let hours  = 12;
    let filter = RECOVERY_DEFAULT_FILTER;
    let _certO = null, _avgO = null, _convO = null;
    const _bareNums = [];
    for (const part of parts.slice(1)) {
      if (part.endsWith('h'))                                  hours = parseFloat(part) || 12;
      else if (part.endsWith('d'))                             hours = (parseFloat(part) || 1) * 24;
      else if (['all','postliq','confirmed'].includes(part.toLowerCase())) filter = part.toLowerCase();
      else if (!isNaN(parseFloat(part)))                       _bareNums.push(parseFloat(part));
    }
    if (_bareNums.length >= 1) _certO = _bareNums[0];
    if (_bareNums.length >= 2) _avgO  = _bareNums[1];
    if (_bareNums.length >= 3) _convO = _bareNums[2];
    if (_bareNums.length >= 4) hours  = _bareNums[3];
    hours = Math.max(1, Math.min(120, hours));
    const _thrOv = {};
    if (_certO != null) _thrOv.certMin = _certO;
    if (_avgO  != null) _thrOv.avgMin  = _avgO;
    if (_convO != null) _thrOv.convMin = _convO;

    await tg('sendMessage', { chat_id: chatId,
      text: `🔍 <b>Recovery Scan — Last ${hours}h</b>\nFilter: <b>${filter}</b>\nScanning ${WATCH.size} assets for swept liquidity...\n<i>Allow 30-60s...</i>`,
      parse_mode: 'HTML' }).catch(() => {});

    const results = await runFullRecoveryScan(hours, filter, _thrOv).catch(() => []);

    if (!results.length) {
      await tg('sendMessage', { chat_id: chatId,
        text: `📭 <b>No signals found</b>\nNo ${filter === 'postliq' ? 'post-liquidity' : filter === 'confirmed' ? 'confirmed real-move' : ''} setups in last ${hours}h.\n\nTry: /recovery 24h or /recovery 48h`,
        parse_mode: 'HTML' }).catch(() => {});
      return;
    }

    // Summary card
    const summaryLines = [
      `♻️ <b>Recovery Scan Results — ${results.length} setups found</b>`,
      `Last ${hours}h | Filter: ${filter} | Sorted by readiness`,
      '',
    ];

    for (const r of results.slice(0, 10)) {
      const icon = r.lepdState === 'PERFECT_EXHAUSTION' ? '🏆'
                 : r.lepdState === 'STRONG_EXHAUSTION'  ? '✅'
                 : r.rmeeMode  === 'REAL_MOVE_CONFIRMED' ? '🎯'
                 : r.rmeeMode  === 'CONFIRMING'          ? '⚡'
                 : r.atlasTier === 'APEX_PRIME'          ? '🏔️🔥'
                 : '📍';

      const entryStr = r.realEntry  ? ` → Entry: <code>${r.realEntry}</code>`
                     : r.preCalcEntry ? ` → Pre-calc: <code>${r.preCalcEntry}</code>` : '';
      const moveStr  = r.expectedMove > 0 ? ` | +${r.expectedMove}% expected` : '';
      const plStr    = r.postLiqDecision === 'EXECUTE_LIMIT' ? ` ✅ PostLiq READY`
                     : r.postLiqDecision === 'WAIT_SWEEP'    ? ` ⏳ PostLiq SWEEP`
                     : '';

      summaryLines.push(
        `${icon} <b>${r.symbol}</b> ${r.dir} @ <code>${r.price}</code>${entryStr}${moveStr}${plStr}`,
        `   LEPD: ${r.lepdState} | RMEE: ${r.rmeeMode} | PostLiq: ${r.postLiqDecision||'N/A'}`
      );
    }
    if (results.length > 10) summaryLines.push(`\n<i>+${results.length - 10} more setups...</i>`);
    const cardLimit = filter === 'postliq' ? results.length : Math.min(3, results.length);
    summaryLines.push('', `<i>Sending full signal cards for ${filter === 'postliq' ? 'all' : 'top ' + cardLimit} setups...</i>`);

    await tg('sendMessage', { chat_id: chatId,
      text: summaryLines.join('\n'), parse_mode: 'HTML' }).catch(() => {});

    // Send every PostLiq card; retain the top-three limit for other filters.
    const gen = this.signalGenerator;
    for (const r of results.slice(0, cardLimit)) {
      try {
        await new Promise(res => setTimeout(res, 1500));

        const consensus = await buildMTFConsensus(r.symbol, gen).catch(() => null);
        if (!consensus) continue;

        // ✅ FIX: align recovery direction with live consensus to avoid the
        // "header SELL but card BUY" bug. The recovery scanner enumerates both
        // directions and may rank a SELL candidate while consensus actually
        // picks BUY for the same symbol.
        if (consensus?.consensusDirection && consensus.consensusDirection !== 'NEUTRAL'
            && consensus.consensusDirection !== r.dir) {
          console.log(`♻️ Recovery dir corrected for ${r.symbol}: ${r.dir} → ${consensus.consensusDirection}`);
          r.dir = consensus.consensusDirection;
        }

        const livePrice = await fetchLivePrice(r.symbol).catch(() => r.price);
        const instCtx   = await buildInstitutionalContextFull(r.symbol, livePrice, r.dir).catch(() => null);
        if (instCtx) consensus._instCtx = instCtx;

        // Apply the quality gate to normal recovery cards. /postliq is an
        // exhaustive PostLiq feed, so include its sweep and other states.
        const _q = isHighQualitySignal(consensus, instCtx, _thrOv);
        if (filter !== 'postliq' && !_q.ok) {
          console.log(`⏭ Recovery card skipped ${r.symbol} ${r.dir} → ${_q.reason}`);
          continue;
        }
        // ✅ ARBITER: pick the BEST liquidity engine for this recovery card
        // and stash on consensus so AI Analyst + RSDE both reuse it.
        const _gCertR = safeNumber(consensus?.certaintyScore || consensus?.certainty || 0);
        const _pickedR = selectBestLimitGuarded(livePrice, r.dir, { cert: _gCertR, instCtx });
        const _safeLim = _pickedR?.price || null;
        if (_safeLim) {
          consensus._safeLimit  = _safeLim;
          consensus._safeSource = _pickedR.source;
          consensus._safeLabel  = _pickedR.label;
          if (instCtx) {
            instCtx._safeLimit  = _safeLim;
            instCtx._safeSource = _pickedR.source;
            instCtx._safeLabel  = _pickedR.label;
          }
        }

        const scored = autoScoreSignal(consensus, consensus?.bestSig);

        const header = [
          `━━━ ♻️ RECOVERY: ${r.symbol} ${r.dir} ━━━`,
          `LEPD: <b>${r.lepdState}</b> | RMEE: <b>${r.rmeeMode}</b> | ATLAS: <b>${r.atlasTier}</b>`,
          _safeLim ? `🎯 <b>Limit (${r.dir} max -3% pullback): <code>${_safeLim}</code></b>` :
            (r.realEntry ? `🎯 <b>Real move entry: <code>${r.realEntry}</code></b>` : (r.preCalcEntry ? `📍 Pre-calc entry: <code>${r.preCalcEntry}</code>` : '')),
          r.expectedMove > 0 ? `📈 Expected move: ${r.dir==='BUY'?'+':'-'}${r.expectedMove}%` : '',
          '',
        ].filter(Boolean).join('\n');

        const cardText = formatMTFConsensusMessage(consensus) || '';
        const fullMsg  = header + cardText;
        const safeMsg  = fullMsg.length > 4090 ? fullMsg.slice(0, 4090) + '<i>…</i>' : fullMsg;

        const msgR = await tg('sendMessage', {
          chat_id: chatId, text: safeMsg, parse_mode: 'HTML', disable_web_page_preview: true,
        }).catch(() => null);

        if (msgR?.ok) {
          await new Promise(res => setTimeout(res, 1500));
          await sendAIAnalysis(r.symbol, consensus, instCtx, scored, true).catch(() => {});
        }
      } catch(e) {
        console.warn(`Recovery card error for ${r.symbol}:`, e.message);
      }
    }
    return;
  }

  // /atlas — show ATLAS score for a specific symbol
  if (cmd === '/atlas') {
    const sym = parts[1]?.toUpperCase().replace('/', '') || null;
    const d   = parts[2]?.toUpperCase() || 'BUY';
    if (!sym) {
      await tg('sendMessage', { chat_id: chatId,
        text: 'Usage: /atlas BTCUSDT BUY', parse_mode: 'HTML' }).catch(() => {});
      return;
    }
    try {
      const price   = await fetchLivePrice(sym);
      const candles = await fetchCandlesCached(sym, '1h', 80);
      const atlas   = await computeATLAS(sym, price, d, candles, null);
      const msg     = atlas ? `<b>${sym} ${d} ATLAS Report</b>\n${formatATLAS(atlas, d)}`
                            : `❌ Could not compute ATLAS for ${sym}`;
      await tg('sendMessage', { chat_id: chatId, text: msg, parse_mode: 'HTML' }).catch(() => {});
    } catch(e) {
      await tg('sendMessage', { chat_id: chatId, text: `❌ Error: ${e.message}`, parse_mode: 'HTML' }).catch(() => {});
    }
    return;
  }

  return _origHandleLegacy_atlas.call(this, message);
};

