/* ████████████████████████████████████████████████████████████████████████████
   EXHAUSTION TARGET ENGINE (ETE) v2 — Multi-Timeframe Reversal Predictor
   ─────────────────────────────────────────────────────────────────────────────
   Command: /exhaustion SYMBOL BUY|SELL [TARGET_PRICE]
   Examples:
     /exhaustion XRPUSDT SELL          → BUY trend exhaustion zone
     /exhaustion XRPUSDT SELL 0.9934   → + confirms SELL target is reachable
     /exhaustion BTCUSDT BUY 85000     → SELL trend exhaustion zone + BUY target

   Direction logic:
     SELL in command = user trades SELL after reversal  → current trend is BUY
     BUY  in command = user trades BUY  after reversal  → current trend is SELL

   Timeframe weights: 1D = 5×, 4H = 2.5×, 1H = 1×  (institutional weighting)

   FIX NOTE: All previous patches targeted EnhancedQuantumTradingSystem.prototype —
   the wrong class. The live bot routes commands through
   EnhancedQuantumTelegramInterface.prototype.handleEnhancedCommand → handleLegacyCommand.
   This patch correctly targets EnhancedQuantumTelegramInterface.prototype.
   ████████████████████████████████████████████████████████████████████████████ */

/* ════════════════════════════════════════════════════════════════════════════
   HELPER — ATR(14)
   ════════════════════════════════════════════════════════════════════════════ */
function _ete_atr(candles) {
  let sum = 0, cnt = 0;
  const n = candles.length;
  for (let i = Math.max(1, n - 15); i < n; i++) {
    const tr = Math.max(
      candles[i].h - candles[i].l,
      Math.abs(candles[i].h - candles[i - 1].c),
      Math.abs(candles[i].l - candles[i - 1].c)
    );
    sum += tr; cnt++;
  }
  return cnt > 0 ? sum / cnt : candles[candles.length - 1].c * 0.01;
}

/* ════════════════════════════════════════════════════════════════════════════
   HELPER — RSI(14)
   ════════════════════════════════════════════════════════════════════════════ */
function _ete_rsi(candles) {
  let gains = 0, losses = 0, cnt = 0;
  const n = candles.length;
  for (let i = Math.max(1, n - 15); i < n; i++) {
    const ch = candles[i].c - candles[i - 1].c;
    if (ch >= 0) gains += ch; else losses -= ch;
    cnt++;
  }
  if (!cnt) return 50;
  const avgG = gains / cnt, avgL = losses / cnt;
  if (avgL === 0) return 100;
  return 100 - 100 / (1 + avgG / avgL);
}

/* ════════════════════════════════════════════════════════════════════════════
   HELPER — Swing pivots (5-bar rule)
   ════════════════════════════════════════════════════════════════════════════ */
function _ete_swings(candles) {
  const n = candles.length;
  const lb = Math.min(5, Math.max(2, Math.floor(n / 8)));
  const highs = [], lows = [];
  for (let i = lb; i < n - lb; i++) {
    if (candles.slice(i - lb, i).every(c => c.h <= candles[i].h) &&
        candles.slice(i + 1, i + lb + 1).every(c => c.h <= candles[i].h))
      highs.push({ idx: i, price: candles[i].h });
    if (candles.slice(i - lb, i).every(c => c.l >= candles[i].l) &&
        candles.slice(i + 1, i + lb + 1).every(c => c.l >= candles[i].l))
      lows.push({ idx: i, price: candles[i].l });
  }
  return { highs, lows };
}

/* ════════════════════════════════════════════════════════════════════════════
   PER-TIMEFRAME ANALYSIS
   ════════════════════════════════════════════════════════════════════════════ */
function _ete_analyseTF(candles, currentPrice, trend, label) {
  try {
    const atr = _ete_atr(candles);
    const rsi = _ete_rsi(candles);
    const rsiExhausted = trend === 'BUY' ? rsi > 70 : rsi < 30;
    const { highs: swingHighs, lows: swingLows } = _ete_swings(candles);
    const n = candles.length;

    /* ── Fibonacci extension ──────────────────────────────────────── */
    let fibTarget = null, fibLabel = '';
    if (trend === 'BUY' && swingHighs.length && swingLows.length) {
      const hi = swingHighs[swingHighs.length - 1].price;
      const lo = swingLows.filter(s => s.idx < swingHighs[swingHighs.length - 1].idx).slice(-1)[0]?.price;
      if (lo && hi > lo) {
        const imp = hi - lo;
        const f127 = lo + imp * 1.272, f161 = lo + imp * 1.618;
        fibTarget = f127 > currentPrice ? f127 : f161;
        fibLabel  = fibTarget === f127 ? '127.2% ext' : '161.8% ext';
      }
    } else if (trend === 'SELL' && swingHighs.length && swingLows.length) {
      const hi = swingHighs[swingHighs.length - 1].price;
      const lo = swingLows.filter(s => s.idx < swingHighs[swingHighs.length - 1].idx).slice(-1)[0]?.price;
      if (lo && hi > lo) {
        const imp = hi - lo;
        const cands = [hi - imp * 1.272, hi - imp * 1.618].filter(v => v < currentPrice && v > 0);
        if (cands.length) {
          fibTarget = cands[0];
          fibLabel  = fibTarget === hi - imp * 1.272 ? '127.2% ext' : '161.8% ext';
        }
      }
    }

    /* ── Liquidity pool (equal highs / equal lows) ───────────────── */
    const TOL = 0.0015;
    let poolTarget = null;
    if (trend === 'BUY') {
      const highs = swingHighs.filter(s => s.price > currentPrice).map(s => s.price).sort((a, b) => a - b);
      for (let i = 0; i < highs.length - 1 && !poolTarget; i++)
        if (Math.abs(highs[i + 1] - highs[i]) / highs[i] < TOL) poolTarget = (highs[i] + highs[i + 1]) / 2;
      if (!poolTarget && highs.length) poolTarget = highs[0];
    } else {
      const lows = swingLows.filter(s => s.price < currentPrice).map(s => s.price).sort((a, b) => b - a);
      for (let i = 0; i < lows.length - 1 && !poolTarget; i++)
        if (Math.abs(lows[i] - lows[i + 1]) / lows[i] < TOL) poolTarget = (lows[i] + lows[i + 1]) / 2;
      if (!poolTarget && lows.length) poolTarget = lows[0];
    }

    /* ── ATR projection ──────────────────────────────────────────── */
    const atrMult  = label === '1D' ? 4.5 : label === '4H' ? 2.5 : 1.5;
    const atrTarget = trend === 'BUY'
      ? currentPrice + atr * atrMult
      : Math.max(currentPrice - atr * atrMult, currentPrice * 0.01);

    /* ── Volume exhaustion ───────────────────────────────────────── */
    const vols = candles.slice(-7).map(c => c.v || 0);
    const vEarly = (vols[0] + vols[1] + vols[2]) / 3;
    const vLate  = (vols[4] + vols[5] + vols[6]) / 3;
    const volExhausted = vEarly > 0 && vLate < vEarly * 0.75;

    /* ── Price-RSI divergence ────────────────────────────────────── */
    let divergence = false;
    if (n >= 20) {
      const mid = Math.floor(n / 2);
      const older = candles[mid].c, newer = candles[n - 1].c;
      if (trend === 'BUY'  && newer > older && rsi < 60) divergence = true;
      if (trend === 'SELL' && newer < older && rsi > 40) divergence = true;
    }

    /* ── Weighted consensus price ────────────────────────────────── */
    const sigs = [];
    if (fibTarget  !== null) sigs.push({ price: fibTarget,  w: 3, lbl: fibLabel });
    if (poolTarget !== null) sigs.push({ price: poolTarget, w: 2, lbl: 'Liq pool' });
    sigs.push({ price: atrTarget, w: 1, lbl: `${atrMult}×ATR` });
    const sigW = sigs.reduce((s, sg) => s + sg.w, 0);
    const exhaustionPrice = sigs.reduce((s, sg) => s + sg.price * sg.w, 0) / sigW;

    /* ── Confidence ──────────────────────────────────────────────── */
    let confidence = 50;
    if (rsiExhausted) confidence += 20;
    if (volExhausted) confidence += 15;
    if (poolTarget)   confidence += 15;
    if (fibTarget)    confidence +=  5;
    if (divergence)   confidence += 10;
    confidence = Math.min(95, confidence);

    const R = v => Math.round(v * 1e6) / 1e6;
    return {
      label, confidence, rsi: Math.round(rsi * 10) / 10,
      exhaustionPrice: R(exhaustionPrice),
      atr: R(atr), atrTarget: R(atrTarget), atrMult,
      fibTarget:  fibTarget  !== null ? R(fibTarget)  : null, fibLabel,
      poolTarget: poolTarget !== null ? R(poolTarget) : null,
      rsiExhausted, volExhausted, divergence,
      signals: sigs.map(s => ({ lbl: s.lbl, price: R(s.price) })),
    };
  } catch (e) {
    console.warn(`_ete_analyseTF [${label}] error:`, e.message);
    return null;
  }
}

/* ════════════════════════════════════════════════════════════════════════════
   MAIN ENGINE
   ════════════════════════════════════════════════════════════════════════════ */
async function computeExhaustionTarget(symbol, currentPrice, userDir, userTargetPrice) {
  const currentTrend = userDir === 'BUY' ? 'SELL' : 'BUY';

  const [c1h, c4h, c1d] = await Promise.all([
    fetchCandlesCached(symbol, '1h',   120).catch(() => null),
    fetchCandlesCached(symbol, '4h',   100).catch(() => null),
    fetchCandlesCached(symbol, '1day',  80).catch(() => null),
  ]);

  if (!c1h || c1h.length < 20) return null;

  const tf1h = _ete_analyseTF(c1h, currentPrice, currentTrend, '1H');
  const tf4h = (c4h && c4h.length >= 20) ? _ete_analyseTF(c4h, currentPrice, currentTrend, '4H') : null;
  const tf1d = (c1d && c1d.length >= 10) ? _ete_analyseTF(c1d, currentPrice, currentTrend, '1D') : null;

  const candidates = [];
  if (tf1h) candidates.push({ tf: tf1h, weight: 1.0 });
  if (tf4h) candidates.push({ tf: tf4h, weight: 2.5 });
  if (tf1d) candidates.push({ tf: tf1d, weight: 5.0 });
  if (!candidates.length) return null;

  const totalW       = candidates.reduce((s, c) => s + c.weight, 0);
  const wExhaustion  = candidates.reduce((s, c) => s + c.tf.exhaustionPrice * c.weight, 0) / totalW;
  const wConfidence  = Math.round(candidates.reduce((s, c) => s + c.tf.confidence * c.weight, 0) / totalW);

  const anySigRsi  = candidates.some(c => c.tf.rsiExhausted);
  const anySigVol  = candidates.some(c => c.tf.volExhausted);
  const anySigPool = candidates.some(c => c.tf.poolTarget !== null);
  const allAgree   = candidates.length > 1 && candidates.every(c =>
    currentTrend === 'BUY' ? c.tf.exhaustionPrice > currentPrice : c.tf.exhaustionPrice < currentPrice
  );

  let targetAnalysis = null;
  if (userTargetPrice && Number.isFinite(userTargetPrice) && userTargetPrice > 0) {
    const exhaustionOK = userDir === 'BUY' ? wExhaustion < userTargetPrice : wExhaustion > userTargetPrice;
    targetAnalysis = {
      valid:       exhaustionOK,
      targetPrice: userTargetPrice,
      distPct:     Math.round(Math.abs((userTargetPrice - wExhaustion) / wExhaustion * 100) * 1000) / 1000,
      runPct:      Math.round(Math.abs((wExhaustion   - currentPrice) / currentPrice  * 100) * 1000) / 1000,
    };
  }

  return {
    symbol, currentPrice, currentTrend, userDir,
    exhaustionPrice: Math.round(wExhaustion * 1e6) / 1e6,
    confidence: wConfidence,
    tf1h, tf4h, tf1d,
    anySigRsi, anySigVol, anySigPool, allAgree,
    targetAnalysis,
    timestamp: Date.now(),
  };
}

/* ════════════════════════════════════════════════════════════════════════════
   TELEGRAM FORMATTER
   ════════════════════════════════════════════════════════════════════════════ */
function formatExhaustionReport(d) {
  if (!d) return '❌ Could not compute exhaustion target.';

  const fmt = v => {
    const n = Number(v);
    if (!Number.isFinite(n) || n <= 0) return '?';
    if (n >= 100000) return n.toFixed(0);
    if (n >= 10000)  return n.toFixed(1);
    if (n >= 1000)   return n.toFixed(2);
    if (n >= 100)    return n.toFixed(3);
    if (n >= 1)      return n.toFixed(4);
    if (n >= 0.01)   return n.toFixed(5);
    return n.toFixed(6);
  };

  const trendUp    = d.currentTrend === 'BUY';
  const trendEmoji = trendUp ? '📈' : '📉';
  const userEmoji  = d.userDir === 'BUY' ? '🟢' : '🔴';
  const confFill   = Math.round(d.confidence / 10);
  const confBar    = '█'.repeat(Math.max(0,Math.min(10,confFill))) + '░'.repeat(Math.max(0,10-Math.max(0,Math.min(10,confFill))));
  const confLabel  = d.confidence >= 85 ? '🔥🔥 VERY HIGH'
                   : d.confidence >= 70 ? '🔥 HIGH'
                   : d.confidence >= 55 ? '✅ MODERATE'
                   : '⚠️ LOW — wait for confluence';

  const lines = [];

  lines.push(`━━━ 🎯 EXHAUSTION TARGET ENGINE (1H·4H·1D) ━━━`);
  lines.push(`<b>${d.symbol}</b>  Live: <code>${fmt(d.currentPrice)}</code>`);
  lines.push(`Scanned: 1H + 4H + 1D · ${new Date(d.timestamp).toUTCString()}`);
  lines.push(``);
  lines.push(`${trendEmoji} Current trend:  <b>${d.currentTrend} (${trendUp ? 'rising' : 'falling'})</b>`);
  lines.push(`${userEmoji} Your trade:      <b>${d.userDir}</b> after reversal`);
  lines.push(``);

  lines.push(`━━━ 📍 MTF CONSENSUS EXHAUSTION ZONE ━━━`);
  lines.push(`🎯 <b>TARGET: <code>${fmt(d.exhaustionPrice)}</code></b>`);
  lines.push(`   <i>→ ${d.currentTrend} move exhausts &amp; reverses here</i>`);
  lines.push(``);
  lines.push(`Confidence: ${confLabel}`);
  lines.push(`[${confBar}] ${d.confidence}%`);
  lines.push(``);

  const sigs = [];
  if (d.anySigRsi)  sigs.push(`⚠️ RSI exhaustion on ≥1 TF`);
  if (d.anySigVol)  sigs.push(`📉 Volume declining (momentum weakening)`);
  if (d.anySigPool) sigs.push(`🏊 Liquidity pool cluster mapped`);
  if (d.allAgree)   sigs.push(`✅ All timeframes agree on exhaustion side`);
  if (sigs.length)  lines.push(sigs.join('\n'));
  lines.push(``);

  lines.push(`━━━ 🕐 TIMEFRAME BREAKDOWN ━━━`);
  for (const tf of [d.tf1h, d.tf4h, d.tf1d].filter(Boolean)) {
    const tags = [];
    if (tf.rsiExhausted) tags.push(`RSI ${tf.rsi} ${trendUp ? 'OB' : 'OS'}`);
    if (tf.volExhausted) tags.push(`vol↓`);
    if (tf.divergence)   tags.push(`divergence`);
    const tagStr = tags.length ? ` · <i>${tags.join(' · ')}</i>` : '';
    lines.push(`<b>${tf.label}:</b> <code>${fmt(tf.exhaustionPrice)}</code> (${tf.confidence}% conf)${tagStr}`);
    const parts = [];
    if (tf.fibTarget)  parts.push(`Fib ${fmt(tf.fibTarget)} <i>${tf.fibLabel}</i>`);
    if (tf.poolTarget) parts.push(`Pool ${fmt(tf.poolTarget)}`);
    parts.push(`ATR×${tf.atrMult} → ${fmt(tf.atrTarget)}`);
    lines.push(`   ${parts.join(' | ')}`);
    lines.push(`   ATR: ${fmt(tf.atr)} · RSI: ${tf.rsi}`);
    lines.push(``);
  }

  const distPct = Math.round(Math.abs((d.exhaustionPrice - d.currentPrice) / d.currentPrice * 100) * 100) / 100;
  lines.push(`📏 Distance to exhaustion: <b>${distPct}%</b> from live price`);
  lines.push(``);

  if (d.targetAnalysis) {
    const ta = d.targetAnalysis;
    lines.push(`━━━ 🏹 TARGET PRICE ANALYSIS ━━━`);
    lines.push(`Your ${d.userDir} target: <code>${fmt(ta.targetPrice)}</code>`);
    lines.push(``);
    if (ta.valid) {
      lines.push(`✅ <b>TARGET IS REACHABLE</b>`);
      lines.push(``);
      lines.push(`Step 1 — ${d.currentTrend} run to exhaustion:`);
      lines.push(`  <code>${fmt(d.currentPrice)}</code> → <code>${fmt(d.exhaustionPrice)}</code>  (<b>${ta.runPct}%</b>)`);
      lines.push(``);
      lines.push(`Step 2 — Reversal to your target:`);
      lines.push(`  <code>${fmt(d.exhaustionPrice)}</code> → <code>${fmt(ta.targetPrice)}</code>  (<b>${ta.distPct}%</b>)`);
      lines.push(``);
      lines.push(`📋 <b>TRADE PLAN:</b>`);
      lines.push(`  1️⃣  Wait — price reaches <code>${fmt(d.exhaustionPrice)}</code>  (+${ta.runPct}%)`);
      lines.push(`  2️⃣  Enter ${d.userDir} at exhaustion zone`);
      lines.push(`  3️⃣  Target: <code>${fmt(ta.targetPrice)}</code>  (${ta.distPct}% reversal)`);
    } else {
      lines.push(`⚠️ <b>TARGET MISMATCH</b>`);
      lines.push(`Exhaustion at <code>${fmt(d.exhaustionPrice)}</code> but your ${d.userDir} target <code>${fmt(ta.targetPrice)}</code> is on the wrong side.`);
      lines.push(`Double-check your direction or target price.`);
    }
    lines.push(``);
  }

  lines.push(`━━━ 💡 SUMMARY ━━━`);
  lines.push(`• ${d.currentTrend} trend exhausts near <code>${fmt(d.exhaustionPrice)}</code>`);
  lines.push(`• After exhaustion → expect reversal → enter <b>${d.userDir}</b>`);
  lines.push(``);
  lines.push(`<i>⚠️ Always use a stop loss. Exhaustion zones can extend before reversing.</i>`);
  lines.push(`<i>💡 Confirm with: /deep ${d.symbol} ${d.userDir}</i>`);

  return lines.join('\n');
}

/* ════════════════════════════════════════════════════════════════════════════
   WIRE /exhaustion INTO EnhancedQuantumTelegramInterface.handleEnhancedCommand
   ─────────────────────────────────────────────────────────────────────────────
   FIX: The bot routes ALL commands through:
     EnhancedQuantumTelegramInterface.handleEnhancedCommand   (line ~27834)
       → default: case → this.handleLegacyCommand()
         → default: case → "Unknown quantum command"
   
   Previous patches on EnhancedQuantumTradingSystem.prototype.handleLegacyCommand
   were NEVER called (wrong class — EnhancedQuantumTradingSystem has no live
   handleLegacyCommand in the actual call chain).

   Correct fix: patch EnhancedQuantumTelegramInterface.prototype.handleEnhancedCommand
   so /exhaustion is intercepted at the top-level switch, exactly like /atlas, /apex, /ancs.
   ════════════════════════════════════════════════════════════════════════════ */

const _ete_origHandleEnhanced = EnhancedQuantumTelegramInterface.prototype.handleEnhancedCommand;
EnhancedQuantumTelegramInterface.prototype.handleEnhancedCommand = async function(message) {
  const text    = (message?.text || '').trim();
  const chatId  = message?.chat?.id;
  const parts   = text.split(/\s+/);
  const cmd     = parts[0].toLowerCase().replace(/@[^\s]+$/, '');

  if (cmd === '/exhaustion') {
    // Admin gate (handleEnhancedCommand normally does this but we've intercepted early)
    if (!isAdminMessage(message)) return;

    const sym   = normalizeAnalysisSymbol(parts[1]);
    const dir   = (parts[2] || '').toUpperCase();
    const tpRaw = parts[3] ? parseFloat(parts[3]) : null;
    const tp    = (tpRaw && Number.isFinite(tpRaw) && tpRaw > 0) ? tpRaw : null;

    // ── Usage guard ──────────────────────────────────────────────────────────
    if (!sym || (dir !== 'BUY' && dir !== 'SELL')) {
      await this.sendMessage(chatId, [
        '🎯 <b>EXHAUSTION TARGET ENGINE (1H·4H·1D)</b>',
        '',
        '<b>Usage:</b>',
        '  <code>/exhaustion SYMBOL BUY|SELL</code>',
        '  <code>/exhaustion SYMBOL BUY|SELL TARGET_PRICE</code>',
        '',
        '<b>Examples:</b>',
        '  <code>/exhaustion LTCUSDT SELL</code>',
        '    → Finds where the current BUY move exhausts (you want to SELL after)',
        '',
        '  <code>/exhaustion XRPUSDT SELL 0.9934</code>',
        '    → Same + confirms your 0.9934 SELL target is reachable after reversal',
        '',
        '  <code>/exhaustion BTCUSDT BUY 85000</code>',
        '    → Finds SELL exhaustion + confirms BUY target 85000 is reachable',
        '',
        '<b>BUY</b>  = you want to buy after exhaustion → current trend is SELL',
        '<b>SELL</b> = you want to sell after exhaustion → current trend is BUY',
        '',
        'Signals: Fibonacci ext · Liquidity pools · ATR projection · RSI · Volume',
      ].join('\n'));
      return;
    }

    try {
      await this.sendMessage(chatId,
        `🎯 Computing exhaustion target for <b>${sym} ${dir}</b>${tp ? ` · your target: <code>${tp}</code>` : ''}...\n` +
        `<i>Fetching 1H + 4H + 1D candles · Fib extensions · Liq pools · RSI · Volume</i>`
      );

      const price = await fetchLivePrice(sym).catch(() => null);
      if (!price || price <= 0) {
        await this.sendMessage(chatId,
          `❌ Could not fetch live price for <b>${sym}</b>.\nCheck the symbol and try again.`
        );
        return;
      }

      const result = await computeExhaustionTarget(sym, price, dir, tp).catch(e => {
        console.error('ETE compute error:', e.message); return null;
      });

      if (!result) {
        await this.sendMessage(chatId,
          `❌ Could not compute exhaustion for <b>${sym} ${dir}</b>.\nInsufficient candle data — try again in a moment.`
        );
        return;
      }

      const msg = formatExhaustionReport(result);

      // Telegram max 4096 chars — split if needed
      if (msg.length > 4000) {
        const cut = msg.lastIndexOf('\n', Math.floor(msg.length / 2)) || 4000;
        await this.sendMessage(chatId, msg.slice(0, cut));
        await this.sendMessage(chatId, msg.slice(cut + 1));
      } else {
        await this.sendMessage(chatId, msg);
      }

    } catch (err) {
      console.error('/exhaustion handler error:', err.message);
      await this.sendMessage(chatId, `❌ Exhaustion engine error: ${err.message}`);
    }

    return; // do NOT fall through
  }

  // All other commands pass through untouched
  return _ete_origHandleEnhanced.call(this, message);
};


/* ════════════════════════════════════════════════════════════════════════════
   UPDATE /quantum + /help MENU
   Patch handleEnhancedCommand's /help case via getEnhancedQuantumHelp override.
   We override the method on the prototype so any instance picks it up.
   ════════════════════════════════════════════════════════════════════════════ */

const _ete_origGetHelp = EnhancedQuantumTelegramInterface.prototype.getEnhancedQuantumHelp;
EnhancedQuantumTelegramInterface.prototype.getEnhancedQuantumHelp = function() {
  // Call the original to get existing help text
  let base = '';
  try { base = _ete_origGetHelp ? _ete_origGetHelp.call(this) : ''; } catch(e) { base = ''; }

  // If original help already mentions /exhaustion, don't duplicate
  if (base && base.includes('/exhaustion')) return base;

  // If original help exists, append our block
  const eteBlock = [
    '',
    '━━━ 🎯 EXHAUSTION TARGET ENGINE ━━━',
    '/exhaustion SYMBOL BUY|SELL — exact price where current trend exhausts &amp; reverses',
    '/exhaustion SYMBOL BUY|SELL PRICE — + confirms your target price is reachable',
    '   <i>Example: /exhaustion LTCUSDT SELL  |  /exhaustion XRPUSDT SELL 0.9934</i>',
  ].join('\n');

  return base ? base + eteBlock : [
    '⚛️ <b>Bot Commands</b>',
    '',
    '🎯 <b>EXHAUSTION TARGET ENGINE</b>',
    '/exhaustion SYMBOL BUY|SELL',
    '/exhaustion SYMBOL BUY|SELL TARGET_PRICE',
    '',
    '📡 See /quantum for the full command list.',
    eteBlock,
  ].join('\n');
};


