/* ══════════════════════════════════════════════════════════════════════
   /validate — LIQUIDITY PRICE VALIDATOR
   Given 2-4 candidate liquidity prices for a symbol/direction, rank them
   by how strongly each is confirmed by real pivot (swing wick) + volume
   structure across 1h, 4h and 1D candles, and surface the single
   best-supported price.

   Scoring is an explicit, honest technical confluence score — it mirrors
   the confluence banding already used by /vaultmtf's reversal-limit logic
   (3/3 TF agreement = high-confidence band, 2/3 = strong, 1/3 = weak,
   0/3 = distance-only guess). It is NOT a probability guarantee: no score
   here is presented as literal 100%, and every report ends with a plain
   reminder that risk management still applies regardless of score.
   ══════════════════════════════════════════════════════════════════════ */

const VALIDATE_TF_FRAMES = [
  { tf: '1h',   label: '1h',  candles: 200, weight: 1 },
  { tf: '4h',   label: '4h',  candles: 200, weight: 2 },
  { tf: '1day', label: '1D',  candles: 200, weight: 3 },
];
const VALIDATE_MIN_CANDIDATES = 2;
const VALIDATE_MAX_CANDIDATES = 4;

// Fractal pivot detector — finds local swing highs/lows with wick and
// volume context, used as a proxy for resting liquidity (stop clusters).
function _vldFindPivots(candles, lookback = 3) {
  const out = [];
  if (!Array.isArray(candles) || candles.length < lookback * 2 + 5) return out;

  const vols = candles.map(c => Number(c?.v) || 0);

  for (let i = lookback; i < candles.length - lookback; i++) {
    const c = candles[i];
    const h = Number(c?.h), l = Number(c?.l), o = Number(c?.o), cl = Number(c?.c);
    if (![h, l, o, cl].every(Number.isFinite)) continue;
    const range = h - l;
    if (range <= 0) continue;

    let isHigh = true, isLow = true;
    for (let k = i - lookback; k <= i + lookback; k++) {
      if (k === i) continue;
      const kh = Number(candles[k]?.h), kl = Number(candles[k]?.l);
      if (!Number.isFinite(kh) || kh > h) isHigh = false;
      if (!Number.isFinite(kl) || kl < l) isLow = false;
    }

    const volWindowStart = Math.max(0, i - 20);
    const volWindow = vols.slice(volWindowStart, i + 1);
    const avgVol = volWindow.length ? volWindow.reduce((s, v) => s + v, 0) / volWindow.length : 0;
    const volRatio = avgVol > 0 ? (vols[i] / avgVol) : 1;

    if (isHigh) {
      const upperWick = h - Math.max(o, cl);
      out.push({ price: h, type: 'high', index: i, wickRatio: upperWick / range, volRatio });
    }
    if (isLow) {
      const lowerWick = Math.min(o, cl) - l;
      out.push({ price: l, type: 'low', index: i, wickRatio: lowerWick / range, volRatio });
    }
  }
  return out;
}

// Score how well one candidate price aligns with resting liquidity on a
// single timeframe's pivot map. Returns a 0..1 quality score plus context.
function _vldScoreOnTF(candidatePrice, pivots, tolerancePct) {
  if (!pivots.length) return { matched: false, quality: 0, distPct: null, touches: 0 };

  let best = null;
  let touches = 0;
  for (const p of pivots) {
    const distPct = Math.abs(p.price - candidatePrice) / candidatePrice * 100;
    if (distPct <= tolerancePct) {
      touches++;
      const proximity = 1 - (distPct / tolerancePct);          // 1 = exact hit
      const wick = Math.max(0, Math.min(1, p.wickRatio));       // rejection strength
      const vol = Math.max(0, Math.min(1.5, p.volRatio - 1) / 1.5); // volume spike, 0..1
      const quality = proximity * 0.5 + wick * 0.3 + vol * 0.2;
      if (!best || quality > best.quality) {
        best = { quality, distPct, wickRatio: p.wickRatio, volRatio: p.volRatio, type: p.type };
      }
    }
  }
  if (!best) return { matched: false, quality: 0, distPct: null, touches: 0 };
  // Repeated retests of the same zone strengthen it (small capped bonus).
  const touchBonus = Math.min(0.15, (touches - 1) * 0.05);
  return { matched: true, quality: Math.min(1, best.quality + touchBonus), distPct: best.distPct, touches, type: best.type };
}

// Loose psychological / round-number confluence check.
function _vldRoundnessBonus(price) {
  if (!Number.isFinite(price) || price <= 0) return 0;
  const magnitude = Math.pow(10, Math.floor(Math.log10(price)));
  const normalized = price / magnitude;              // 1..10
  const nearest = Math.round(normalized * 20) / 20;   // nearest 0.05 step
  return Math.abs(normalized - nearest) < 0.01 ? 1 : 0;
}

/**
 * Score each candidate liquidity price against pivot/volume structure on
 * 1h, 4h and 1D, and rank them best-first.
 */
async function validateLiquidityPrices(symbol, dir, candidates) {
  const candidateItems = candidates.map(candidate => (
    typeof candidate === 'number'
      ? { price: candidate, source: 'UNSPECIFIED' }
      : candidate
  ));
  const ref = candidateItems[0].price;
  const tolerancePct = ref < 0.01 ? 0.6 : ref < 1 ? 0.45 : ref < 100 ? 0.3 : 0.25;

  const candleSets = await Promise.all(
    VALIDATE_TF_FRAMES.map(f => fetchCandlesCached(symbol, f.tf, f.candles)
      .then(r => Array.isArray(r)
        ? r.filter(c => c && Number.isFinite(Number(c.h)) && Number.isFinite(Number(c.l)))
        : [])
      .catch(() => [])
    )
  );

  const perTF = VALIDATE_TF_FRAMES.map((f, i) => ({
    ...f,
    candleCount: candleSets[i].length,
    pivots: _vldFindPivots(candleSets[i]),
  }));

  const framesWithData = perTF.filter(f => f.candleCount >= 20);
  if (framesWithData.length === 0) {
    throw new Error(`No usable 1h/4h/1D candle data returned for ${symbol}. Check the symbol.`);
  }

  const results = candidateItems.map(candidate => {
    const price = candidate.price;
    const tfHits = perTF.map(tf => ({
      tf: tf.label,
      weight: tf.weight,
      hasData: tf.candleCount >= 20,
      ...(_vldScoreOnTF(price, tf.pivots, tolerancePct)),
    }));
    const matched = tfHits.filter(h => h.matched);
    const confluence = matched.length;
    const weightedQuality = matched.length
      ? matched.reduce((s, h) => s + h.quality * h.weight, 0) / matched.reduce((s, h) => s + h.weight, 0)
      : 0;

    // Confluence band mirrors the existing VAULT MTF reversal-limit scoring
    // in this bot: 3/3 timeframes agreeing is the only path into the 95%+
    // band; fewer confirmations are shown as progressively weaker.
    let base;
    if (confluence === 3) base = 95;
    else if (confluence === 2) base = 80;
    else if (confluence === 1) base = 60;
    else base = 35;

    const qualityBonusMax = confluence === 3 ? 4 : confluence === 2 ? 12 : confluence === 1 ? 15 : 15;
    const qualityBonus = Math.round(weightedQuality * qualityBonusMax);
    const roundBonus = _vldRoundnessBonus(price);
    const score = Math.max(1, Math.min(99, base + qualityBonus + roundBonus));

    return {
      price,
      source: candidate.source || 'UNSPECIFIED',
      score,
      confluence,
      weightedQuality: Math.round(weightedQuality * 100),
      tfHits,
    };
  });

  results.sort((a, b) => b.score - a.score);
  return { symbol, dir, tolerancePct, results, framesUsed: VALIDATE_TF_FRAMES.map(f => f.label) };
}

function formatValidateReport(report) {
  const { symbol, dir, results, framesUsed } = report;
  const winner = results[0];
  const lines = [];
  lines.push(`━━━ 🎯 LIQUIDITY VALIDATOR: ${symbol} ${dir} ━━━`);
  lines.push(`Timeframes checked: ${framesUsed.join(' · ')}`);
  lines.push('');

  results.forEach((r, i) => {
    const medal = i === 0 ? '🥇' : i === 1 ? '🥈' : i === 2 ? '🥉' : '▫️';
    const tfBadges = r.tfHits.map(h => `${h.matched ? '✅' : (h.hasData ? '▫️' : '❔')}${h.tf}`).join(' ');
    lines.push(`${medal} <code>${fmtPrice(r.price)}</code>${_formatLiquiditySourceTag(r.source)} — <b>${r.score}%</b> confluence  (${r.confluence}/3 TFs · ${tfBadges})`);
  });

  lines.push('');
  if (winner.score >= 95) {
    lines.push(`✅ <b>Highest-confidence level: ${fmtPrice(winner.price)}</b> (${winner.score}%)`);
    lines.push(`All three timeframes independently confirm resting liquidity at this level.`);
  } else if (winner.score >= 80) {
    lines.push(`⚠️ <b>Best candidate: ${fmtPrice(winner.price)}</b> (${winner.score}%) — 2/3 timeframe confluence.`);
    lines.push(`Below the 95%+ full-confluence band; treat as strong but not conclusive.`);
  } else {
    lines.push(`⚠️ <b>No candidate reached strong multi-timeframe confluence.</b>`);
    lines.push(`Closest: ${fmtPrice(winner.price)} (${winner.score}%) — use caution or widen the candidate list.`);
  }
  lines.push('');
  lines.push(`<i>Technical liquidity-confluence score (pivot wicks + volume + retests across ${framesUsed.join('/')}), not a guaranteed outcome. No signal can promise a literal 100% probability — use risk management regardless of score.</i>`);

  return lines.join('\n');
}

/* ── Wire /validate into EnhancedQuantumTelegramInterface.handleEnhancedCommand ── */
const _validate_origHandleEnhanced = EnhancedQuantumTelegramInterface.prototype.handleEnhancedCommand;
EnhancedQuantumTelegramInterface.prototype.handleEnhancedCommand = async function(message) {
  const text   = (message?.text || '').trim();
  const chatId = message?.chat?.id;
  const parts  = text.split(/\s+/);
  const cmd    = (parts[0] || '').toLowerCase().replace(/@[^\s]+$/, '');

  if (cmd === '/validate') {
    const sym        = (parts[1] || '').toUpperCase().replace('/', '');
    const dir        = (parts[2] || '').toUpperCase();
    const rawPrices  = parts[3] || '';

    const usage = [
      '🎯 <b>LIQUIDITY PRICE VALIDATOR</b>',
      '',
      'Checks 2-4 candidate liquidity prices against real pivot/volume',
      'structure on 1h, 4h and 1D, and ranks which one is best supported',
      'by multi-timeframe confluence.',
      '',
      '<b>Usage:</b>',
      '/validate SYMBOL BUY|SELL PRICE1,PRICE2,PRICE3[,PRICE4]',
      'Add -(k), (k), or (kraken) to mark a Kraken level.',
      '',
      '<b>Example:</b>',
      '/validate XRPUSDT SELL 0.145-(k),0.1345,0.1356',
    ].join('\n');

    if (!sym || !['BUY', 'SELL'].includes(dir) || !rawPrices) {
      await tg('sendMessage', { chat_id: chatId, parse_mode: 'HTML', text: usage }).catch(() => {});
      return;
    }

    const candidates = _parseTaggedLiquidityPriceList(rawPrices)
      .filter(candidate => Number.isFinite(candidate.price) && candidate.price > 0)
      .filter((candidate, index, all) =>
        all.findIndex(other => other.price === candidate.price) === index
      );

    if (candidates.length < VALIDATE_MIN_CANDIDATES || candidates.length > VALIDATE_MAX_CANDIDATES) {
      await tg('sendMessage', { chat_id: chatId, parse_mode: 'HTML',
        text: `❌ Provide 2-4 comma-separated candidate prices.\n\n${usage}` }).catch(() => {});
      return;
    }

    try {
      await tg('sendMessage', { chat_id: chatId, parse_mode: 'HTML',
        text: `🎯 <b>Validating ${candidates.length} liquidity prices for ${sym} ${dir}</b>...\n<i>Scanning 1h + 4h + 1D pivot & volume structure</i>` }).catch(() => {});

      const report = await validateLiquidityPrices(sym, dir, candidates);
      const msg = formatValidateReport(report);
      await tg('sendMessage', { chat_id: chatId, parse_mode: 'HTML', disable_web_page_preview: true, text: msg }).catch(() => {});
    } catch (e) {
      await tg('sendMessage', { chat_id: chatId, parse_mode: 'HTML',
        text: `❌ Validator error for <b>${sym}</b>: ${e.message}` }).catch(() => {});
    }
    return;
  }

  return _validate_origHandleEnhanced.call(this, message);
};

/* Add /validate to whichever help menu is already active. */
const _validatePreviousHelp = EnhancedQuantumTelegramInterface.prototype.getEnhancedQuantumHelp;
EnhancedQuantumTelegramInterface.prototype.getEnhancedQuantumHelp = function() {
  let base = '';
  try { base = _validatePreviousHelp ? _validatePreviousHelp.call(this) : ''; } catch (_) {}
  const block = [
    '',
    '━━━ 🎯 LIQUIDITY VALIDATOR ━━━',
    '/validate SYMBOL BUY|SELL P1,P2,P3[,P4] — rank candidate liquidity prices by 1h/4h/1D confluence',
    'Mark Kraken levels with -(k), (k), or (kraken).',
    '/validate XRPUSDT SELL 0.145-(k),0.1345,0.1356',
  ].join('\n');
  return base ? base + block : `🎯 <b>Liquidity Validator</b>\n${block}`;
};

/* ============================================================================
   BREAKOUT ASSET BRIDGE
   ----------------------------------------------------------------------------
   Breakout is a funded-trading platform, not a public exchange API. Its
   public materials describe tier-1 centralized-exchange liquidity, so this
   bridge uses Kraken's public market-data endpoints (Breakout's backing
   market-data source) and feeds the resulting assets into the same WATCH,
   candle, order-book, trade-flow, liquidity, and signal pipeline already used
   by the rest of this engine.

   No private Breakout credentials are required. The optional
   BREAKOUT_SYMBOLS environment variable can pin the exact symbols enabled for
   an evaluation. With discovery enabled, Kraken's online USD/USDT/USDC spot
   pairs are discovered and normalised to the engine's XXXUSDT symbol format.
   Breakout execution/account state is intentionally not inferred from public
   market data.
   ========================================================================== */
const BREAKOUT_ENABLED = process.env.BREAKOUT_ENABLED !== '0';
const BREAKOUT_DISCOVERY_ENABLED = process.env.BREAKOUT_DISCOVERY_ENABLED !== '0';
const BREAKOUT_MAX_ASSETS = Math.max(
  1, Math.min(2000, Number(process.env.BREAKOUT_MAX_ASSETS || 500))
);
const BREAKOUT_REFRESH_MS = Math.max(
  15 * 60 * 1000, Number(process.env.BREAKOUT_REFRESH_MS || 6 * 60 * 60 * 1000)
);
const BREAKOUT_EXPLICIT_SYMBOLS = new Set(
  String(process.env.BREAKOUT_SYMBOLS || '')
    .split(',')
    .map(value => value.trim())
    .filter(Boolean)
    .map(value => String(value).toUpperCase().replace(/[^A-Z0-9]/g, ''))
    .map(value => value.endsWith('USD') && !value.endsWith('USDT')
      ? `${value.slice(0, -3)}USDT` : value)
);
const _breakoutPairs = new Map();
const _breakoutSymbols = new Set(BREAKOUT_EXPLICIT_SYMBOLS);
let _breakoutUniverseLoadedAt = 0;
let _breakoutUniverseLoading = null;

function _breakoutCanonicalSymbol(value) {
  const compact = String(value || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
  if (!compact) return '';
  if (compact === 'XBTUSD' || compact === 'XBTUSDT') return 'BTCUSDT';
  if (compact === 'XDGUSD' || compact === 'XDGUSDT') return 'DOGEUSDT';
  if (compact.endsWith('USDT')) return compact;
  if (compact.endsWith('USDC')) return `${compact.slice(0, -4)}USDT`;
  if (compact.endsWith('USD')) return `${compact.slice(0, -3)}USDT`;
  return `${compact}USDT`;
}

function _breakoutBaseFromPair(row) {
  const wsname = String(row?.wsname || '');
  if (wsname.includes('/')) return wsname.split('/')[0].toUpperCase();
  return String(row?.base || row?.baseCurrency || '').toUpperCase()
    .replace(/^X(?=[A-Z])/, '').replace(/^Z(?=[A-Z])/, '');
}

function _breakoutQuoteFromPair(row) {
  const wsname = String(row?.wsname || '');
  if (wsname.includes('/')) return wsname.split('/')[1].toUpperCase();
  return String(row?.quote || row?.quoteCurrency || '').toUpperCase()
    .replace(/^X(?=[A-Z])/, '').replace(/^Z(?=[A-Z])/, '');
}

function _breakoutPairForSymbol(symbol) {
  const canonical = _breakoutCanonicalSymbol(symbol);
  const known = _breakoutPairs.get(canonical);
  if (known) return known;

  const base = canonical.replace(/USDT$/, '');
  const krakenBase = base === 'BTC' ? 'XBT' : base === 'DOGE' ? 'XDG' : base;
  return {
    pair: `${krakenBase}USD`,
    altname: `${krakenBase}USD`,
    wsname: `${krakenBase}/USD`,
    symbol: canonical,
    discovered: false,
  };
}

function isBreakoutSymbol(symbol) {
  const canonical = _breakoutCanonicalSymbol(symbol);
  if (!canonical) return false;
  if (_breakoutSymbols.has(canonical) || _breakoutPairs.has(canonical)) return true;
  try {
    return Boolean(WATCH.get(canonical)?._breakoutAsset);
  } catch (_) {
    return false;
  }
}

function _breakoutRegisterWatch(symbol, metadata = {}) {
  const canonical = _breakoutCanonicalSymbol(symbol);
  if (!canonical || !BREAKOUT_ENABLED) return null;
  _breakoutSymbols.add(canonical);
  const existing = WATCH.get(canonical) || {};
  const pair = _breakoutPairForSymbol(canonical);
  WATCH.set(canonical, {
    ...existing,
    quantum_id: existing.quantum_id || `Q${canonical.replace('USDT', '')}`,
    entanglement: existing.entanglement ?? 0.65,
    coherence: existing.coherence ?? 0.65,
    type: 'breakout',
    leverage: existing.leverage || FUTURES_LEVERAGE,
    tf: existing.tf || '1h',
    added: existing.added || Date.now(),
    score: existing.score || 50,
    _breakoutAsset: true,
    breakoutPair: pair.pair,
    breakoutSource: 'Kraken public market data',
    ...metadata,
  });
  return canonical;
}

async function loadBreakoutAssetUniverse(forceRefresh = false) {
  if (!BREAKOUT_ENABLED) return [];
  const now = Date.now();
  if (!forceRefresh && _breakoutUniverseLoadedAt &&
      now - _breakoutUniverseLoadedAt < BREAKOUT_REFRESH_MS) {
    return [..._breakoutSymbols];
  }
  if (_breakoutUniverseLoading) return _breakoutUniverseLoading;

  _breakoutUniverseLoading = (async () => {
    try {
      if (BREAKOUT_DISCOVERY_ENABLED) {
        const response = await axiosGetSafe(
          process.env.BREAKOUT_ASSET_PAIRS_URL ||
          'https://api.kraken.com/0/public/AssetPairs',
          12000
        );
        const rows = response?.data?.result || {};
        for (const [key, row] of Object.entries(rows)) {
          const status = String(row?.status || 'online').toLowerCase();
          const quote = _breakoutQuoteFromPair(row);
          const base = _breakoutBaseFromPair(row)
            .replace(/^XBT$/, 'BTC').replace(/^XDG$/, 'DOGE');
          if (status !== 'online' || !base || !['USD', 'USDT', 'USDC'].includes(quote)) continue;
          const symbol = _breakoutCanonicalSymbol(`${base}USDT`);
          _breakoutPairs.set(symbol, {
            pair: String(row?.altname || key),
            altname: String(row?.altname || key),
            wsname: String(row?.wsname || `${base}/${quote}`),
            symbol,
            base,
            quote,
            discovered: true,
          });
          _breakoutSymbols.add(symbol);
        }
      }
    } catch (error) {
      console.warn(`⚠️ Breakout asset discovery failed: ${error.message}`);
    }

    const explicit = [...BREAKOUT_EXPLICIT_SYMBOLS];
    for (const symbol of explicit) _breakoutRegisterWatch(symbol);

    const candidates = [..._breakoutSymbols]
      .sort((a, b) => a.localeCompare(b))
      .slice(0, BREAKOUT_MAX_ASSETS);
    for (const symbol of candidates) {
      const pair = _breakoutPairs.get(symbol) || _breakoutPairForSymbol(symbol);
      _breakoutRegisterWatch(symbol, {
        breakoutPair: pair.pair,
        breakoutQuote: pair.quote || 'USD',
      });
    }
    _breakoutUniverseLoadedAt = Date.now();
    console.log(`🚀 Breakout asset bridge: ${candidates.length} assets registered`);
    return candidates;
  })().finally(() => {
    _breakoutUniverseLoading = null;
  });
  return _breakoutUniverseLoading;
}

async function _breakoutTicker(symbol) {
  const pair = _breakoutPairForSymbol(symbol);
  const response = await axiosGetSafe(
    `https://api.kraken.com/0/public/Ticker?pair=${encodeURIComponent(pair.pair)}`,
    8000
  );
  const result = response?.data?.result || {};
  const row = Object.values(result)[0];
  if (!row) return null;
  const last = Number(row.c?.[0] || row.last);
  if (!Number.isFinite(last) || last <= 0) return null;
  return {
    last,
    bid: Number(row.b?.[0] || 0),
    ask: Number(row.a?.[0] || 0),
    volume24h: Number(row.v?.[1] || row.v?.[0] || 0),
    high24h: Number(row.h?.[1] || row.h?.[0] || 0),
    low24h: Number(row.l?.[1] || row.l?.[0] || 0),
    open24h: Number(row.o || 0),
    pair: pair.pair,
  };
}

function _breakoutKrakenInterval(tf) {
  return {
    '1min': 1, '5min': 5, '15min': 15, '30min': 30,
    '1h': 60, '2h': 60, '4h': 240, '8h': 240,
    '1day': 1440, '2day': 1440, '3day': 1440, '1week': 10080,
  }[tf] || 60;
}

function _breakoutAggregateCandles(candles, groupSize) {
  if (groupSize <= 1) return candles;
  const output = [];
  for (let i = 0; i + groupSize - 1 < candles.length; i += groupSize) {
    const group = candles.slice(i, i + groupSize);
    output.push({
      t: group[0].t, o: group[0].o,
      h: Math.max(...group.map(c => c.h)),
      l: Math.min(...group.map(c => c.l)),
      c: group[group.length - 1].c,
      v: group.reduce((sum, c) => sum + c.v, 0),
      qv: group.reduce((sum, c) => sum + (c.qv || c.v * c.c), 0),
      bullish: group[group.length - 1].c >= group[0].o,
    });
  }
  return output;
}

async function _breakoutCandles(symbol, tf, limit = 200) {
  const pair = _breakoutPairForSymbol(symbol);
  const aggregateSize = tf === '8h' ? 2 : tf === '2day' ? 2 : tf === '3day' ? 3 : 1;
  const response = await axiosGetSafe(
    `https://api.kraken.com/0/public/OHLC?pair=${encodeURIComponent(pair.pair)}` +
      `&interval=${_breakoutKrakenInterval(tf)}`,
    10000
  );
  const rows = Object.values(response?.data?.result || {}).find(Array.isArray) || [];
  const candles = rows.map(row => ({
    t: Number(row[0]) * 1000, o: Number(row[1]), h: Number(row[2]),
    l: Number(row[3]), c: Number(row[4]), v: Number(row[6] || 0),
    qv: Number(row[6] || 0) * Number(row[4] || 0),
  })).filter(c =>
    c.t > 0 && c.o > 0 && c.h > 0 && c.l > 0 && c.c > 0 && c.h >= c.l
  );
  return _breakoutAggregateCandles(candles, aggregateSize).slice(-limit);
}

async function _breakoutOrderBook(symbol, limit = 50) {
  const pair = _breakoutPairForSymbol(symbol);
  const response = await axiosGetSafe(
    `https://api.kraken.com/0/public/Depth?pair=${encodeURIComponent(pair.pair)}` +
      `&count=${Math.min(500, Math.max(1, limit))}`,
    8000
  );
  const row = Object.values(response?.data?.result || {})[0];
  if (!row) return null;
  return {
    bids: (row.bids || []).map(level => [level[0], level[1]]),
    asks: (row.asks || []).map(level => [level[0], level[1]]),
  };
}

async function _breakoutTrades(symbol, limit = 100) {
  const pair = _breakoutPairForSymbol(symbol);
  const response = await axiosGetSafe(
    `https://api.kraken.com/0/public/Trades?pair=${encodeURIComponent(pair.pair)}`,
    8000
  );
  const row = Object.values(response?.data?.result || {}).find(Array.isArray) || [];
  return row.slice(-Math.min(1000, limit)).map(trade => [
    trade[0], trade[1], trade[2], trade[3] === 's' ? 'sell' : 'buy', trade[4] || 'market'
  ]);
}

function _breakoutLiquidityMetrics(book, ticker) {
  const bids = book?.bids || [], asks = book?.asks || [];
  const bidLevels = bids.map(v => [Number(v[0]), Number(v[1])]).filter(v => v[0] > 0 && v[1] > 0);
  const askLevels = asks.map(v => [Number(v[0]), Number(v[1])]).filter(v => v[0] > 0 && v[1] > 0);
  const bestBid = bidLevels[0]?.[0] || ticker?.bid || 0;
  const bestAsk = askLevels[0]?.[0] || ticker?.ask || 0;
  const mid = bestBid && bestAsk ? (bestBid + bestAsk) / 2 : ticker?.last || 0;
  const within = (levels, pct) => levels
    .filter(([price]) => mid > 0 && Math.abs(price - mid) / mid <= pct)
    .reduce((sum, [price, quantity]) => sum + price * quantity, 0);
  const bidNotional1Pct = within(bidLevels, 0.01);
  const askNotional1Pct = within(askLevels, 0.01);
  const total1Pct = bidNotional1Pct + askNotional1Pct;
  const spreadPct = bestBid > 0 && bestAsk > 0 ? ((bestAsk - bestBid) / bestBid) * 100 : null;
  const imbalance = total1Pct > 0 ? (bidNotional1Pct - askNotional1Pct) / total1Pct : 0;
  let grade = 'UNAVAILABLE';
  if (total1Pct > 0) {
    grade = spreadPct <= 0.05 && total1Pct >= 1000000 ? 'A' :
      spreadPct <= 0.20 && total1Pct >= 100000 ? 'B' :
      spreadPct <= 0.75 ? 'C' : 'D';
  }
  return {
    bestBid, bestAsk, mid, spreadPct,
    bidNotional1Pct, askNotional1Pct, totalNotional1Pct: total1Pct,
    imbalance, grade, levels: bidLevels.length + askLevels.length,
  };
}

const _breakoutOriginalFetchLivePrice = fetchLivePrice;
fetchLivePrice = async function(symbol) {
  if (!BREAKOUT_ENABLED || !isBreakoutSymbol(symbol)) {
    return _breakoutOriginalFetchLivePrice(symbol);
  }
  try {
    const ticker = await _breakoutTicker(symbol);
    if (ticker?.last) {
      updateTick(symbol, ticker.last);
      _livePriceCache.set(symbol, { price: ticker.last, ts: Date.now() });
      return ticker.last;
    }
  } catch (error) {
    console.warn(`Breakout price fetch failed for ${symbol}: ${error.message}`);
  }
  return null;
};

const _breakoutOriginalFetchCandles = fetchCandles;
fetchCandles = async function(symbol, tf, limit = 200) {
  if (!BREAKOUT_ENABLED || !isBreakoutSymbol(symbol)) {
    return _breakoutOriginalFetchCandles(symbol, tf, limit);
  }
  try {
    const candles = await _breakoutCandles(symbol, tf, limit);
    return candles.length >= 2 ? candles : null;
  } catch (error) {
    console.warn(`Breakout candle fetch failed for ${symbol} ${tf}: ${error.message}`);
    return null;
  }
};

// Existing institutional and websocket consumers speak the Bitget response
// shape. Adapting at this boundary lets every downstream liquidity consumer
// work without a second Breakout-only implementation.
const _originalGetOrderBook = bitgetAPI.getOrderBook.bind(bitgetAPI);
bitgetAPI.getOrderBook = async function(symbol, limit = 50) {
  if (!BREAKOUT_ENABLED || !isBreakoutSymbol(symbol)) {
    return _originalGetOrderBook(symbol, limit);
  }
  try {
    const book = await _breakoutOrderBook(symbol, limit);
    return book ? { code: '00000', data: book, source: 'breakout-kraken-public' } : null;
  } catch (error) {
    console.warn(`Breakout order book fetch failed for ${symbol}: ${error.message}`);
    return null;
  }
};
const _originalGetTrades = bitgetAPI.getTrades.bind(bitgetAPI);
bitgetAPI.getTrades = async function(symbol, limit = 100) {
  if (!BREAKOUT_ENABLED || !isBreakoutSymbol(symbol)) {
    return _originalGetTrades(symbol, limit);
  }
  try {
    const trades = await _breakoutTrades(symbol, limit);
    return { code: '00000', data: trades, source: 'breakout-kraken-public' };
  } catch (error) {
    console.warn(`Breakout trades fetch failed for ${symbol}: ${error.message}`);
    return null;
  }
};

// Breakout does not publish a liquidation-orders endpoint. Return an explicit
// zero/unknown result for those symbols so the shared cascade-risk engine does
// not mistake generated placeholder numbers for observed liquidations.
const _originalLiquidationFetch = LiquidationRiskAnalyzer.prototype.fetchLiquidationData;
LiquidationRiskAnalyzer.prototype.fetchLiquidationData = async function(symbol) {
  if (!BREAKOUT_ENABLED || !isBreakoutSymbol(symbol)) {
    return _originalLiquidationFetch.call(this, symbol);
  }
  try {
    const price = await fetchLivePrice(symbol);
    const result = {
      symbol,
      total_liquidations: 0,
      long_liquidations: 0,
      short_liquidations: 0,
      long_volume: 0,
      short_volume: 0,
      net_liquidation_volume: 0,
      clusters: [],
      estimated_levels: this.estimateLiquidationLevels(symbol, price),
      current_price: price,
      source: 'unavailable — Breakout public liquidation feed not exposed',
      observed: false,
      timestamp: Date.now(),
    };
    this.liquidationHistory.set(symbol, result);
    return result;
  } catch (error) {
    console.warn(`Breakout liquidation state unavailable for ${symbol}: ${error.message}`);
    return {
      symbol, total_liquidations: 0, long_liquidations: 0, short_liquidations: 0,
      long_volume: 0, short_volume: 0, net_liquidation_volume: 0, clusters: [],
      estimated_levels: {}, current_price: null, observed: false,
      source: 'unavailable — Breakout public liquidation feed not exposed',
      timestamp: Date.now(),
    };
  }
};

async function getBreakoutAssetReport(requestedSymbol) {
  await loadBreakoutAssetUniverse(false);
  const symbol = _breakoutRegisterWatch(requestedSymbol);
  if (!symbol) throw new Error('Invalid Breakout symbol.');
  const [ticker, book, candles] = await Promise.all([
    _breakoutTicker(symbol),
    _breakoutOrderBook(symbol, 50).catch(() => null),
    _breakoutCandles(symbol, '1h', 100).catch(() => []),
  ]);
  if (!ticker) throw new Error(`No public Breakout/Kraken ticker found for ${symbol}.`);
  const liquidity = _breakoutLiquidityMetrics(book, ticker);
  const ranges = candles.slice(-20).map(c => c.h - c.l).filter(v => v > 0);
  const avgRange = ranges.length ? ranges.reduce((a, b) => a + b, 0) / ranges.length : 0;
  const avgVolume = candles.length
    ? candles.slice(-20).reduce((sum, c) => sum + c.v, 0) / Math.min(20, candles.length)
    : 0;
  const lastVolume = candles[candles.length - 1]?.v || 0;
  const pair = _breakoutPairForSymbol(symbol);
  return {
    symbol, pair: pair.pair, source: 'Kraken public market data via Breakout bridge',
    executionVenue: 'Breakout account (execution state is private and not read)',
    price: ticker.last, bid: ticker.bid, ask: ticker.ask,
    volume24h: ticker.volume24h, turnover24h: ticker.volume24h * ticker.last,
    high24h: ticker.high24h, low24h: ticker.low24h, open24h: ticker.open24h,
    change24hPct: ticker.open24h > 0 ? ((ticker.last - ticker.open24h) / ticker.open24h) * 100 : null,
    liquidity, candleCount: candles.length,
    atrProxy1h: avgRange, avgVolume1h: avgVolume,
    latestVolumeRatio: avgVolume > 0 ? lastVolume / avgVolume : null,
    liquidationData: 'Breakout public liquidation feed is not exposed; no synthetic liquidation values are used.',
    timestamp: Date.now(),
  };
}

function _breakoutFmt(value, digits = 6) {
  return Number.isFinite(Number(value)) ? Number(value).toPrecision(digits) : 'N/A';
}

function formatBreakoutAssetReport(report) {
  const liq = report.liquidity || {};
  const pct = value => Number.isFinite(Number(value)) ? `${Number(value).toFixed(3)}%` : 'N/A';
  return [
    `🚀 <b>BREAKOUT ASSET LIQUIDITY — ${report.symbol}</b>`,
    `Source: <b>${report.source}</b>`,
    `Market pair: <code>${report.pair}</code> · Price: <code>${_breakoutFmt(report.price)}</code>`,
    `24h: <b>${pct(report.change24hPct)}</b> · Turnover: <b>$${_breakoutFmt(report.turnover24h, 5)}</b>`,
    `24h range: <code>${_breakoutFmt(report.low24h)}</code> → <code>${_breakoutFmt(report.high24h)}</code>`,
    '',
    `━━━ ORDER-BOOK LIQUIDITY ━━━`,
    `Best bid/ask: <code>${_breakoutFmt(report.bid)}</code> / <code>${_breakoutFmt(report.ask)}</code>`,
    `Spread: <b>${pct(liq.spreadPct)}</b> · 1% depth: <b>$${_breakoutFmt(liq.totalNotional1Pct, 5)}</b>`,
    `Bid depth: $${_breakoutFmt(liq.bidNotional1Pct, 5)} · Ask depth: $${_breakoutFmt(liq.askNotional1Pct, 5)}`,
    `Book imbalance: <b>${Number.isFinite(liq.imbalance) ? (liq.imbalance * 100).toFixed(2) + '%' : 'N/A'}</b> · Grade: <b>${liq.grade}</b>`,
    '',
    `━━━ ENGINE INPUTS ━━━`,
    `1h candles: <b>${report.candleCount}</b> · ATR proxy: <code>${_breakoutFmt(report.atrProxy1h)}</code>`,
    `Latest volume / 20-bar average: <b>${report.latestVolumeRatio ? report.latestVolumeRatio.toFixed(2) + 'x' : 'N/A'}</b>`,
    `✅ Candles, live price, order book, trade flow and liquidity map use the same downstream engine contracts as other assets.`,
    `ℹ️ ${report.liquidationData}`,
  ].join('\n');
}

const _breakoutOriginalHandler = EnhancedQuantumTelegramInterface.prototype.handleEnhancedCommand;
EnhancedQuantumTelegramInterface.prototype.handleEnhancedCommand = async function(message) {
  const text = String(message?.text || '').trim();
  const parts = text.split(/\s+/);
  const cmd = (parts[0] || '').toLowerCase().replace(/@[^\s]+$/, '');
  const chatId = message?.chat?.id;
  if (cmd === '/breakout' || cmd === '/breakoutasset' || cmd === '/bo') {
    if (typeof isAdminMessage === 'function' && !isAdminMessage(message)) return;
    const symbol = parts[1];
    if (!symbol) {
      await tg('sendMessage', {
        chat_id: chatId, parse_mode: 'HTML',
        text: [
          '🚀 <b>BREAKOUT ASSET BRIDGE</b>', '',
          '<b>Usage:</b> /breakout SYMBOL',
          '<b>Examples:</b> /breakout BTCUSDT · /breakout SOLUSD',
          '',
          'Use /breakoutassets to see discovered assets.',
          'Breakout account execution and private liquidation data are not inferred from public market data.',
        ].join('\n'),
      }).catch(() => {});
      return;
    }
    try {
      await tg('sendMessage', {
        chat_id: chatId, parse_mode: 'HTML',
        text: `🚀 <b>Mapping Breakout liquidity for ${_breakoutCanonicalSymbol(symbol)}...</b>`,
      }).catch(() => {});
      const report = await getBreakoutAssetReport(symbol);
      await tg('sendMessage', {
        chat_id: chatId, parse_mode: 'HTML', disable_web_page_preview: true,
        text: formatBreakoutAssetReport(report),
      }).catch(() => {});
    } catch (error) {
      await tg('sendMessage', {
        chat_id: chatId, parse_mode: 'HTML',
        text: `❌ Breakout asset error: ${error.message}`,
      }).catch(() => {});
    }
    return;
  }
  if (cmd === '/breakoutassets') {
    if (typeof isAdminMessage === 'function' && !isAdminMessage(message)) return;
    try {
      const symbols = await loadBreakoutAssetUniverse(false);
      const shown = symbols.slice(0, 40);
      await tg('sendMessage', {
        chat_id: chatId, parse_mode: 'HTML',
        text: [
          `🚀 <b>BREAKOUT ASSETS</b> — ${symbols.length} registered`,
          '',
          shown.length ? shown.map((s, i) => `${i + 1}. <code>${s}</code>`).join('\n') : 'No assets discovered.',
          '',
          '<i>Use /breakout SYMBOL for the live liquidity card.</i>',
        ].join('\n'),
      }).catch(() => {});
    } catch (error) {
      await tg('sendMessage', {
        chat_id: chatId, parse_mode: 'HTML',
        text: `❌ Breakout asset discovery error: ${error.message}`,
      }).catch(() => {});
    }
    return;
  }
  return _breakoutOriginalHandler.call(this, message);
};

const _breakoutPreviousHelp = EnhancedQuantumTelegramInterface.prototype.getEnhancedQuantumHelp;
EnhancedQuantumTelegramInterface.prototype.getEnhancedQuantumHelp = function() {
  let base = '';
  try { base = _breakoutPreviousHelp ? _breakoutPreviousHelp.call(this) : ''; } catch (_) {}
  const block = [
    '',
    '━━━ 🚀 BREAKOUT ASSET BRIDGE ━━━',
    '/breakout SYMBOL — map live price, candles, order-book depth, trade flow and liquidity',
    '/breakoutassets — list discovered Breakout/Kraken market assets',
  ].join('\n');
  return base ? base + block : `🚀 <b>Breakout Asset Bridge</b>\n${block}`;
};

