/* ============================================================================
   LIQUIDITY VENUE LABELS
   ----------------------------------------------------------------------------
   A level marked with (K), -(k), or -(kraken) is explicitly Kraken-sourced.
   Unmarked manual candidates remain unverified; automatically generated
   Breakout levels are Kraken-backed, while non-Breakout levels are shown as
   non-Kraken exchange/engine references.
   ========================================================================== */
function _normaliseLiquiditySource(source) {
  const value = String(source || '').trim().toUpperCase();
  if (value === 'K' || value === 'KRAKEN') return 'KRAKEN';
  if (value === 'X' || value === 'OTHER' || value === 'OTHER_EXCHANGE') return 'OTHER_EXCHANGE';
  return 'UNSPECIFIED';
}

function _formatLiquiditySourceTag(source) {
  const venue = _normaliseLiquiditySource(source);
  return venue === 'KRAKEN' ? ' (K)'
    : venue === 'OTHER_EXCHANGE' ? ' (X)'
    : ' (U)';
}

function _liquidityVenueForSymbol(symbol) {
  return typeof isBreakoutSymbol === 'function' && isBreakoutSymbol(symbol)
    ? 'KRAKEN'
    : 'OTHER_EXCHANGE';
}

function _parseTaggedLiquidityPriceList(rawPrices) {
  return String(rawPrices || '')
    .split(',')
    .map(raw => {
      const text = raw.trim();
      const isKraken = /^\s*\(\s*(?:k|kraken)\s*\)/i.test(text) ||
        /(?:^|[-\s])\(\s*(?:k|kraken)\s*\)\s*$/i.test(text) ||
        /^\s*(?:k|kraken)\s*:\s*/i.test(text);
      const cleaned = text
        .replace(/\(\s*(?:k|kraken)\s*\)/ig, '')
        .replace(/^\s*(?:k|kraken)\s*:\s*/i, '')
        .replace(/\s*-\s*$/g, '')
        .trim();
      return {
        price: Number(cleaned),
        source: isKraken ? 'KRAKEN' : 'UNSPECIFIED',
      };
    });
}

function _markLiquidityPriceCodes(message, symbol, sourceOverride) {
  const source = sourceOverride || _liquidityVenueForSymbol(symbol);
  const tag = _formatLiquiditySourceTag(source);
  const text = String(message || '');
  return text.replace(/(<code>[^<]+<\/code>)/g, `$1${tag}`);
}

function _addLiquidityVenueLegend(message) {
  return `${message}\n<i>Venue markers: (K) Kraken-backed liquidity · (X) non-Kraken exchange/engine reference · (U) source not explicitly verified.</i>`;
}

const _venueTaggedFormatAPEX = formatAPEX;
formatAPEX = function(apex, dir) {
  const message = _venueTaggedFormatAPEX(apex, dir);
  if (!message) return message;
  return _addLiquidityVenueLegend(
    _markLiquidityPriceCodes(message, apex?.symbol, apex?.source)
  );
};

const _venueTaggedFormatATLAS = formatATLAS;
formatATLAS = function(atlas, dir) {
  const message = _venueTaggedFormatATLAS(atlas, dir);
  if (!message) return message;
  return _addLiquidityVenueLegend(
    _markLiquidityPriceCodes(message, atlas?.symbol, atlas?.source)
  );
};

const _venueTaggedFormatSweepDirection = formatSweepDirection;
formatSweepDirection = function(sweep) {
  const message = _venueTaggedFormatSweepDirection(sweep);
  if (!message) return message;
  return _addLiquidityVenueLegend(
    _markLiquidityPriceCodes(message, sweep?.symbol, sweep?.source)
  );
};



