/* ============================================================================
   TOTAL MARKET DECISION ENGINE
   ----------------------------------------------------------------------------
   Intraday direction and the limit plan use ONLY closed 4H and 1H candles.
   Both timeframes must be strong and agree; visible recent sweep/rejection
   evidence or a missing confluence zone forces WAIT. No other timeframe is
   consulted by this command.

   The score is confluence, not win probability. A limit order can remain
   unfilled, and candle data cannot prove that manipulation is absent.
   ========================================================================== */

function normalizeDecisionSymbol(raw) {
  let symbol = String(raw || '').trim().toUpperCase();
  if (!symbol) return null;
  if (symbol.includes('/')) return symbol.replace(/[^A-Z0-9/]/g, '');
  symbol = symbol.replace(/[^A-Z0-9]/g, '');
  if (!symbol) return null;
  return symbol.endsWith('USDT') ? symbol : `${symbol}USDT`;
}

function _tdNum(value, fallback = 0) {
  const n = Number(value);
  return Number.isFinite(n) ? n : fallback;
}

function _tdEma(values, period) {
  const source = (values || []).map(Number).filter(Number.isFinite);
  if (!source.length) return 0;
  const p = Math.max(2, Math.min(Number(period) || 2, source.length));
  const k = 2 / (p + 1);
  return source.reduce((ema, value, index) =>
    index === 0 ? value : value * k + ema * (1 - k), source[0]);
}

function _tdRsi(candles, period = 14) {
  if (!Array.isArray(candles) || candles.length < 3) return 50;
  const closes = candles.map(c => _tdNum(c?.c)).filter(v => v > 0);
  if (closes.length < 3) return 50;
  const p = Math.min(period, closes.length - 1);
  let gains = 0, losses = 0;
  for (let i = closes.length - p; i < closes.length; i++) {
    const change = closes[i] - closes[i - 1];
    if (change >= 0) gains += change;
    else losses += Math.abs(change);
  }
  if (losses === 0) return gains > 0 ? 100 : 50;
  return 100 - (100 / (1 + (gains / p) / (losses / p)));
}

function _tdAtr(candles, period = 14) {
  if (!Array.isArray(candles) || !candles.length) return 0;
  const recent = candles.slice(-Math.min(period, candles.length));
  return recent.reduce((sum, c) => sum + Math.max(0, _tdNum(c?.h) - _tdNum(c?.l)), 0) /
    Math.max(1, recent.length);
}

function _tdFmt(value) {
  const n = Number(value);
  if (!Number.isFinite(n)) return '—';
  if (Math.abs(n) >= 1000) return n.toFixed(2);
  if (Math.abs(n) >= 1) return n.toFixed(4);
  return n.toFixed(6);
}

function _tdPct(value) {
  const n = Number(value);
  return Number.isFinite(n) ? `${n >= 0 ? '+' : ''}${n.toFixed(2)}%` : '—';
}

function _tdTimeframeMs(tf) {
  const intervals = { '5min': 300000, '5m': 300000, '15min': 900000, '15m': 900000, '1h': 3600000, '4h': 14400000 };
  return intervals[String(tf || '').toLowerCase()] || 3600000;
}

function _tdClosedCandles(tf, candles, now = Date.now()) {
  const intervalMs = _tdTimeframeMs(tf);
  return (Array.isArray(candles) ? candles : []).filter(c => {
    const o = _tdNum(c?.o), h = _tdNum(c?.h), l = _tdNum(c?.l), close = _tdNum(c?.c);
    let openedAt = Number(c?.t);
    if (![o, h, l, close].every(v => v > 0) || h < l || !Number.isFinite(openedAt)) return false;
    if (openedAt < 1e12) openedAt *= 1000;
    return openedAt + intervalMs <= now;
  });
}

function _tdCandleVolume(candle) {
  const quoteVolume = _tdNum(candle?.qv);
  return quoteVolume > 0 ? quoteVolume : _tdNum(candle?.v);
}

function _tdMedian(values) {
  const sorted = (Array.isArray(values) ? values : [])
    .map(Number).filter(Number.isFinite).sort((a, b) => a - b);
  if (!sorted.length) return 0;
  const middle = Math.floor(sorted.length / 2);
  return sorted.length % 2 ? sorted[middle] : (sorted[middle - 1] + sorted[middle]) / 2;
}

function _tdFindConfirmedSwings(candles, lookback = 48) {
  const bars = Array.isArray(candles) ? candles : [];
  const first = Math.max(2, bars.length - lookback);
  const highs = [], lows = [];
  for (let i = first; i < bars.length - 2; i++) {
    const high = _tdNum(bars[i].h), low = _tdNum(bars[i].l);
    const neighbors = [bars[i - 2], bars[i - 1], bars[i + 1], bars[i + 2]];
    const highValues = neighbors.map(c => _tdNum(c.h));
    const lowValues = neighbors.map(c => _tdNum(c.l));
    if (highValues.every(value => high >= value) && highValues.some(value => high > value)) {
      const previous = highs.at(-1);
      if (previous && i - previous.index < 4) {
        if (high > previous.price) highs[highs.length - 1] = { index: i, price: high };
      } else highs.push({ index: i, price: high });
    }
    if (lowValues.every(value => low <= value) && lowValues.some(value => low < value)) {
      const previous = lows.at(-1);
      if (previous && i - previous.index < 4) {
        if (low < previous.price) lows[lows.length - 1] = { index: i, price: low };
      } else lows.push({ index: i, price: low });
    }
  }
  return { highs, lows };
}

function _tdDirectionalDisplacementAt(candles, index, direction, atr, lookback = 6) {
  const bars = Array.isArray(candles) ? candles : [];
  if (index < lookback || index >= bars.length || !(atr > 0)) return null;
  const bar = bars[index];
  const prior = bars.slice(index - lookback, index);
  const range = _tdNum(bar.h) - _tdNum(bar.l);
  const body = Math.abs(_tdNum(bar.c) - _tdNum(bar.o));
  if (!(range > 0)) return null;
  const bodyRatio = body / range;
  const closePosition = (_tdNum(bar.c) - _tdNum(bar.l)) / range;
  const priorHigh = Math.max(...prior.map(c => _tdNum(c.h)));
  const priorLow = Math.min(...prior.map(c => _tdNum(c.l)));
  const structureLevel = direction === 'BUY' ? priorHigh : priorLow;
  const brokeStructure = direction === 'BUY'
    ? _tdNum(bar.c) > priorHigh + atr * 0.05
    : _tdNum(bar.c) < priorLow - atr * 0.05;
  const bodyBaseline = _tdMedian(bars.slice(Math.max(0, index - 20), index)
    .map(c => Math.abs(_tdNum(c.c) - _tdNum(c.o))));
  const volumeBaseline = _tdMedian(bars.slice(Math.max(0, index - 20), index)
    .map(_tdCandleVolume));
  const volumeRatio = volumeBaseline > 0 ? _tdCandleVolume(bar) / volumeBaseline : 0;
  const directionalBody = direction === 'BUY'
    ? _tdNum(bar.c) > _tdNum(bar.o) && closePosition >= 0.75
    : _tdNum(bar.c) < _tdNum(bar.o) && closePosition <= 0.25;
  if (!directionalBody || !brokeStructure ||
      body < Math.max(atr * 0.55, bodyBaseline * 1.5) ||
      bodyRatio < 0.58 || volumeRatio < 1.15) return null;

  return {
    index,
    direction,
    body,
    bodyRatio,
    atrMultiple: body / atr,
    volumeRatio,
    structureLevel,
    closePosition,
  };
}

function _tdFindOrderBlockBefore(candles, displacement, atr) {
  if (!displacement || !(atr > 0)) return null;
  const bars = Array.isArray(candles) ? candles : [];
  const first = Math.max(0, displacement.index - 6);
  for (let i = displacement.index - 1; i >= first; i--) {
    const bar = bars[i];
    const opposing = displacement.direction === 'BUY'
      ? _tdNum(bar.c) < _tdNum(bar.o)
      : _tdNum(bar.c) > _tdNum(bar.o);
    const zoneLow = _tdNum(bar.l), zoneHigh = _tdNum(bar.h);
    if (!opposing || !(zoneHigh > zoneLow) || zoneHigh - zoneLow > atr * 2.5) continue;
    const laterBars = bars.slice(displacement.index + 1);
    const invalidated = laterBars.some(c => displacement.direction === 'BUY'
      ? _tdNum(c.c) < zoneLow
      : _tdNum(c.c) > zoneHigh);
    if (invalidated) continue;
    return {
      direction: displacement.direction,
      low: zoneLow,
      high: zoneHigh,
      candleIndex: i,
      displacementIndex: displacement.index,
      displacementVolumeRatio: displacement.volumeRatio,
    };
  }
  return null;
}

function _tdBuildFourHourStructure(candles, atr) {
  const bars = Array.isArray(candles) ? candles : [];
  const swings = _tdFindConfirmedSwings(bars, 48);
  const previousHigh = swings.highs.at(-2), lastHigh = swings.highs.at(-1);
  const previousLow = swings.lows.at(-2), lastLow = swings.lows.at(-1);
  const higherHigh = !!(previousHigh && lastHigh && lastHigh.price > previousHigh.price + atr * 0.05);
  const higherLow = !!(previousLow && lastLow && lastLow.price > previousLow.price + atr * 0.05);
  const lowerHigh = !!(previousHigh && lastHigh && lastHigh.price < previousHigh.price - atr * 0.05);
  const lowerLow = !!(previousLow && lastLow && lastLow.price < previousLow.price - atr * 0.05);
  const swingBias = higherHigh && higherLow ? 'BUY'
    : lowerHigh && lowerLow ? 'SELL' : 'NEUTRAL';

  let displacement = null, orderBlock = null;
  for (let i = bars.length - 1; i >= Math.max(20, bars.length - 12); i--) {
    const candidates = [
      _tdDirectionalDisplacementAt(bars, i, 'BUY', atr, 6),
      _tdDirectionalDisplacementAt(bars, i, 'SELL', atr, 6),
    ].filter(Boolean);
    if (!candidates.length) continue;
    displacement = candidates[0];
    orderBlock = _tdFindOrderBlockBefore(bars, displacement, atr);
    if (orderBlock) break;
    displacement = null;
  }

  const rangeHigh = swings.highs.length
    ? Math.max(...swings.highs.slice(-3).map(point => point.price)) : 0;
  const rangeLow = swings.lows.length
    ? Math.min(...swings.lows.slice(-3).map(point => point.price)) : 0;
  const rangeMid = rangeHigh > rangeLow ? (rangeHigh + rangeLow) / 2 : 0;
  const bias = displacement?.direction || swingBias;
  const swingState = higherHigh && higherLow ? 'HH + HL'
    : lowerHigh && lowerLow ? 'LH + LL'
      : displacement ? `${displacement.direction} BOS / structure shift`
        : 'Mixed / unconfirmed';
  return {
    bias,
    swingBias,
    swingState,
    higherHigh,
    higherLow,
    lowerHigh,
    lowerLow,
    lastSwingHigh: lastHigh?.price || 0,
    lastSwingLow: lastLow?.price || 0,
    rangeHigh,
    rangeLow,
    rangeMid,
    displacement,
    orderBlock,
    aligned: !!bias && bias !== 'NEUTRAL' && !!orderBlock && orderBlock.direction === bias,
  };
}

function _tdFindLiquiditySweep(candles, direction, firstIndex, lastIndex) {
  const bars = Array.isArray(candles) ? candles : [];
  for (let i = Math.min(lastIndex, bars.length - 1); i >= Math.max(8, firstIndex); i--) {
    const prior = bars.slice(i - 8, i);
    if (prior.length < 8) continue;
    const priorHigh = Math.max(...prior.map(c => _tdNum(c.h)));
    const priorLow = Math.min(...prior.map(c => _tdNum(c.l)));
    const bar = bars[i];
    const sweptLow = _tdNum(bar.l) < priorLow && _tdNum(bar.c) > priorLow;
    const sweptHigh = _tdNum(bar.h) > priorHigh && _tdNum(bar.c) < priorHigh;
    if (direction === 'BUY' && sweptLow) {
      return { index: i, side: 'low', level: priorLow, reclaimed: true };
    }
    if (direction === 'SELL' && sweptHigh) {
      return { index: i, side: 'high', level: priorHigh, reclaimed: true };
    }
  }
  return null;
}

function _tdBuildOneHourExecution(candles, direction, atr) {
  const bars = Array.isArray(candles) ? candles : [];
  if (bars.length < 30 || !['BUY', 'SELL'].includes(direction) || !(atr > 0)) {
    return { confirmed: false, reason: 'Not enough closed 1H data for an execution trigger.' };
  }
  const firstEvent = Math.max(20, bars.length - 14);
  for (let i = bars.length - 1; i >= firstEvent; i--) {
    const displacement = _tdDirectionalDisplacementAt(bars, i, direction, atr, 5);
    if (!displacement) continue;
    const twoBarsBack = bars[i - 2];
    const current = bars[i];
    const fvgLow = direction === 'BUY' ? _tdNum(twoBarsBack.h) : _tdNum(current.h);
    const fvgHigh = direction === 'BUY' ? _tdNum(current.l) : _tdNum(twoBarsBack.l);
    if (fvgHigh - fvgLow < atr * 0.05) continue;
    const invalidated = bars.slice(i + 1).some(bar => direction === 'BUY'
      ? _tdNum(bar.c) < fvgLow
      : _tdNum(bar.c) > fvgHigh);
    if (invalidated) continue;

    const sweep = _tdFindLiquiditySweep(bars, direction, Math.max(8, i - 8), i - 1);
    if (!sweep) continue;
    const impulseBars = bars.slice(sweep.index, i + 1);
    const impulseLow = Math.min(...impulseBars.map(c => _tdNum(c.l)));
    const impulseHigh = Math.max(...impulseBars.map(c => _tdNum(c.h)));
    if (impulseHigh - impulseLow < atr * 1.25) continue;
    return {
      confirmed: true,
      direction,
      sweep,
      displacement,
      fvg: { low: fvgLow, high: fvgHigh, index: i },
      impulse: { low: impulseLow, high: impulseHigh, range: impulseHigh - impulseLow },
      barsSinceDisplacement: bars.length - 1 - i,
      reason: `1H ${sweep.side} sweep/reclaim → displacement through structure (${displacement.volumeRatio.toFixed(2)}× relative volume) → fresh ${direction === 'BUY' ? 'bullish' : 'bearish'} imbalance`,
    };
  }
  return {
    confirmed: false,
    reason: `No recent 1H liquidity sweep/reclaim followed by a volume-backed structure break and fresh ${direction === 'BUY' ? 'bullish' : 'bearish'} imbalance.`,
  };
}

function _tdDetectRecentSweep(tf, candles) {
  const bars = Array.isArray(candles) ? candles : [];
  if (bars.length < 22) return null;
  const lookback = 20;
  const recentCount = tf === '4h' ? 1 : 3;
  const firstIndex = Math.max(lookback, bars.length - recentCount);

  for (let i = firstIndex; i < bars.length; i++) {
    const bar = bars[i];
    const prior = bars.slice(i - lookback, i);
    if (!bar || prior.length < lookback) continue;
    const priorHigh = Math.max(...prior.map(c => _tdNum(c.h)));
    const priorLow = Math.min(...prior.map(c => _tdNum(c.l)));
    const range = _tdNum(bar.h) - _tdNum(bar.l);
    if (!(range > 0)) continue;
    const body = Math.abs(_tdNum(bar.c) - _tdNum(bar.o));
    const upperWick = _tdNum(bar.h) - Math.max(_tdNum(bar.o), _tdNum(bar.c));
    const lowerWick = Math.min(_tdNum(bar.o), _tdNum(bar.c)) - _tdNum(bar.l);
    const wickThreshold = Math.max(body * 1.25, range * 0.3);
    const rejectedHigh = _tdNum(bar.h) > priorHigh && _tdNum(bar.c) < priorHigh &&
      upperWick >= wickThreshold;
    const reclaimedLow = _tdNum(bar.l) < priorLow && _tdNum(bar.c) > priorLow &&
      lowerWick >= wickThreshold;

    if (rejectedHigh || reclaimedLow) {
      const side = rejectedHigh ? 'high' : 'low';
      const level = rejectedHigh ? priorHigh : priorLow;
      return {
        tf,
        side,
        level,
        index: i,
        reason: `${tf} candle swept the prior ${lookback}-bar ${side} and closed back inside the range`,
      };
    }
  }
  return null;
}

function _tdDetectThreeTopRejection(candles, atr) {
  const bars = (Array.isArray(candles) ? candles : []).filter(c =>
    _tdNum(c?.h) > 0 && _tdNum(c?.l) > 0 && _tdNum(c?.c) > 0 && _tdNum(c?.h) >= _tdNum(c?.l)
  );
  const inactive = {
    active: false,
    available: bars.length >= 40 && atr > 0,
    structureBreak: false,
    reason: 'No active 4H three-top rejection pattern detected.',
  };
  if (bars.length < 40 || !(atr > 0)) return inactive;

  const firstIndex = Math.max(2, bars.length - 48);
  const rawPivots = [];
  for (let i = firstIndex; i < bars.length - 2; i++) {
    const high = _tdNum(bars[i].h);
    const neighbors = [bars[i - 2], bars[i - 1], bars[i + 1], bars[i + 2]].map(c => _tdNum(c.h));
    const isPivot = neighbors.every(value => high >= value) && neighbors.some(value => high > value);
    if (isPivot) rawPivots.push({ index: i, candle: bars[i], high });
  }

  // Collapse nearby fractals into one swing high so a choppy cluster is not
  // counted as several separate "heads".
  const pivots = [];
  for (const pivot of rawPivots) {
    const previous = pivots.at(-1);
    if (previous && pivot.index - previous.index < 4) {
      if (pivot.high > previous.high) pivots[pivots.length - 1] = pivot;
    } else {
      pivots.push(pivot);
    }
  }
  if (pivots.length < 3) return inactive;

  const heads = pivots.slice(-3);
  const [first, second, third] = heads;
  const barsSinceThird = bars.length - 1 - third.index;
  if (barsSinceThird > 18) return inactive;

  const troughBetween = (left, right) => {
    const section = bars.slice(left.index + 1, right.index);
    if (!section.length) return null;
    let minBar = section[0];
    let minIndex = left.index + 1;
    section.forEach((bar, offset) => {
      if (_tdNum(bar.l) < _tdNum(minBar.l)) {
        minBar = bar;
        minIndex = left.index + 1 + offset;
      }
    });
    return { index: minIndex, price: _tdNum(minBar.l) };
  };
  const firstTrough = troughBetween(first, second);
  const secondTrough = troughBetween(second, third);
  if (!firstTrough || !secondTrough) return inactive;

  const topReference = Math.max(first.high, second.high);
  const allHeads = heads.map(head => head.high);
  const headSpread = Math.max(...allHeads) - Math.min(...allHeads);
  const topClustered = headSpread <= Math.max(atr * 3.5, topReference * 0.035);
  const thirdNearTop = third.high >= topReference - Math.max(atr * 1.5, topReference * 0.01);
  const thirdSweptAndRejected = third.high > topReference && _tdNum(third.candle.c) < topReference;
  const thirdFailedAtTop = third.high <= topReference + atr * 0.35 &&
    thirdNearTop && _tdNum(third.candle.c) < topReference;
  const thirdRange = _tdNum(third.candle.h) - _tdNum(third.candle.l);
  const thirdBody = Math.abs(_tdNum(third.candle.c) - _tdNum(third.candle.o));
  const thirdUpperWick = _tdNum(third.candle.h) -
    Math.max(_tdNum(third.candle.o), _tdNum(third.candle.c));
  const thirdHasRejection = third.candle.c < third.candle.o ||
    (thirdRange > 0 && thirdUpperWick >= Math.max(thirdBody * 1.1, thirdRange * 0.25));
  const postTopBearishClose = bars.slice(third.index + 1, third.index + 4).some(c => {
    const range = _tdNum(c.h) - _tdNum(c.l);
    return range > 0 && c.c < c.o && (c.o - c.c) / range >= 0.45 && c.c < third.candle.c;
  });
  const risingOrFlatLows = secondTrough.price >= firstTrough.price - atr * 0.5;
  const swingsHaveDepth = topReference - firstTrough.price >= atr * 0.75 &&
    topReference - secondTrough.price >= atr * 0.75;
  const thirdRejected = (thirdSweptAndRejected || thirdFailedAtTop) &&
    (thirdHasRejection || postTopBearishClose);
  const lastClose = _tdNum(bars.at(-1).c);
  const bullishInvalidation = lastClose > topReference + atr * 0.75;

  if (!topClustered || !risingOrFlatLows || !swingsHaveDepth || !thirdRejected || bullishInvalidation) {
    return inactive;
  }

  const supportSlope = secondTrough.index > firstTrough.index
    ? (secondTrough.price - firstTrough.price) / (secondTrough.index - firstTrough.index)
    : 0;
  const projectedSupport = secondTrough.price +
    supportSlope * (bars.length - 1 - secondTrough.index);
  const brokeLastSwingLow = lastClose < secondTrough.price - atr * 0.15;
  const brokeRisingSupport = supportSlope > 0 &&
    lastClose < projectedSupport - atr * 0.15;
  const structureBreak = brokeLastSwingLow || brokeRisingSupport;
  const phase = structureBreak ? 'BEARISH STRUCTURE BREAK' : 'THIRD-TOP REJECTION — WAIT FOR BREAK';

  return {
    active: true,
    available: true,
    structureBreak,
    phase,
    heads: allHeads,
    troughs: [firstTrough.price, secondTrough.price],
    supportLevel: projectedSupport,
    barsSinceThird,
    reason: structureBreak
      ? `4H three-top rejection followed by a close below rising support near ${_tdFmt(projectedSupport)}; BUY is blocked.`
      : `4H third top rejected the prior high area near ${_tdFmt(topReference)}; block BUY and wait for a 4H structure break before considering SELL.`,
  };
}

function _tdCandlesAreFresh(tf, candles, now = Date.now()) {
  const intervalMs = _tdTimeframeMs(tf);
  const last = Array.isArray(candles) ? candles.at(-1) : null;
  let openedAt = Number(last?.t);
  if (!Number.isFinite(openedAt)) return false;
  if (openedAt < 1e12) openedAt *= 1000;
  const closedAt = openedAt + intervalMs;
  return closedAt <= now && now - closedAt <= intervalMs * 2;
}

function _tdAnalyzeTimeframe(tf, candles, currentPrice) {
  const bars = Array.isArray(candles) ? candles.filter(c =>
    _tdNum(c?.o) > 0 && _tdNum(c?.h) > 0 && _tdNum(c?.l) > 0 && _tdNum(c?.c) > 0
  ) : [];
  if (bars.length < 20) {
    return {
      tf, direction: 'NEUTRAL', pattern: 'INSUFFICIENT_DATA', score: 0,
      confidence: 0, candles: bars.length, reason: 'Not enough completed candles',
    };
  }

  const closes = bars.map(c => c.c);
  const last = bars[bars.length - 1];
  const price = _tdNum(currentPrice, last.c);
  const atr = _tdAtr(bars);
  const ema20 = _tdEma(closes, 20);
  const ema50 = _tdEma(closes, 50);
  const ema200 = bars.length >= 80 ? _tdEma(closes, 200) : 0;
  const previousEma20 = _tdEma(closes.slice(0, -5), 20);
  const emaSlope = ema20 - previousEma20;
  const lookback = bars.slice(-Math.min(20, bars.length));
  const prior = bars.slice(-Math.min(21, bars.length), -1);
  const rangeHigh = Math.max(...prior.map(c => c.h));
  const rangeLow = Math.min(...prior.map(c => c.l));
  const recentHigh = Math.max(...lookback.slice(0, -3).map(c => c.h));
  const recentLow = Math.min(...lookback.slice(0, -3).map(c => c.l));
  const midpoint = (rangeHigh + rangeLow) / 2;
  const rsi = _tdRsi(bars);
  const avgVolume = bars.slice(-21, -1).reduce((sum, c) => sum + _tdCandleVolume(c), 0) /
    Math.max(1, Math.min(20, bars.length - 1));
  const volumeRatio = avgVolume > 0 ? _tdCandleVolume(last) / avgVolume : 1;
  const body = Math.abs(last.c - last.o);
  const bodyRatio = (last.h - last.l) > 0 ? body / (last.h - last.l) : 0;
  const higherHigh = bars.length >= 12 &&
    Math.max(...bars.slice(-6).map(c => c.h)) > Math.max(...bars.slice(-12, -6).map(c => c.h));
  const higherLow = bars.length >= 12 &&
    Math.min(...bars.slice(-6).map(c => c.l)) > Math.min(...bars.slice(-12, -6).map(c => c.l));
  const lowerHigh = bars.length >= 12 &&
    Math.max(...bars.slice(-6).map(c => c.h)) < Math.max(...bars.slice(-12, -6).map(c => c.h));
  const lowerLow = bars.length >= 12 &&
    Math.min(...bars.slice(-6).map(c => c.l)) < Math.min(...bars.slice(-12, -6).map(c => c.l));
  const bullTrend = ema20 > ema50 && emaSlope > 0 && (higherHigh || higherLow);
  const bearTrend = ema20 < ema50 && emaSlope < 0 && (lowerHigh || lowerLow);
  const breakoutUp = last.c > rangeHigh && bodyRatio >= 0.45;
  const breakoutDown = last.c < rangeLow && bodyRatio >= 0.45;
  const pullbackBuy = bullTrend && price <= ema20 + atr * 0.35 && price > recentLow;
  const pullbackSell = bearTrend && price >= ema20 - atr * 0.35 && price < recentHigh;
  const bullishCandle = last.c > last.o && bodyRatio >= 0.45;
  const bearishCandle = last.c < last.o && bodyRatio >= 0.45;
  const rangePct = price > 0 ? (rangeHigh - rangeLow) / price : 0;
  const compressed = atr > 0 && rangePct < 0.035;

  let direction = 'NEUTRAL';
  if (bullTrend && (bullishCandle || breakoutUp || pullbackBuy)) direction = 'BUY';
  else if (bearTrend && (bearishCandle || breakoutDown || pullbackSell)) direction = 'SELL';
  else if (ema20 > ema50 && rsi >= 52 && price >= midpoint) direction = 'BUY';
  else if (ema20 < ema50 && rsi <= 48 && price <= midpoint) direction = 'SELL';

  let pattern = 'RANGE / NO EDGE';
  if (breakoutUp && bullTrend) pattern = 'BULLISH BREAKOUT CONTINUATION';
  else if (breakoutDown && bearTrend) pattern = 'BEARISH BREAKOUT CONTINUATION';
  else if (pullbackBuy) pattern = 'BULLISH PULLBACK CONTINUATION';
  else if (pullbackSell) pattern = 'BEARISH PULLBACK CONTINUATION';
  else if (bullTrend) pattern = 'BULLISH TREND — WAIT FOR PULLBACK';
  else if (bearTrend) pattern = 'BEARISH TREND — WAIT FOR PULLBACK';
  else if (compressed) pattern = 'COMPRESSION — WAIT FOR BREAKOUT';

  const trendScore = direction === 'BUY'
    ? (bullTrend ? 35 : 18) : direction === 'SELL'
      ? (bearTrend ? 35 : 18) : 0;
  const momentumScore = direction === 'BUY'
    ? (rsi >= 52 && rsi <= 72 ? 25 : rsi > 72 ? 10 : 8)
    : direction === 'SELL'
      ? (rsi <= 48 && rsi >= 28 ? 25 : rsi < 28 ? 10 : 8) : 0;
  const structureScore = direction === 'BUY'
    ? (higherHigh && higherLow ? 25 : higherHigh || higherLow ? 15 : 5)
    : direction === 'SELL'
      ? (lowerHigh && lowerLow ? 25 : lowerHigh || lowerLow ? 15 : 5) : 0;
  const participationScore = volumeRatio >= 1.15 ? 15 : volumeRatio >= 0.85 ? 9 : 4;
  const rawScore = direction === 'NEUTRAL'
    ? 0 : Math.min(100, trendScore + momentumScore + structureScore + participationScore);

  return {
    tf, direction, pattern, score: Math.round(rawScore),
    confidence: Math.round(rawScore),
    candles: bars.length, price, atr, ema20, ema50, ema200,
    rsi: Number(rsi.toFixed(1)), volumeRatio: Number(volumeRatio.toFixed(2)),
    rangeHigh, rangeLow, midpoint, recentHigh, recentLow,
    higherHigh, higherLow, lowerHigh, lowerLow, breakoutUp, breakoutDown,
    pullbackBuy, pullbackSell, compressed,
    location: price < midpoint ? 'DISCOUNT' : price > midpoint ? 'PREMIUM' : 'EQUILIBRIUM',
    reason: `${pattern} | RSI ${rsi.toFixed(1)} | volume ${volumeRatio.toFixed(2)}× | ` +
      `EMA20 ${price >= ema20 ? 'above' : 'below'} price`,
  };
}

function _tdBuildPlan(direction, timeframes, currentPrice, fourHourStructure, oneHourExecution) {
  const oneHour = timeframes?.['1h'];
  const fourHour = timeframes?.['4h'];
  const price = _tdNum(currentPrice);
  const emptyPlan = reason => ({
    order: 'WAIT', entry: null, entryZone: null, stop: null, tp1: null, tp2: null, tp3: null,
    invalidation: null, reason,
  });
  if (!['BUY', 'SELL'].includes(direction) || !oneHour?.atr || !fourHour?.atr || price <= 0) {
    return emptyPlan('Both 1H and 4H candle context is required before calculating a limit entry.');
  }
  if (!fourHourStructure?.aligned ||
      fourHourStructure.bias !== direction ||
      fourHourStructure.orderBlock?.direction !== direction) {
    return emptyPlan('The 4H has not confirmed same-direction structure, displacement and a fresh order-block zone.');
  }
  if (!oneHourExecution?.confirmed || oneHourExecution.direction !== direction) {
    return emptyPlan(oneHourExecution?.reason ||
      'The 1H sweep, structure break and imbalance sequence is not confirmed.');
  }

  const impulse = oneHourExecution.impulse;
  const oteLow = direction === 'BUY'
    ? impulse.high - impulse.range * 0.618
    : impulse.low + impulse.range * 0.5;
  const oteHigh = direction === 'BUY'
    ? impulse.high - impulse.range * 0.5
    : impulse.low + impulse.range * 0.618;
  const fvg = oneHourExecution.fvg;
  const orderBlock = fourHourStructure.orderBlock;
  if (!(fourHourStructure.rangeHigh > fourHourStructure.rangeLow &&
      fourHourStructure.rangeMid > fourHourStructure.rangeLow &&
      fourHourStructure.rangeMid < fourHourStructure.rangeHigh)) {
    return emptyPlan('The 4H dealing range is unavailable; premium/discount location cannot be confirmed.');
  }
  let zoneLow = Math.max(oteLow, fvg.low, orderBlock.low, fourHourStructure.rangeLow);
  let zoneHigh = Math.min(oteHigh, fvg.high, orderBlock.high, fourHourStructure.rangeHigh);
  if (direction === 'BUY') zoneHigh = Math.min(zoneHigh, fourHourStructure.rangeMid);
  else zoneLow = Math.max(zoneLow, fourHourStructure.rangeMid);
  const minimumZoneWidth = Math.max(oneHour.atr * 0.05, price * 0.00001);
  if (zoneHigh - zoneLow < minimumZoneWidth) {
    return emptyPlan('The 1H pullback, 1H imbalance and 4H order block do not overlap; wait for fresh confluence.');
  }
  if (direction === 'BUY' && zoneLow <= _tdNum(fourHour.recentLow)) {
    return emptyPlan('The BUY pullback zone falls through recent 4H support; wait for the 4H structure to reset.');
  }
  if (direction === 'SELL' && zoneHigh >= _tdNum(fourHour.recentHigh)) {
    return emptyPlan('The SELL pullback zone rises through recent 4H resistance; wait for the 4H structure to reset.');
  }

  const tickBuffer = Math.max(price * 0.000001, Number.EPSILON);
  let entry = (zoneLow + zoneHigh) / 2;
  if (direction === 'BUY') {
    if (price <= zoneLow) return emptyPlan('The BUY pullback zone has already been traded through; wait for a fresh 1H impulse.');
    if (entry >= price) entry = Math.min(zoneHigh, price - tickBuffer);
    if (entry < zoneLow || entry >= price) return emptyPlan('No valid BUY LIMIT remains below the live price inside the confluence zone.');
  } else {
    if (price >= zoneHigh) return emptyPlan('The SELL pullback zone has already been traded through; wait for a fresh 1H impulse.');
    if (entry <= price) entry = Math.max(zoneLow, price + tickBuffer);
    if (entry > zoneHigh || entry <= price) return emptyPlan('No valid SELL LIMIT remains above the live price inside the confluence zone.');
  }

  const stop = direction === 'BUY'
    ? Math.min(entry - oneHour.atr * 1.1, impulse.low - oneHour.atr * 0.12)
    : Math.max(entry + oneHour.atr * 1.1, impulse.high + oneHour.atr * 0.12);
  const risk = Math.abs(entry - stop);
  if (!(risk > 0) || (direction === 'BUY' ? stop >= entry : stop <= entry)) {
    return emptyPlan('The structural invalidation level does not produce a valid limit-order risk.');
  }
  const tp1 = direction === 'BUY' ? entry + risk * 1.5 : entry - risk * 1.5;
  const tp2 = direction === 'BUY' ? entry + risk * 2.5 : entry - risk * 2.5;
  const tp3 = direction === 'BUY' ? entry + risk * 3.5 : entry - risk * 3.5;

  return {
    order: direction === 'BUY' ? 'BUY LIMIT' : 'SELL LIMIT',
    entry,
    stop,
    tp1,
    tp2,
    tp3,
    risk,
    invalidation: direction === 'BUY'
      ? `1H close below ${_tdFmt(stop)}`
      : `1H close above ${_tdFmt(stop)}`,
    reason: `4H ${fourHourStructure.bias} structure (${fourHourStructure.swingState}) and a fresh displacement order block align with the 1H sweep/reclaim, volume-backed structure break and fair-value gap; the 1H 50–61.8% pullback is in 4H ${direction === 'BUY' ? 'discount' : 'premium'}.`,
    entryZone: `${_tdFmt(zoneLow)} – ${_tdFmt(zoneHigh)}`,
    zoneLow,
    zoneHigh,
    impulse,
    fvg,
    orderBlock,
  };
}


// 15M-only pullback map: derives a retracement wait-zone from the latest
// directional impulse leg. It is advisory and does not alter the 4H/1H gate.
function _tdBuild15mPullback(candles, direction, currentPrice, isFresh = true) {
  const bars = Array.isArray(candles) ? candles.filter(c =>
    _tdNum(c?.o) > 0 && _tdNum(c?.h) > 0 && _tdNum(c?.l) > 0 && _tdNum(c?.c) > 0
  ) : [];
  const price = _tdNum(currentPrice, 0);
  if (!['BUY', 'SELL'].includes(direction)) {
    return { available: false, status: 'NO DIRECTION', reason: 'A directional 4H/1H bias is required to identify a 15M breakout retest.' };
  }
  if (bars.length < 24 || !(price > 0)) {
    return { available: false, status: 'INSUFFICIENT DATA', reason: 'At least 24 valid 15M candles and a live price are required.' };
  }
  if (!isFresh) {
    return { available: false, status: 'STALE DATA', reason: '15M candles are stale; refresh before using a breakout retest level.' };
  }

  // Use completed 15M candles only. Find confirmed local swing levels (2 bars
  // either side), then require a later candle to CLOSE through that level with
  // a directional displacement body. The broken swing is the retest reference.
  const lookback = bars.slice(-48);
  const atr = _tdAtr(lookback, 14);
  if (!(atr > 0)) return { available: false, status: 'NO ATR', reason: '15M volatility could not be calculated.' };

  const leftRight = 2;
  const latestBreakIndex = lookback.length - 1;
  const earliestBreakIndex = Math.max(5, latestBreakIndex - 10);
  let candidate = null;

  for (let pivot = 2; pivot < lookback.length - 3; pivot++) {
    const p = lookback[pivot];
    let isSwing = true;
    if (direction === 'SELL') {
      const level = _tdNum(p.l);
      for (let j = pivot - leftRight; j <= pivot + leftRight; j++) {
        if (j !== pivot && _tdNum(lookback[j].l) <= level) { isSwing = false; break; }
      }
      if (!isSwing) continue;
      for (let b = Math.max(pivot + leftRight + 1, earliestBreakIndex); b <= latestBreakIndex; b++) {
        const candle = lookback[b];
        const o = _tdNum(candle.o), c = _tdNum(candle.c);
        const body = o - c;
        const range = Math.max(_tdNum(candle.h) - _tdNum(candle.l), 0);
        if (c < level && body > 0 && body >= Math.max(atr * 0.30, range * 0.45)) {
          if (!candidate || b > candidate.breakIndex) {
            candidate = { level, pivotIndex: pivot, breakIndex: b, breakoutOpen: o,
              breakoutClose: c, breakoutHigh: _tdNum(candle.h), breakoutLow: _tdNum(candle.l) };
          }
        }
      }
    } else {
      const level = _tdNum(p.h);
      for (let j = pivot - leftRight; j <= pivot + leftRight; j++) {
        if (j !== pivot && _tdNum(lookback[j].h) >= level) { isSwing = false; break; }
      }
      if (!isSwing) continue;
      for (let b = Math.max(pivot + leftRight + 1, earliestBreakIndex); b <= latestBreakIndex; b++) {
        const candle = lookback[b];
        const o = _tdNum(candle.o), c = _tdNum(candle.c);
        const body = c - o;
        const range = Math.max(_tdNum(candle.h) - _tdNum(candle.l), 0);
        if (c > level && body > 0 && body >= Math.max(atr * 0.30, range * 0.45)) {
          if (!candidate || b > candidate.breakIndex) {
            candidate = { level, pivotIndex: pivot, breakIndex: b, breakoutOpen: o,
              breakoutClose: c, breakoutHigh: _tdNum(candle.h), breakoutLow: _tdNum(candle.l) };
          }
        }
      }
    }
  }

  if (!candidate) {
    return {
      available: false, status: 'NO CONFIRMED 15M BREAKOUT',
      reason: 'No recent 15M candle has closed through a confirmed swing level with sufficient directional displacement. No pullback price is being guessed.'
    };
  }

  const level = candidate.level;
  // Retest tolerance is deliberately narrow and volatility-scaled. The broken
  // swing level remains the exact reference; the band is only an execution
  // tolerance, not a replacement Fibonacci target.
  const tolerance = Math.max(level * 0.0005, Math.min(atr * 0.12, level * 0.002));
  const zoneLow = level - tolerance;
  const zoneHigh = level + tolerance;
  let status, reason;
  if (direction === 'SELL') {
    if (price > zoneHigh) {
      status = 'BREAKOUT RETEST INVALIDATED';
      reason = 'Price has reclaimed above the broken 15M support beyond the retest tolerance; wait for a fresh bearish breakout.';
    } else if (price >= zoneLow) {
      status = 'PRICE RETESTING BROKEN SUPPORT';
      reason = 'Price is retesting the broken 15M support from below. Wait for a bearish 15M rejection/close before considering execution.';
    } else {
      status = 'WAIT FOR SUPPORT RETEST';
      reason = 'Wait for price to pull back upward to the exact broken 15M support level, then require bearish rejection; do not chase.';
    }
  } else {
    if (price < zoneLow) {
      status = 'BREAKOUT RETEST INVALIDATED';
      reason = 'Price has fallen below the broken 15M resistance beyond the retest tolerance; wait for a fresh bullish breakout.';
    } else if (price <= zoneHigh) {
      status = 'PRICE RETESTING BROKEN RESISTANCE';
      reason = 'Price is retesting the broken 15M resistance from above. Wait for a bullish 15M rejection/close before considering execution.';
    } else {
      status = 'WAIT FOR RESISTANCE RETEST';
      reason = 'Wait for price to pull back downward to the exact broken 15M resistance level, then require bullish rejection; do not chase.';
    }
  }

  return {
    available: true, timeframe: '15M', method: 'CONFIRMED SWING BREAKOUT RETEST',
    direction, status, reason, breakoutLevel: level, zoneLow, zoneHigh,
    ideal: level, tolerance, atr15m: atr,
    breakoutOpen: candidate.breakoutOpen, breakoutClose: candidate.breakoutClose,
    breakoutHigh: candidate.breakoutHigh, breakoutLow: candidate.breakoutLow,
    breakoutCandleIndex: candidate.breakIndex, swingPivotIndex: candidate.pivotIndex
  };
}

async function buildTotalMarketDecision(symbol, generator) {
  const frames = ['4h', '1h', '15min', '5min'];
  const coreFrames = ['4h', '1h'];
  const executionFrames = ['15min', '5min'];
  const [priceResult, ...candleResults] = await Promise.all([
    fetchLivePrice(symbol).catch(() => null),
    ...frames.map(tf => fetchCandlesCached(symbol, tf, 120)
      .catch(() => [])),
  ]);
  const price = _tdNum(priceResult, 0);
  const now = Date.now();
  const candleSets = {};
  const timeframes = {};
  frames.forEach((tf, index) => {
    candleSets[tf] = _tdClosedCandles(tf, candleResults[index], now);
    timeframes[tf] = _tdAnalyzeTimeframe(tf, candleSets[tf], price);
  });

  const fourHour = timeframes['4h'];
  const oneHour = timeframes['1h'];
  const directionsAgree = ['BUY', 'SELL'].includes(fourHour?.direction) &&
    fourHour.direction === oneHour?.direction;
  const direction = directionsAgree ? fourHour.direction : 'NEUTRAL';
  const fourHourStructure = _tdBuildFourHourStructure(candleSets['4h'], fourHour?.atr);
  const oneHourExecution = ['BUY', 'SELL'].includes(direction)
    ? _tdBuildOneHourExecution(candleSets['1h'], direction, oneHour?.atr)
    : { confirmed: false, reason: 'The 1H execution trigger is not checked until both timeframes agree.' };
  const alignedStructural = directionsAgree ? coreFrames.slice() : [];
  const conflictingStructural = ['BUY', 'SELL'].includes(fourHour?.direction) &&
    ['BUY', 'SELL'].includes(oneHour?.direction) &&
    fourHour.direction !== oneHour.direction ? coreFrames.slice() : [];
  const alignment = directionsAgree ? 100 : 0;
  const patternAligned = directionsAgree && coreFrames.every(tf => {
    const pattern = String(timeframes[tf]?.pattern || '');
    return direction === 'BUY' ? pattern.startsWith('BULLISH') : pattern.startsWith('BEARISH');
  });
  const patternScore = patternAligned ? 100 : 0;
  const dataQuality = Math.round(frames.reduce((sum, tf) =>
    sum + (timeframes[tf].candles >= 50 ? 1 : timeframes[tf].candles >= 20 ? 0.6 : 0), 0) / frames.length * 100);
  const timeframeThreshold = 75;
  const lowerTimeframeAvailable = executionFrames.every(tf => candleSets[tf].length >= 20);
  const lowerTimeframeFresh = executionFrames.every(tf => _tdCandlesAreFresh(tf, candleSets[tf], now));
  const fifteenMinutePullback = _tdBuild15mPullback(
    candleSets['15min'], direction, price, _tdCandlesAreFresh('15min', candleSets['15min'], now)
  );
  const modelScore = directionsAgree
    ? Math.min(_tdNum(fourHour.score), _tdNum(oneHour.score)) : 0;
  const executionAlignment = ['BUY', 'SELL'].includes(direction)
    ? Math.round(executionFrames.filter(tf => timeframes[tf]?.direction === direction).length / executionFrames.length * 100) : 0;
  const lowerTimeframeScore = lowerTimeframeAvailable
    ? Math.round(executionFrames.reduce((sum, tf) => sum + _tdNum(timeframes[tf]?.score), 0) / executionFrames.length) : null;
  const compositeScore = lowerTimeframeAvailable
    ? Math.round(modelScore * 0.70 + lowerTimeframeScore * 0.30) : modelScore;
  const intradayConfluence = modelScore;
  const averagePatternScore = Math.round(
    (_tdNum(fourHour.score) + _tdNum(oneHour.score)) / coreFrames.length
  );
  const freshData = coreFrames.every(tf => _tdCandlesAreFresh(tf, candleSets[tf], now));
  const sufficientData = coreFrames.every(tf => candleSets[tf].length >= 50);
  const strongTimeframes = directionsAgree && sufficientData &&
    coreFrames.every(tf => timeframes[tf].score >= timeframeThreshold) && patternAligned;
  const sweepChecksComplete = coreFrames.every(tf => candleSets[tf].length >= 22);
  const sweepChecks = coreFrames.map(tf => _tdDetectRecentSweep(tf, candleSets[tf])).filter(Boolean);
  const confirmedExecutionSweep = oneHourExecution.confirmed
    ? oneHourExecution.sweep : null;
  const unresolvedSweepChecks = sweepChecks.filter(check => {
    const expectedSide = direction === 'BUY' ? 'low' : direction === 'SELL' ? 'high' : null;
    return !(check.tf === '1h' && check.index === confirmedExecutionSweep?.index &&
      check.side === expectedSide);
  });
  const fourHourPattern = _tdDetectThreeTopRejection(candleSets['4h'], fourHour?.atr);
  const threeTopBuyBlocked = fourHourPattern.active && direction === 'BUY';
  const waitForBreakBeforeSell = fourHourPattern.active &&
    direction === 'SELL' && !fourHourPattern.structureBreak;
  const footprintChecks = [
    {
      label: '4H directional structure and fresh order block',
      passed: fourHourStructure.aligned && fourHourStructure.bias === direction,
    },
    { label: '1H liquidity sweep and reclaim', passed: !!oneHourExecution.sweep },
    { label: '1H displacement through structure', passed: !!oneHourExecution.displacement },
    { label: '1H fair-value gap', passed: !!oneHourExecution.fvg },
    {
      label: '1H relative-volume confirmation',
      passed: _tdNum(oneHourExecution.displacement?.volumeRatio) >= 1.15,
    },
  ];
  const footprintScore = Math.round(
    footprintChecks.filter(check => check.passed).length / footprintChecks.length * 100
  );
  const footprintReady = footprintChecks.every(check => check.passed);

  let plan = {
    order: 'WAIT', entry: null, entryZone: null, stop: null, tp1: null, tp2: null, tp3: null,
    invalidation: null, reason: 'The 4H and 1H setup has not passed every entry condition.',
  };
  if (price <= 0) {
    plan.reason = 'Live price is unavailable; no limit levels can be calculated safely.';
  } else if (!sufficientData || !freshData) {
    plan.reason = 'The closed 1H/4H candles are insufficient or stale; wait for current data.';
  } else if (!directionsAgree) {
    plan.reason = conflictingStructural.length
      ? 'The 1H and 4H point in different directions; neither timeframe overrides the other.'
      : 'The 1H and 4H do not both have a directional setup.';
  } else if (threeTopBuyBlocked) {
    plan.reason = fourHourPattern.reason;
  } else if (waitForBreakBeforeSell) {
    plan.reason = fourHourPattern.reason;
  } else if (!strongTimeframes) {
    plan.reason = `Both 1H and 4H must show aligned continuation structure with a score of at least ${timeframeThreshold}/100.`;
  } else if (!sweepChecksComplete) {
    plan.reason = 'There are not enough recent closed candles to check for a sweep/rejection.';
  } else if (!fourHourStructure.aligned || fourHourStructure.bias !== direction) {
    plan.reason = 'The 4H has not confirmed same-direction swing structure and a fresh displacement order block.';
  } else if (!oneHourExecution.confirmed) {
    plan.reason = oneHourExecution.reason;
  } else if (unresolvedSweepChecks.length) {
    plan.reason = `Unresolved sweep/rejection evidence: ${unresolvedSweepChecks.map(check => check.reason).join('; ')}.`;
  } else if (!footprintReady) {
    plan.reason = `Only ${footprintScore}% of the required two-timeframe footprint checks passed.`;
  } else {
    plan = _tdBuildPlan(direction, timeframes, price, fourHourStructure, oneHourExecution);
  }

  const strictConfirmed = plan.order === 'BUY LIMIT' || plan.order === 'SELL LIMIT';
  let status = 'WAIT — NO VALID LIMIT ENTRY';
  if (strictConfirmed) status = 'STRONG 4H + 1H STRUCTURE / 15M + 5M EXECUTION CONTEXT — LIMIT SETUP';
  else if (!sufficientData || !freshData) status = 'WAIT — INSUFFICIENT OR STALE DATA';
  else if (threeTopBuyBlocked) status = 'WAIT — 4H THREE-TOP REJECTION (BUY BLOCKED)';
  else if (waitForBreakBeforeSell) status = 'WAIT — 4H STRUCTURE BREAK NOT CONFIRMED';
  else if (!directionsAgree) status = 'WAIT — 1H/4H NOT ALIGNED';
  else if (!strongTimeframes) status = 'WAIT — 1H/4H CONVICTION BELOW THRESHOLD';
  else if (!sweepChecksComplete) status = 'WAIT — INSUFFICIENT SWEEP HISTORY';
  else if (unresolvedSweepChecks.length) status = 'WAIT — UNRESOLVED SWEEP/REJECTION';
  else if (!fourHourStructure.aligned || fourHourStructure.bias !== direction) {
    status = 'WAIT — 4H STRUCTURE / ORDER BLOCK NOT CONFIRMED';
  } else if (!oneHourExecution.confirmed) {
    status = 'WAIT — 1H SWEEP / DISPLACEMENT / FVG NOT CONFIRMED';
  } else if (!footprintReady) status = 'WAIT — TWO-TIMEFRAME FOOTPRINT INCOMPLETE';

  return {
    symbol, price, direction, status, modelScore, compositeScore, lowerTimeframeScore,
    executionAlignment, lowerTimeframeAvailable, lowerTimeframeFresh,
    confidenceType: 'The lower of the 1H/4H setup scores; not a win probability',
    strictConfirmed, alignment, patternScore, dataQuality, timeframeThreshold,
    intradayConfluence, averagePatternScore,
    conflictingStructural, alignedStructural, timeframes, plan,
    sweepChecks, unresolvedSweepChecks, sweepChecksComplete, freshData, sufficientData,
    fourHourStructure, oneHourExecution, fifteenMinutePullback, footprintChecks, footprintScore, footprintReady,
    fourHourPattern, threeTopBuyBlocked, waitForBreakBeforeSell,
    generatedAt: new Date().toISOString(),
  };
}

function formatTotalMarketDecision(decision) {
  if (!decision) return '❌ No market decision available.';
  const fmt = _tdFmt;
  const p = decision.plan || {};
  const dIcon = decision.direction === 'BUY' ? '🟢' : decision.direction === 'SELL' ? '🔴' : '⚪';
  const tfOrder = ['4h', '1h', '15min', '5min'];
  const tfLabels = { '4h': '4H', '1h': '1H', '15min': '15M', '5min': '5M' };
  const tfLines = tfOrder.map(tf => {
    const x = decision.timeframes?.[tf];
    if (!x) return null;
    const icon = x.direction === 'BUY' ? '🟢' : x.direction === 'SELL' ? '🔴' : '⚪';
    return `${icon} <b>${tfLabels[tf]}</b> ${x.direction} | ${x.pattern} | ${x.confidence}% | RSI ${x.rsi ?? '—'} | ${x.location || '—'}`;
  }).filter(Boolean).join('\n');
  const conflictText = decision.conflictingStructural?.length
    ? decision.conflictingStructural.map(tf => `${tf.toUpperCase()} ${decision.timeframes?.[tf]?.direction || '—'}`).join(', ')
    : 'None';
  const activeSweeps = decision.unresolvedSweepChecks || decision.sweepChecks || [];
  const sweepText = activeSweeps.length
    ? activeSweeps.map(check => check.reason).join('; ')
    : decision.oneHourExecution?.confirmed
      ? `1H ${decision.oneHourExecution.sweep.side} sweep was reclaimed and confirmed by displacement; no unresolved sweep veto`
    : decision.sweepChecksComplete
      ? 'No recent sweep/rejection detected in the checked closed candles'
      : 'Not checked — recent 1H/4H candle data is insufficient';
  const fourHourStructure = decision.fourHourStructure || {};
  const fourHourOb = fourHourStructure.orderBlock;
  const fourHourBos = fourHourStructure.displacement;
  const fourHourStructureText = !fourHourStructure.aligned
    ? `${fourHourStructure.bias || 'NEUTRAL'} — no fresh aligned displacement/order block`
    : `${fourHourStructure.bias} (${fourHourStructure.swingState}); dealing range ` +
      `${fmt(fourHourStructure.rangeLow)}–${fmt(fourHourStructure.rangeHigh)}; ` +
      `midpoint ${fmt(fourHourStructure.rangeMid)}; BOS beyond ${fmt(fourHourBos?.structureLevel)}`;
  const fourHourObText = fourHourOb
    ? `${fourHourOb.direction} ${fmt(fourHourOb.low)}–${fmt(fourHourOb.high)}; ` +
      `fresh displacement ${fourHourOb.displacementVolumeRatio.toFixed(2)}× relative volume`
    : 'No fresh, unmitigated same-direction 4H order block';
  const oneHourExecution = decision.oneHourExecution || {};
  const oneHourExecutionText = oneHourExecution.confirmed
    ? `${oneHourExecution.reason}; FVG ${fmt(oneHourExecution.fvg.low)}–${fmt(oneHourExecution.fvg.high)}`
    : oneHourExecution.reason || 'Not confirmed';
  const pb15 = decision.fifteenMinutePullback || {};
  const pullback15Text = pb15.available
    ? `<b>${pb15.status}</b> | Exact broken swing level: <code>${fmt(pb15.breakoutLevel)}</code> | Retest zone: <code>${fmt(pb15.zoneLow)}–${fmt(pb15.zoneHigh)}</code> | Breakout close: ${fmt(pb15.breakoutClose)} | ${pb15.reason}`
    : `<b>${pb15.status || 'UNAVAILABLE'}</b> | ${pb15.reason || 'No confirmed 15M breakout retest level available.'}`;
  const footprintText = (decision.footprintChecks || [])
    .map(check => `${check.passed ? '✓' : '✗'} ${check.label}`).join(' | ') || 'Not checked';
  const threeTop = decision.fourHourPattern || {};
  const threeTopText = !threeTop.available
    ? 'Not checked — insufficient closed 4H candles'
    : !threeTop.active
      ? 'No active 4H three-top rejection detected'
      : `${threeTop.phase}; heads ${threeTop.heads.map(fmt).join(' / ')}; ` +
        `reaction lows ${threeTop.troughs.map(fmt).join(' / ')}; ` +
        `support line ${fmt(threeTop.supportLevel)}`;
  const planLines = p.order === 'WAIT'
    ? [
        `🛑 <b>INSTRUCTION: WAIT — DO NOT ENTER</b>`,
        p.reason || 'No executable setup.',
        `Required: 4H structure/order block and 1H sweep→reclaim→displacement→FVG must align; 15M/5M provide additional execution-timing context and do not override the 4H/1H core gate. The 1H OTE, FVG and 4H order block must overlap in 4H discount (BUY) or premium (SELL).`,
      ]
    : [
        `✅ <b>INSTRUCTION: ${p.order}</b>`,
        `Entry zone: <code>${p.entryZone || fmt(p.entry)}</code>`,
        `Limit entry: <code>${fmt(p.entry)}</code>`,
        `Stop loss: <code>${fmt(p.stop)}</code>`,
        `TP1: <code>${fmt(p.tp1)}</code>  |  TP2: <code>${fmt(p.tp2)}</code>  |  TP3: <code>${fmt(p.tp3)}</code>`,
        `Invalidation: <b>${p.invalidation}</b>`,
        `Plan logic: ${p.reason}`,
        `<i>A limit may not fill. Levels do not guarantee a favorable move; size risk before placing an order.</i>`,
      ];
  const lines = [
    `━━━ 🧭 4H + 1H + 15M + 5M DECISION ━━━`,
    `<b>${decision.symbol}</b> | Price: <code>${fmt(decision.price)}</code>`,
    `${dIcon} Bias: <b>${decision.direction}</b> | Status: <b>${decision.status}</b>`,
    `HTF core score (4H/1H): <b>${decision.modelScore}/100</b> | Four-TF composite: <b>${decision.compositeScore ?? decision.modelScore}/100</b>`,
    `15M/5M directional agreement: <b>${decision.executionAlignment ?? 0}%</b> | Lower-TF data: <b>${decision.lowerTimeframeAvailable ? (decision.lowerTimeframeFresh ? 'FRESH' : 'STALE') : 'INSUFFICIENT'}</b>`,
    ``,
    `<b>FOUR-TIMEFRAME ANALYSIS</b>`,
    tfLines || 'No timeframe data returned.',
    ``,
    `<b>ENTRY FILTERS</b>`,
    `4H/1H same direction: <b>${decision.alignment === 100 ? 'YES' : 'NO'}</b> | 15M/5M agree with core bias: <b>${decision.executionAlignment === 100 ? 'YES' : decision.executionAlignment === 50 ? 'PARTIAL' : 'NO'}</b> | 4H/1H patterns: <b>${decision.patternScore === 100 ? 'YES' : 'NO'}</b>`,
    `Minimum score per timeframe: <b>${decision.timeframeThreshold}/100</b> | Closed-candle data quality: <b>${decision.dataQuality}%</b>`,
    `Conflicting timeframes: <b>${conflictText}</b>`,
    `4H structure: <b>${fourHourStructureText}</b>`,
    `4H order block: <b>${fourHourObText}</b>`,
    `1H execution: <b>${oneHourExecutionText}</b>`,
    `15M pullback to wait for: ${pullback15Text}`,
    `Two-timeframe footprint checks: <b>${decision.footprintScore ?? 0}/100</b> <i>(rule checklist, not win probability)</i> — ${footprintText}`,
    `Recent sweep/rejection check: <b>${sweepText}</b>`,
    `4H three-top guard: <b>${threeTopText}</b>`,
    ``,
    ...planLines,
    ``,
    `📌 <b>Reading:</b> The 15M breakout-retest level is a separate timing reference only; it does not replace the existing 1H/4H limit-entry calculation or confirm an entry by itself. ${decision.strictConfirmed
      ? 'The primary limit remains the overlap of a 1H retracement/imbalance with a 4H order block and value zone; it is conditional, not a forecast or guaranteed fill.'
      : 'No qualifying limit setup now. Do not substitute another timeframe or force a directional entry.'}`,
    `<i>4H swings, 1H sweeps, displacement, gaps and relative volume are OHLCV proxies—not proof of institutional orders, intent or manipulation. The three-top guard blocks BUY at a rejected third 4H top; SELL still needs a 4H break and aligned 1H/4H evidence.</i>`,
  ];
  return lines.join('\n').slice(0, 4090);
}

console.log('✅ INTRADAY DECISION ENGINE loaded — /decision SYMBOL');

/* ============================================================================
   AUTOMATIC BITGET FOUR-TIMEFRAME DECISION SCANNER
   ----------------------------------------------------------------------------
   Rotates through the liquid Bitget USDT perpetual universe in bounded batches.
   It uses the same buildTotalMarketDecision() rules as /decision SYMBOL and
   alerts only when strictConfirmed is true and the complete limit plan is
   valid. This sends conditional trade plans; it never places exchange orders.
   ========================================================================== */
const DECISION_AUTO_SCAN_DEFAULT =
  !['0', 'false', 'off', 'no'].includes(String(process.env.DECISION_AUTO_SCAN ?? 'true').trim().toLowerCase());
const DECISION_AUTO_INTERVAL_MS = Math.max(
  60_000, Number.parseInt(process.env.DECISION_AUTO_INTERVAL_MS || '300000', 10) || 300_000
);
const DECISION_AUTO_BATCH_SIZE = Math.max(
  1, Math.min(500, Number.parseInt(process.env.DECISION_AUTO_BATCH_SIZE || (LOW_BANDWIDTH_MODE ? '8' : '12'), 10) || 80)
);
const DECISION_AUTO_CONCURRENCY = Math.max(
  1, Math.min(6, Number.parseInt(process.env.DECISION_AUTO_CONCURRENCY || (LOW_BANDWIDTH_MODE ? '1' : '2'), 10) || 3)
);
const DECISION_AUTO_SYMBOL_TIMEOUT_MS = Math.max(
  10_000, Number.parseInt(process.env.DECISION_AUTO_SYMBOL_TIMEOUT_MS || (LOW_BANDWIDTH_MODE ? '25000' : '35000'), 10) || 45_000
);
const DECISION_AUTO_ALERT_COOLDOWN_MS = Math.max(
  60_000, Number.parseInt(process.env.DECISION_AUTO_ALERT_COOLDOWN_MS || '7200000', 10) || 7_200_000
);
const _decisionAutoScanState = {
  enabled: false,
  running: false,
  timer: null,
  cursor: 0,
  totalScanned: 0,
  lastCycleAt: 0,
  lastCycleDoneAt: 0,
  lastBatchScanned: 0,
  lastReadyCount: 0,
  lastAlertCount: 0,
  lastError: null,
  alertHistory: new Map(),
};

function getDecisionAutoScanStatus() {
  const universeSize = Array.isArray(_rankedSymbols)
    ? _rankedSymbols.filter(item => String(item?.symbol || '').endsWith('USDT')).length
    : 0;
  const cursorText = universeSize
    ? `${Math.min(_decisionAutoScanState.cursor, universeSize)}/${universeSize}`
    : 'waiting for Bitget universe';
  const lastDone = _decisionAutoScanState.lastCycleDoneAt
    ? new Date(_decisionAutoScanState.lastCycleDoneAt).toISOString()
    : 'not completed yet';
  return [
    '🧭 <b>Automatic Bitget decision scan</b>',
    `Status: <b>${_decisionAutoScanState.enabled ? (_decisionAutoScanState.running ? 'RUNNING' : 'ON') : 'STOPPED'}</b>`,
    `Bitget USDT perpetuals: <b>${universeSize}</b> | Rotation: <b>${cursorText}</b>`,
    `Batch: <b>${DECISION_AUTO_BATCH_SIZE}</b> assets every <b>${Math.round(DECISION_AUTO_INTERVAL_MS / 60000)} min</b>`,
    `Total attempted: <b>${_decisionAutoScanState.totalScanned}</b> | Last batch: <b>${_decisionAutoScanState.lastBatchScanned}</b>`,
    `Last ready plans: <b>${_decisionAutoScanState.lastReadyCount}</b> | Last alerts sent: <b>${_decisionAutoScanState.lastAlertCount}</b>`,
    `Last completed: <code>${lastDone}</code>`,
    _decisionAutoScanState.lastError ? `Last error: ${_decisionAutoScanState.lastError}` : '',
  ].filter(Boolean).join('\n');
}

function stopDecisionAutoScanner() {
  const wasEnabled = _decisionAutoScanState.enabled;
  _decisionAutoScanState.enabled = false;
  if (_decisionAutoScanState.timer) clearInterval(_decisionAutoScanState.timer);
  _decisionAutoScanState.timer = null;
  return wasEnabled;
}

function startDecisionAutoScanner() {
  if (_decisionAutoScanState.enabled && _decisionAutoScanState.timer) return false;
  _decisionAutoScanState.enabled = true;
  if (_decisionAutoScanState.timer) clearInterval(_decisionAutoScanState.timer);
  _decisionAutoScanState.timer = setInterval(() => {
    runDecisionAutoScan().catch(error =>
      console.error('Automatic decision scan scheduler error:', error.message)
    );
  }, DECISION_AUTO_INTERVAL_MS);
  // Delay the first run slightly so startup discovery and the regular scanner
  // can settle before the independent decision scan begins.
  setTimeout(() => {
    runDecisionAutoScan().catch(error =>
      console.error('Automatic decision scan startup error:', error.message)
    );
  }, LOW_BANDWIDTH_MODE ? 90_000 : 8_000);
  console.log(
    `🧭 Automatic Bitget decision scanner active: ${DECISION_AUTO_BATCH_SIZE} symbols every ${Math.round(DECISION_AUTO_INTERVAL_MS / 60000)} min`
  );
  return true;
}

function _decisionAutoExecutable(decision) {
  const plan = decision?.plan || {};
  const numericLevels = [plan.entry, plan.stop, plan.tp1, plan.tp2, plan.tp3].every(value =>
    Number.isFinite(Number(value)) && Number(value) > 0
  );
  return decision?.strictConfirmed === true &&
    ((decision.direction === 'BUY' && plan.order === 'BUY LIMIT') ||
      (decision.direction === 'SELL' && plan.order === 'SELL LIMIT')) &&
    numericLevels;
}

function _decisionAutoAlertBlock(decision) {
  const plan = decision.plan;
  const fmt = _tdFmt;
  return [
    `${decision.direction === 'BUY' ? '🟢' : '🔴'} <b>${decision.symbol} ${decision.direction} LIMIT</b>`,
    `Entry: <code>${fmt(plan.entry)}</code> | Zone: <code>${plan.entryZone || '—'}</code>`,
    `SL: <code>${fmt(plan.stop)}</code> | TP1: <code>${fmt(plan.tp1)}</code>`,
    `TP2: <code>${fmt(plan.tp2)}</code> | TP3: <code>${fmt(plan.tp3)}</code>`,
    `Live: <code>${fmt(decision.price)}</code> | 4H/1H confluence: <b>${decision.modelScore}/100</b>`,
    `Invalidation: ${plan.invalidation || 'see manual /decision report'}`,
    '<i>Conditional setup only; limit may not fill. This bot does not place orders.</i>',
  ].join('\n');
}

async function _decisionAutoSendAlerts(decisions) {
  const now = Date.now();
  const candidates = decisions.filter(decision => {
    const key = `${decision.symbol}:${decision.direction}`;
    const entry = Number(decision.plan.entry);
    const previous = _decisionAutoScanState.alertHistory.get(key);
    const materiallyMoved = previous?.entry > 0 &&
      Math.abs(entry - previous.entry) / previous.entry >= 0.004;
    return !previous ||
      now - previous.sentAt >= DECISION_AUTO_ALERT_COOLDOWN_MS ||
      materiallyMoved;
  });
  if (!candidates.length) return 0;

  const header = '🚨 <b>BITGET — EXECUTABLE 4H + 1H LIMIT SETUPS</b>\n';
  const chunks = [];
  let chunk = { text: header, decisions: [] };
  for (const decision of candidates) {
    const block = `\n\n${_decisionAutoAlertBlock(decision)}`;
    if (chunk.decisions.length && chunk.text.length + block.length > 3500) {
      chunks.push(chunk);
      chunk = { text: header, decisions: [] };
    }
    chunk.text += block;
    chunk.decisions.push(decision);
  }
  if (chunk.decisions.length) chunks.push(chunk);

  let sent = 0;
  for (let chunkIndex = 0; chunkIndex < chunks.length; chunkIndex++) {
    const item = chunks[chunkIndex];
    if (!_decisionAutoScanState.enabled) break;
    const response = await tg('sendMessage', {
      chat_id: TELEGRAM_CHAT_ID,
      text: item.text,
      parse_mode: 'HTML',
      disable_web_page_preview: true,
    }, 3);
    if (response?.ok) {
      const sentAt = Date.now();
      for (const decision of item.decisions) {
        _decisionAutoScanState.alertHistory.set(
          `${decision.symbol}:${decision.direction}`,
          { sentAt, entry: Number(decision.plan.entry) }
        );
      }
      sent += item.decisions.length;
    } else {
      console.warn('Automatic decision alert was not accepted by Telegram:', response?.description || 'no response');
    }
    if (chunkIndex < chunks.length - 1) await sleep(1100);
  }
  return sent;
}

async function runDecisionAutoScan() {
  if (!_decisionAutoScanState.enabled || _decisionAutoScanState.running) return;
  if (!TELEGRAM_CHAT_ID) {
    _decisionAutoScanState.lastError = 'TELEGRAM_CHAT_ID is not configured';
    console.warn('⏸️ Automatic decision scan skipped — TELEGRAM_CHAT_ID is not configured');
    return;
  }

  _decisionAutoScanState.running = true;
  _decisionAutoScanState.lastCycleAt = Date.now();
  _decisionAutoScanState.lastError = null;
  let attempted = 0;
  let ready = 0;
  let alertsSent = 0;
  try {
    await loadDynamicSymbolUniverse(!_dynamicSymbolsLoaded);
    const symbols = [...new Set((_rankedSymbols || [])
      .map(item => String(item?.symbol || '').toUpperCase())
      .filter(symbol => /^[A-Z0-9]+USDT$/.test(symbol)))];
    if (!symbols.length) {
      throw new Error('Bitget returned no ranked USDT perpetual symbols; no decision scan was run.');
    }

    const batchSize = Math.min(DECISION_AUTO_BATCH_SIZE, symbols.length);
    const start = _decisionAutoScanState.cursor % symbols.length;
    const batch = Array.from({ length: batchSize }, (_, index) =>
      symbols[(start + index) % symbols.length]
    );
    _decisionAutoScanState.cursor = (start + batchSize) % symbols.length;

    console.log(`🧭 Decision scan batch: ${batch.length}/${symbols.length} Bitget assets (cursor ${_decisionAutoScanState.cursor})`);
    const decisions = new Array(batch.length).fill(null);
    let nextIndex = 0;
    const worker = async () => {
      while (_decisionAutoScanState.enabled) {
        const index = nextIndex++;
        if (index >= batch.length) return;
        attempted++;
        const symbol = batch[index];
        try {
          decisions[index] = await raceDeadline(
            buildTotalMarketDecision(symbol, enhancedQuantumSystem?.signalGenerator || null),
            DECISION_AUTO_SYMBOL_TIMEOUT_MS,
            `autoDecision:${symbol}`
          );
        } catch (error) {
          console.warn(`Decision scan failed for ${symbol}:`, error.message);
        }
      }
    };
    await Promise.all(Array.from(
      { length: Math.min(DECISION_AUTO_CONCURRENCY, batch.length) },
      () => worker()
    ));

    const validDecisions = decisions.filter(Boolean);
    ready = validDecisions.filter(_decisionAutoExecutable).length;
    _decisionAutoScanState.totalScanned += attempted;
    _decisionAutoScanState.lastBatchScanned = attempted;
    _decisionAutoScanState.lastReadyCount = ready;
    if (_decisionAutoScanState.enabled && ready) {
      alertsSent = await _decisionAutoSendAlerts(validDecisions.filter(_decisionAutoExecutable));
    }
    _decisionAutoScanState.lastAlertCount = alertsSent;
    _decisionAutoScanState.lastCycleDoneAt = Date.now();
    console.log(
      `🧭 Decision scan batch complete: ${attempted}/${batch.length} attempted, ${ready} executable plans, ${alertsSent} alert(s) sent`
    );
  } catch (error) {
    _decisionAutoScanState.lastError = error.message;
    console.error('Automatic Bitget decision scan failed:', error.message);
  } finally {
    _decisionAutoScanState.running = false;
  }
}

/* ============================================================================
   TELEGRAM COMMAND IDEMPOTENCY
   ----------------------------------------------------------------------------
   Every feature patch above wraps handleEnhancedCommand. A duplicated
   Telegram update can otherwise run the entire wrapper chain again and send
   the same answer twice. Telegram message_id/update_id values are stable, so
   guard at the final prototype boundary after all wrappers are installed.
   ========================================================================== */
const _finalCommandHandler = EnhancedQuantumTelegramInterface.prototype.handleEnhancedCommand;
EnhancedQuantumTelegramInterface.prototype.handleEnhancedCommand = async function(message) {
  const updateId = message?._telegramUpdateId;
  const messageId = message?.message_id;
  const chatId = message?.chat?.id;
  const hasStableId = updateId !== undefined || messageId !== undefined;
  if (hasStableId) {
    if (!this._handledTelegramCommands) this._handledTelegramCommands = new Map();
    const key = updateId !== undefined
      ? `update:${String(updateId)}`
      : `message:${String(chatId)}:${String(messageId)}`;
    const now = Date.now();
    for (const [seenKey, seenAt] of this._handledTelegramCommands) {
      if (now - seenAt > 10 * 60 * 1000) this._handledTelegramCommands.delete(seenKey);
    }
    if (this._handledTelegramCommands.has(key)) {
      console.warn(`⏭️ Duplicate Telegram command ignored (${key})`);
      return;
    }
    this._handledTelegramCommands.set(key, now);
  }
  return _finalCommandHandler.call(this, message);
};

/* ════════════════════════════════════════════════════════════════════════════
   CONTINUATION ENGINE v1.1
   ─────────────────────────────────────────────────────────────────────────
   Purpose:
     A continuation setup often does not fail at the first liquidity pool.
     Price can sweep several same-side pools, exhaust the remaining opposing
     stops, and only then resume the higher-timeframe direction.

   This engine answers three separate questions:
     1. nextPool      — the next unswept pool price is likely to test;
     2. perfectPool   — the deepest reachable pool in the mapped sweep chain
                        before continuation pressure can resume;
     3. continuationEntry — the first recovery/continuation level after that
                            pool. This is a projection until a candle confirms.

   Important:
     "Perfect" here means the best-ranked exhaustion candidate in the
     available candle map, not a guaranteed price or win probability.
     The engine is deliberately advisory and does not replace the existing
     risk, leverage, invalidation, or confirmation gates.
   ════════════════════════════════════════════════════════════════════════════ */

const CONTINUATION_CACHE = new Map();
const CONTINUATION_CACHE_TTL = 35 * 1000;

function _ceNum(value, fallback = 0) {
  const n = Number(value);
  return Number.isFinite(n) ? n : fallback;
}

function _ceRound(value, price) {
  const n = _ceNum(value, 0);
  if (!n) return null;
  const decimals = price < 1 ? 8 : price < 10 ? 6 : price < 100 ? 4 : 2;
  const factor = 10 ** decimals;
  return Math.round(n * factor) / factor;
}

function _ceTick(price) {
  return price < 1 ? 0.00001
    : price < 10 ? 0.0001
      : price < 100 ? 0.001
        : price < 1000 ? 0.01 : 0.1;
}

function _ceClusterLevel(levels, level, tolerance) {
  return levels.find(item => Math.abs(item.level - level) / Math.max(level, 1e-12) <= tolerance);
}

function _ceBuildPools(candles, price, dir, atr) {
  const side = dir === 'BUY' ? 'below' : 'above';
  // Volatility-adaptive clustering: fixed 0.18% was too narrow for many
  // liquid altcoins and left the engine with no mapped pool.
  const tolerance = Math.max(0.0018, Math.min(0.006, (atr / Math.max(price, 1e-12)) * 0.25));
  const source = candles.slice(-90);
  const pools = [];

  for (let i = 2; i < source.length - 2; i++) {
    const candle = source[i];
    const level = dir === 'BUY' ? _ceNum(candle.l) : _ceNum(candle.h);
    if (!(level > 0)) continue;
    if (dir === 'BUY' && level >= price * 0.9995) continue;
    if (dir === 'SELL' && level <= price * 1.0005) continue;

    const isSwing = dir === 'BUY'
      ? level <= _ceNum(source[i - 1].l) &&
        level <= _ceNum(source[i - 2].l) &&
        level <= _ceNum(source[i + 1].l) &&
        level <= _ceNum(source[i + 2].l)
      : level >= _ceNum(source[i - 1].h) &&
        level >= _ceNum(source[i - 2].h) &&
        level >= _ceNum(source[i + 1].h) &&
        level >= _ceNum(source[i + 2].h);
    // A one-bar fractal catches valid but less obvious pivots missed by the
    // two-bar swing rule. It remains a projected pool, not a confirmed setup.
    const microSwing = dir === 'BUY'
      ? level <= _ceNum(source[i - 1].l) && level <= _ceNum(source[i + 1].l)
      : level >= _ceNum(source[i - 1].h) && level >= _ceNum(source[i + 1].h);

    const touches = source.filter(c => {
      const candidate = dir === 'BUY' ? _ceNum(c.l) : _ceNum(c.h);
      return candidate > 0 && Math.abs(candidate - level) / level <= tolerance;
    });
    if (!isSwing && !microSwing && touches.length < 2) continue;

    const existing = _ceClusterLevel(pools, level, tolerance * 1.6);
    const avgVol = source.reduce((sum, c) => sum + _ceNum(c.v), 0) / Math.max(source.length, 1) || 1;
    const touchVol = touches.reduce((sum, c) => sum + _ceNum(c.v), 0) /
      Math.max(touches.length, 1);
    const volumeRatio = touchVol / avgVol;

    if (existing) {
      existing.touches = Math.max(existing.touches, touches.length);
      existing.volumeRatio = Math.max(existing.volumeRatio, volumeRatio);
      existing.swing = existing.swing || isSwing;
      existing.microSwing = existing.microSwing || microSwing;
      existing.lastIndex = Math.max(existing.lastIndex, i);
      continue;
    }

    pools.push({
      level,
      touches: touches.length,
      volumeRatio,
      swing: isSwing,
      microSwing,
      lastIndex: i,
      side,
    });
  }

  // Last-resort map: when no classic pivot/equal-level survives, expose
  // recent range extremes as LOW-strength projected pools instead of returning
  // NO_SETUP for an otherwise valid 1H chart. These cannot confirm exhaustion
  // without a later post-pivot sweep and recovery.
  if (!pools.length) {
    for (const width of [12, 24, 48]) {
      const segment = source.slice(-width);
      if (segment.length < 8) continue;
      const level = dir === 'BUY'
        ? Math.min(...segment.map(c => _ceNum(c.l)))
        : Math.max(...segment.map(c => _ceNum(c.h)));
      if (!(level > 0) || (dir === 'BUY' ? level >= price : level <= price)) continue;
      const duplicate = _ceClusterLevel(pools, level, tolerance * 1.6);
      if (duplicate) continue;
      pools.push({
        level, touches: 1, volumeRatio: 1, swing: false, microSwing: false,
        fallback: true, lastIndex: source.length - 1,
        side, strength: 34,
      });
    }
  }

  const maxDistance = Math.max(atr * 5, price * 0.06);
  const filtered = pools
    .filter(pool => Math.abs(pool.level - price) <= maxDistance)
    .map(pool => {
      const distance = Math.abs(pool.level - price);
      const distanceAtr = atr > 0 ? distance / atr : 99;
      const recency = Math.max(0, 1 - (source.length - 1 - pool.lastIndex) / source.length);
      const strength = Math.min(100, Math.round(
        38 +
        Math.min(28, pool.touches * 9) +
        Math.min(18, Math.max(0, pool.volumeRatio - 1) * 10) +
        (pool.swing ? 8 : 0) +
        recency * 8
      ));
      return {
        ...pool,
        distance,
        distanceAtr: Math.round(distanceAtr * 100) / 100,
        strength,
      };
    })
    .sort((a, b) => dir === 'BUY'
      ? b.level - a.level
      : a.level - b.level);

  return filtered;
}

function _ceWasTouched(candles, pool, dir, lookback = 16) {
  // A pivot candle creates the liquidity pool; it must NOT count as the sweep.
  // Only candles printed after the latest candle contributing to that pool
  // can sweep it. The old implementation included the pivot itself, making
  // every newly discovered pool look already swept.
  const start = Math.max(0, Number(pool?.lastIndex || 0) + 1);
  const recent = candles.slice(Math.max(start, candles.length - lookback));
  return recent.some(c => dir === 'BUY'
    ? _ceNum(c.l) <= pool.level * 0.9995
    : _ceNum(c.h) >= pool.level * 1.0005);
}

function _ceRecoveredAfterTouch(candles, pool, dir, lookback = 16) {
  // Require a recovery close AFTER a post-pivot sweep. Reset the state on a
  // later re-sweep so an old recovery cannot confirm a newly failed level.
  const start = Math.max(0, Number(pool?.lastIndex || 0) + 1);
  const recent = candles.slice(Math.max(start, candles.length - lookback));
  let touched = false;
  for (const candle of recent) {
    const hit = dir === 'BUY'
      ? _ceNum(candle.l) <= pool.level * 0.9995
      : _ceNum(candle.h) >= pool.level * 1.0005;
    if (hit) {
      touched = true;
      continue;
    }
    if (touched && (dir === 'BUY'
      ? _ceNum(candle.c) > pool.level
      : _ceNum(candle.c) < pool.level)) return true;
  }
  return false;
}

function _ceDirectionQuality(candles, dir) {
  const sample = candles.slice(-8);
  if (sample.length < 4) return 0;
  const first = _ceNum(sample[0].c);
  const last = _ceNum(sample[sample.length - 1].c);
  if (!first || !last) return 0;
  const move = (last - first) / first;
  const aligned = dir === 'BUY' ? move > 0 : move < 0;
  const alignedBars = sample.filter(c => dir === 'BUY'
    ? _ceNum(c.c) > _ceNum(c.o)
    : _ceNum(c.c) < _ceNum(c.o)).length;
  return Math.max(0, Math.min(100, Math.round(
    (aligned ? 55 : 25) + alignedBars / sample.length * 35
  )));
}

function detectContinuationExhaustion(candles, price, dir, options = {}) {
  if (!Array.isArray(candles) || candles.length < 30 || !price || !['BUY', 'SELL'].includes(dir)) {
    return {
      state: 'NO_SETUP',
      direction: dir,
      nextPool: null,
      perfectPool: null,
      continuationEntry: null,
      confidence: 0,
      reason: 'At least 30 valid candles and a directional signal are required.',
    };
  }

  try {
    const valid = candles.filter(c =>
      _ceNum(c.o) > 0 && _ceNum(c.h) > 0 && _ceNum(c.l) > 0 && _ceNum(c.c) > 0 &&
      _ceNum(c.h) >= _ceNum(c.l)
    ).slice(-100);
    if (valid.length < 30) return {
      state: 'NO_SETUP',
      direction: dir,
      nextPool: null,
      perfectPool: null,
      continuationEntry: null,
      confidence: 0,
      reason: 'Not enough valid OHLC candles after normalization.',
    };

    const atr = valid.slice(-14).reduce((sum, c) => sum + (_ceNum(c.h) - _ceNum(c.l)), 0) / 14;
    if (!(atr > 0)) return {
      state: 'NO_SETUP',
      direction: dir,
      nextPool: null,
      perfectPool: null,
      continuationEntry: null,
      confidence: 0,
      reason: 'ATR is unavailable.',
    };

    const pools = _ceBuildPools(valid, price, dir, atr);
    if (!pools.length) return {
      state: 'NO_SETUP',
      direction: dir,
      nextPool: null,
      perfectPool: null,
      continuationEntry: null,
      confidence: 0,
      atr: _ceRound(atr, price),
      reason: `No ${dir === 'BUY' ? 'sell-side lows below' : 'buy-side highs above'} current price were inside the 5 ATR / 6% mapping window. Check candle order, OHLC fields, and live price.`,
    };

    // The existing liquidity context can contribute pools that the local
    // equal-high/equal-low scan did not retain. They are only added when they
    // are inside the same distance and are never allowed to outrank a stronger
    // candle-derived level at the same price.
    try {
      const liq = options.liqCtx || getLiquidityContext(valid, price);
      const external = dir === 'BUY' ? liq?.below : liq?.above;
      for (const level of Array.isArray(external) ? external : []) {
        const n = _ceNum(level);
        if (!n || (dir === 'BUY' ? n >= price : n <= price)) continue;
        if (Math.abs(n - price) > Math.max(atr * 3.8, price * 0.045)) continue;
        if (!_ceClusterLevel(pools, n, 0.003)) {
          pools.push({
            level: n,
            touches: 2,
            volumeRatio: 1,
            swing: false,
            lastIndex: valid.length - 1,
            side: dir === 'BUY' ? 'below' : 'above',
            distance: Math.abs(n - price),
            distanceAtr: Math.round(Math.abs(n - price) / atr * 100) / 100,
            strength: 52,
          });
        }
      }
    } catch (_) { /* local pool map is sufficient */ }

    pools.sort((a, b) => dir === 'BUY' ? b.level - a.level : a.level - b.level);
    const touched = pools.map(pool => ({
      ...pool,
      swept: _ceWasTouched(valid, pool, dir),
      recovered: _ceRecoveredAfterTouch(valid, pool, dir),
    }));

    const pending = touched.filter(pool => !pool.swept);
    const next = pending[0] || touched[0] || null;
    const reachable = touched
      .filter(pool => pool.distance <= atr * 3.5)
      .slice(0, 3);
    const chain = reachable.length ? reachable : touched.slice(0, 1);
    const perfect = chain[chain.length - 1] || null;
    const deeperReachable = touched.slice(chain.length).filter(pool => pool.distance <= atr * 3.8);
    const perfectSwept = Boolean(perfect?.swept);
    const perfectRecovered = Boolean(perfect?.recovered);
    const last = valid[valid.length - 1];
    const recent = valid.slice(-5);
    const directionalCloses = recent.filter(c => dir === 'BUY'
      ? _ceNum(c.c) > _ceNum(c.o)
      : _ceNum(c.c) < _ceNum(c.o)).length;
    const volumeDeclining = recent.length >= 3 &&
      _ceNum(recent[recent.length - 1].v) <= _ceNum(recent[recent.length - 2].v) &&
      _ceNum(recent[recent.length - 2].v) <= _ceNum(recent[recent.length - 3].v);
    const directionQuality = _ceDirectionQuality(valid, dir);
    const noDeeperPool = deeperReachable.length === 0;

    let score = 35;
    score += Math.min(20, (perfect?.strength || 0) * 0.2);
    score += Math.round(directionQuality * 0.18);
    score += chain.length >= 2 ? 8 : 0;
    score += noDeeperPool ? 10 : -12;
    score += perfectSwept ? 8 : 0;
    score += perfectRecovered ? 8 : 0;
    score += directionalCloses >= 3 ? 5 : 0;
    score += volumeDeclining ? 4 : 0;
    score = Math.max(0, Math.min(100, Math.round(score)));

    const tick = _ceTick(price);
    const continuationEntry = perfect
      ? _ceRound(dir === 'BUY' ? perfect.level + tick : perfect.level - tick, price)
      : null;
    const projectedTarget = dir === 'BUY'
      ? _ceRound(Math.max(...valid.slice(-20).map(c => _ceNum(c.h))) + atr, price)
      : _ceRound(Math.min(...valid.slice(-20).map(c => _ceNum(c.l))) - atr, price);

    let state = 'PRE_SWEEP';
    if (perfectSwept && perfectRecovered && noDeeperPool &&
      directionalCloses >= 3 && score >= 78) {
      state = 'EXHAUSTION_CONFIRMED';
    } else if (perfectSwept) {
      state = 'SWEEPING';
    } else if (next?.swept) {
      state = 'PARTIAL_SWEEP';
    }

    const fmt = value => _ceRound(value, price);
    const sweepPath = chain.map(pool => fmt(pool.level));
    const pendingPath = touched.filter(pool => !pool.swept).map(pool => fmt(pool.level));
    const perfectLabel = state === 'EXHAUSTION_CONFIRMED'
      ? 'Confirmed exhaustion pool'
      : 'Projected continuation-exhaustion pool';

    return {
      engine: 'CONTINUATION_EXHAUSTION',
      version: '1.1',
      state,
      direction: dir,
      atr: fmt(atr),
      confidence: score,
      directionQuality,
      nextPool: next ? fmt(next.level) : null,
      nextPoolStrength: next?.strength || 0,
      perfectPool: perfect ? fmt(perfect.level) : null,
      perfectPoolStrength: perfect?.strength || 0,
      continuationEntry,
      projectedTarget,
      poolCount: touched.length,
      poolsSwept: touched.filter(pool => pool.swept).length,
      poolsPending: pending.length,
      sweepPath,
      pendingPath,
      pools: touched.slice(0, 6).map(pool => ({
        level: fmt(pool.level),
        strength: pool.strength,
        distanceAtr: pool.distanceAtr,
        swept: pool.swept,
        recovered: pool.recovered,
        source: pool.fallback ? 'range-extreme' : (pool.swing ? 'swing' : 'cluster/fractal'),
      })),
      criteria: {
        trendAligned: directionQuality >= 55,
        multiplePools: chain.length >= 2,
        deepestPoolMapped: Boolean(perfect),
        noDeeperReachablePool: noDeeperPool,
        exhaustionPoolSwept: perfectSwept,
        recoveryAfterSweep: perfectRecovered,
        volumeDeclining,
        directionalCloses: directionalCloses >= 3,
      },
      rationale: perfect
        ? `${dir} continuation path: ${sweepPath.join(' → ')}. ` +
          `The best exhaustion candidate is ${fmt(perfect.level)}; ` +
          `continuation entry is projected at ${continuationEntry}.`
        : `Next ${dir === 'BUY' ? 'downside' : 'upside'} pool is ${fmt(next?.level)}.`,
      warning: state === 'EXHAUSTION_CONFIRMED'
        ? 'Exhaustion is confirmed by the available candles; keep the existing stop and invalidation rules.'
        : `Projection only: wait for a ${dir === 'BUY' ? 'bullish' : 'bearish'} recovery close at/after the exhaustion pool.`,
      generatedAt: Date.now(),
    };
  } catch (error) {
    console.warn('Continuation exhaustion engine error:', error.message);
    return {
      engine: 'CONTINUATION_EXHAUSTION',
      state: 'ERROR',
      direction: dir,
      nextPool: null,
      perfectPool: null,
      continuationEntry: null,
      confidence: 0,
      reason: error.message,
    };
  }
}

function formatContinuationExhaustion(continuation) {
  if (!continuation || continuation.state === 'NO_SETUP' || continuation.state === 'ERROR') return '';
  const icon = continuation.state === 'EXHAUSTION_CONFIRMED' ? '✅'
    : continuation.state === 'SWEEPING' ? '🔄'
      : continuation.state === 'PARTIAL_SWEEP' ? '⚠️' : '👁';
  const fmt = value => value == null ? 'N/A' : String(value);
  const path = continuation.sweepPath?.length
    ? continuation.sweepPath.join(' → ') : 'N/A';
  const pending = continuation.pendingPath?.length
    ? continuation.pendingPath.join(' → ') : 'none';
  return [
    '\n━━━ 🔁 CONTINUATION EXHAUSTION ENGINE ━━━',
    `${icon} <b>${continuation.state.replace(/_/g, ' ')}</b> | Model score: <b>${continuation.confidence}/100</b>`,
    `<b>Liquidity map:</b> ${continuation.poolCount || 0} pool(s) · ${continuation.poolsSwept || 0} swept · ${continuation.poolsPending || 0} pending`,
    `<b>Next pool likely swept:</b> <code>${fmt(continuation.nextPool)}</code> (${continuation.nextPoolStrength || 0}/100 strength)`,
    `<b>${continuation.state === 'EXHAUSTION_CONFIRMED' ? 'Exhaustion pool confirmed' : 'Perfect exhaustion candidate'}:</b> <code>${fmt(continuation.perfectPool)}</code>`,
    `<b>Projected continuation entry:</b> <code>${fmt(continuation.continuationEntry)}</code>`,
    `<b>Sweep path:</b> ${path}`,
    `<b>Still pending:</b> ${pending}`,
    continuation.rationale || '',
    `<i>${continuation.warning || 'Projection only; wait for the recovery candle and keep risk controls active.'}</i>`,
  ].filter(Boolean).join('\n');
}

// Attach the engine after the complete wrapper chain so every scan path gets
// the same continuation result, including manual scans and recovery scans.
const _ceOriginalBuild = buildInstitutionalContextFull;
buildInstitutionalContextFull = async function(symbol, price, dir) {
  const base = await _ceOriginalBuild(symbol, price, dir);
  if (!base || !price || !dir) return base;
  const key = `ce_${symbol}_${dir}_${Math.round(Number(price) * 10000) / 10000}`;
  const cached = CONTINUATION_CACHE.get(key);
  if (cached && Date.now() - cached.ts < CONTINUATION_CACHE_TTL) {
    base.continuation = cached.data;
    base._continuation = true;
    return base;
  }
  const candles = base._sharedCandles || base.candles || [];
  const continuation = detectContinuationExhaustion(candles, Number(price), dir, { liqCtx: base.liq });
  CONTINUATION_CACHE.set(key, { data: continuation, ts: Date.now() });
  base.continuation = continuation;
  base._continuation = true;
  return base;
};

const _ceOriginalFormat = formatInstitutionalContext;
