/* 1) RISK-NORMALIZED POSITION SIZER (RNPS) */
const RNPS_CONFIG = {
  accountRiskPct: parseFloat(process.env.ACCOUNT_RISK_PERCENT || '1.0'),
  minStopPct: parseFloat(process.env.RNPS_MIN_STOP_PCT || '1.5'),
  maxStopPct: parseFloat(process.env.RNPS_MAX_STOP_PCT || '3.5'),
  bufferPct: parseFloat(process.env.RNPS_BUFFER_PCT || '0.4'),
  accountBalance: parseFloat(process.env.ACCOUNT_BALANCE || '5000'),
  defaultStopPct: parseFloat(process.env.RNPS_DEFAULT_STOP || '2.0'),
};

function computeStructureStopDistance(candles, price, dir, instCtx) {
  if (!Array.isArray(candles) || candles.length < 30 || !(price > 0) ||
      !['BUY', 'SELL'].includes(dir)) {
    return {
      stopDistancePct: RNPS_CONFIG.defaultStopPct,
      structuralLevel: null,
      reason: 'Insufficient data — using default stop distance',
    };
  }
  const sample = candles.slice(-60);
  const atrValues = sample.slice(-14).map(c => Number(c.h) - Number(c.l)).filter(v => v > 0);
  const atr = atrValues.length ? atrValues.reduce((a, b) => a + b, 0) / atrValues.length : 0;
  const atrPct = atr > 0 ? atr / price * 100 : 0;
  let structuralLevel = null;
  let reason = '';

  if (dir === 'BUY') {
    for (let i = sample.length - 3; i >= 5; i--) {
      const l = Number(sample[i].l);
      if (l < price && l < Number(sample[i - 1].l) && l < Number(sample[i - 2].l) &&
          l < Number(sample[i + 1].l) && l < Number(sample[i + 2].l)) {
        structuralLevel = l;
        reason = `Stop below swing low ${l.toPrecision(6)}`;
        break;
      }
    }
    if (structuralLevel == null) {
      structuralLevel = price - atr * 1.5;
      reason = 'No recent swing low — using 1.5× ATR';
    }
  } else {
    for (let i = sample.length - 3; i >= 5; i--) {
      const h = Number(sample[i].h);
      if (h > price && h > Number(sample[i - 1].h) && h > Number(sample[i - 2].h) &&
          h > Number(sample[i + 1].h) && h > Number(sample[i + 2].h)) {
        structuralLevel = h;
        reason = `Stop above swing high ${h.toPrecision(6)}`;
        break;
      }
    }
    if (structuralLevel == null) {
      structuralLevel = price + atr * 1.5;
      reason = 'No recent swing high — using 1.5× ATR';
    }
  }

  let rawDistancePct = Math.abs(price - structuralLevel) / price * 100 + RNPS_CONFIG.bufferPct;
  if (atrPct > rawDistancePct * 0.8) {
    rawDistancePct = Math.max(rawDistancePct, atrPct * 1.3);
    reason += ` · widened for ATR ${atrPct.toFixed(2)}%`;
  }
  const stopDistancePct = Math.max(
    RNPS_CONFIG.minStopPct,
    Math.min(RNPS_CONFIG.maxStopPct, rawDistancePct)
  );
  return { stopDistancePct, structuralLevel, reason, magnetAdjusted: false };
}

function computeRiskNormalizedPosition(entryPrice, stopDistancePct, riskPct, balance) {
  const entry = Number(entryPrice);
  const stopPct = Number(stopDistancePct);
  const risk = Number(riskPct ?? RNPS_CONFIG.accountRiskPct);
  const account = Number(balance ?? RNPS_CONFIG.accountBalance);
  if (!(entry > 0) || !(stopPct > 0) || !(risk > 0) || !(account > 0)) {
    return { positionSize: 0, riskAmount: 0, error: 'Invalid sizing input' };
  }
  const riskAmount = account * risk / 100;
  const stopDistancePrice = entry * stopPct / 100;
  return {
    positionSize: Number((riskAmount / stopDistancePrice).toPrecision(8)),
    riskAmount: Number(riskAmount.toFixed(2)),
    stopPrice: Number(stopDistancePrice.toPrecision(8)), // NOTE: a price DISTANCE (entry x stop%), kept for compatibility
    stopDistance: Number(stopDistancePrice.toPrecision(8)),
    stopDistancePct: stopPct,
    entry,
  };
}

function enrichSignalWithRiskSizing(signal, candles, instCtx) {
  if (!signal || !['BUY', 'SELL'].includes(signal.direction)) return signal;
  try {
    const entry = Number(signal.entry || signal.price);
    if (!(entry > 0)) return signal;
    const stopData = computeStructureStopDistance(candles, entry, signal.direction, instCtx);
    const sizing = computeRiskNormalizedPosition(entry, stopData.stopDistancePct);
    signal.riskSizing = {
      stopDistancePct: stopData.stopDistancePct,
      structuralLevel: stopData.structuralLevel,
      reason: stopData.reason,
      positionSize: sizing.positionSize,
      riskAmount: sizing.riskAmount,
      stopPrice: sizing.stopPrice, // distance in price units (legacy name)
      stopDistance: sizing.stopDistance,
      stopPriceAbsolute: Number((signal.direction === 'BUY'
        ? entry - sizing.stopDistance
        : entry + sizing.stopDistance).toPrecision(8)),
      riskPct: RNPS_CONFIG.accountRiskPct,
    };
    if (signal.position_size !== undefined) signal.position_size = sizing.positionSize;
  } catch (error) {
    console.warn('RNPS enrich error:', error.message);
  }
  return signal;
}

const _rnpsOriginalCaptureSignal = captureSignal;
captureSignal = function(signal) {
  try {
    const ctx = signal?._instCtx;
    const candles = ctx?._sharedCandles || ctx?.candles || [];
    enrichSignalWithRiskSizing(signal, candles, ctx);
  } catch (error) {
    console.warn('RNPS capture hook error:', error.message);
  }
  return _rnpsOriginalCaptureSignal(signal);
};

