/* 2) DAILY TRADE GOVERNOR (DTG) */
const DTG_FILE = storagePath('daily_trade_governor.json');
try { STORAGE_LIMITS['daily_trade_governor.json'] = 32 * 1024; } catch (_) {}
const DTG_CONFIG = {
  maxTradesPerDay: Math.max(1, parseInt(process.env.DTG_MAX_TRADES || '1', 10)),
  riskPctFixed: parseFloat(process.env.DTG_RISK_PCT || process.env.ACCOUNT_RISK_PERCENT || '1.0'),
  accountBalance: parseFloat(process.env.ACCOUNT_BALANCE || '5000'),
  resetMinuteUTC: parseInt(process.env.DTG_RESET_MINUTE_UTC || '30', 10),
  resetHourUTC: parseInt(process.env.DTG_RESET_HOUR_UTC || '0', 10),
};
