/* 3) BREAKOUT MIDWAY PAUSE DETECTOR (BMPD) */
const BMPD_CACHE = new Map();
function detectMidwayPause(candles, price, dir) {
  if (!Array.isArray(candles) || candles.length < 60 || !(price > 0) ||
      !['BUY', 'SELL'].includes(dir)) return null;
  try {
    const slice = candles.slice(-100);
    const ranges = slice.slice(-14).map(c => Number(c.h) - Number(c.l)).filter(v => v > 0);
    const atr = ranges.length ? ranges.reduce((a, b) => a + b, 0) / ranges.length : 0;
    if (!(atr > 0)) return null;
    const highs = [], lows = [];
    for (let i = 5; i < slice.length - 5; i++) {
      const h = Number(slice[i].h), l = Number(slice[i].l);
      if (slice.slice(i - 5, i).every(c => Number(c.h) <= h) &&
          slice.slice(i + 1, i + 6).every(c => Number(c.h) <= h)) highs.push({ idx: i, price: h });
      if (slice.slice(i - 5, i).every(c => Number(c.l) >= l) &&
          slice.slice(i + 1, i + 6).every(c => Number(c.l) >= l)) lows.push({ idx: i, price: l });
    }
    const refs = dir === 'BUY' ? highs : lows;
    if (refs.length < 2) return null;
    const ref = refs[refs.length - 1];
    const bosIndex = slice.findIndex((c, i) => i > ref.idx &&
      (dir === 'BUY' ? Number(c.c) > ref.price * 1.0003 : Number(c.c) < ref.price * 0.9997));
    if (bosIndex < 0) return null;
    const older = refs.filter(x => x.idx < ref.idx).map(x => x.price);
    if (!older.length) return null;
    const finalTarget = dir === 'BUY' ? Math.max(...older) : Math.min(...older);
    const lastClose = Number(slice.at(-1).c);
    if (dir === 'BUY' ? lastClose >= finalTarget * 0.998 : lastClose <= finalTarget * 1.002) return null;
    const bosClose = Number(slice[bosIndex].c);
    const totalRange = dir === 'BUY' ? finalTarget - bosClose : bosClose - finalTarget;
    if (!(totalRange > 0)) return null;
    const travelled = dir === 'BUY' ? lastClose - bosClose : bosClose - lastClose;
    const progressPct = travelled / totalRange;
    if (progressPct < 0.5 || progressPct > 0.8) return null;
    const afterBos = slice.slice(bosIndex + 1);
    let pauseStart = -1, pauseEnd = -1, pauseCount = 0;
    for (let i = 0; i < Math.min(afterBos.length, 12); i++) {
      const c = afterBos[i];
      const pause = dir === 'BUY' ? Number(c.c) < Number(c.o) : Number(c.c) > Number(c.o);
      if (pause) {
        if (pauseStart < 0) pauseStart = bosIndex + 1 + i;
        pauseEnd = bosIndex + 1 + i;
        pauseCount++;
      } else if (pauseStart >= 0) break;
    }
    if (pauseCount < 2 || pauseCount > 3 || slice.length - 1 - pauseEnd > 5) return null;
    const pauseBars = slice.slice(pauseStart, pauseEnd + 1);
    const bosLevel = dir === 'BUY' ? Number(slice[bosIndex].h) : Number(slice[bosIndex].l);
    const bosHolds = pauseBars.every(c => dir === 'BUY'
      ? Number(c.c) > bosLevel : Number(c.c) < bosLevel);
    const smallBodies = pauseBars.every(c => {
      const range = Math.max(Number(c.h) - Number(c.l), 1e-9);
      return Math.abs(Number(c.c) - Number(c.o)) / range < 0.4;
    });
    const wicks = pauseBars.every(c => {
      const body = Math.abs(Number(c.c) - Number(c.o));
      const lower = Math.min(Number(c.c), Number(c.o)) - Number(c.l);
      const upper = Number(c.h) - Math.max(Number(c.c), Number(c.o));
      return dir === 'BUY' ? lower >= body * 0.9 : upper >= body * 0.9;
    });
    const volumes = pauseBars.map(c => Number(c.v) || 0);
    const volumeDeclines = volumes.length > 1 && volumes.at(-1) <= volumes[0] * 0.85;
    const extreme = dir === 'BUY'
      ? Math.min(...pauseBars.map(c => Number(c.l)))
      : Math.max(...pauseBars.map(c => Number(c.h)));
    const inMiddle = dir === 'BUY'
      ? extreme > bosClose && extreme < finalTarget
      : extreme < bosClose && extreme > finalTarget;
    const rulesPassed = [bosHolds, smallBodies, wicks, volumeDeclines, inMiddle].filter(Boolean).length;
    if (rulesPassed < 4) return null;
    const entry = dir === 'BUY'
      ? Math.max(extreme, lastClose - atr * 0.15)
      : Math.min(extreme, lastClose + atr * 0.15);
    const stop = dir === 'BUY' ? extreme - atr * 0.6 : extreme + atr * 0.6;
    return {
      direction: dir, pattern: 'BREAKOUT_MIDWAY_PAUSE',
      entry, stop, tp1: dir === 'BUY' ? entry + (finalTarget - entry) * 0.33 : entry - (entry - finalTarget) * 0.33,
      tp2: dir === 'BUY' ? entry + (finalTarget - entry) * 0.66 : entry - (entry - finalTarget) * 0.66,
      tp3: finalTarget, pauseCount, pauseExtreme: extreme, bosLevel, finalTarget,
      progressPct: Math.round(progressPct * 1000) / 10, rulesPassed,
      recoveryConfirmed: Boolean(slice[pauseEnd + 1]),
      confidence: Math.round(55 + rulesPassed * 8),
      reason: `Post-BOS ${dir === 'BUY' ? 'bullish' : 'bearish'} pause — ${pauseCount} candles, ${Math.round(progressPct * 100)}% to target.`,
    };
  } catch (error) {
    console.warn('BMPD error:', error.message);
    return null;
  }
}
const _bmpdOriginalBuild = buildInstitutionalContextFull;
buildInstitutionalContextFull = async function(symbol, price, dir) {
  const base = await _bmpdOriginalBuild(symbol, price, dir);
  try {
    const key = `bmpd_${symbol}_${dir}_${Math.round(Number(price) * 10000)}`;
    const cached = BMPD_CACHE.get(key);
    if (cached && Date.now() - cached.ts < 40000) {
      if (base) base.midwayPause = cached.data;
      return base;
    }
    const candles = base?._sharedCandles || base?.candles ||
      await fetchCandlesCached(symbol, '1h', 150).catch(() => null);
    const data = candles ? detectMidwayPause(candles, Number(price), dir) : null;
    BMPD_CACHE.set(key, { ts: Date.now(), data });
    if (base) {
      base.midwayPause = data;
      base.midwayPauseOpposite = candles
        ? detectMidwayPause(candles, Number(price), dir === 'BUY' ? 'SELL' : 'BUY') : null;
    }
  } catch (error) { console.warn('BMPD wiring error:', error.message); }
  return base;
};
const _bmpdOriginalFormat = formatInstitutionalContext;
formatInstitutionalContext = function(ctx, dir) {
  let message = '';
  try { message = _bmpdOriginalFormat(ctx, dir) || ''; } catch (error) {}
  const p = ctx?.midwayPause;
  if (p?.rulesPassed >= 4) {
    const f = v => Number(v).toPrecision(6);
    message += [
      '', '━━━ 🛑 BREAKOUT MIDWAY PAUSE ━━━',
      `${p.direction === 'BUY' ? '🟢🌱' : '🔴🌱'} <b>Engineered pause detected</b> (${p.rulesPassed}/5 rules)`,
      `${p.pauseCount} candles paused at ${p.progressPct}% toward target`,
      `BOS: <code>${f(p.bosLevel)}</code> · Pause extreme: <code>${f(p.pauseExtreme)}</code>`,
      `🎯 Entry: <code>${f(p.entry)}</code> · Stop: <code>${f(p.stop)}</code>`,
      `🏁 Continuation target: <code>${f(p.finalTarget)}</code>`,
      `<i>${p.reason}</i>`,
    ].join('\n');
  }
  return message;
};
const _bmpdOriginalAnalyse = analyseSignalInternal;
analyseSignalInternal = function(consensus, instCtx, scored) {
  let result = '';
  try { result = _bmpdOriginalAnalyse(consensus, instCtx, scored) || ''; } catch (error) {}
  const p = instCtx?.midwayPause;
  if (p?.rulesPassed >= 4 && consensus?.consensusDirection === p.direction) {
    result += `\n\n🛑 <b>MIDWAY PAUSE — CONTINUATION TARGET</b>\n` +
      `The ${p.pauseCount}-candle pause held the BOS. Target: <code>${Number(p.finalTarget).toPrecision(6)}</code>`;
  }
  return result;
};
console.log('✅ BMPD loaded — post-BOS engineered pause detector');

/* 4) CONTINUATION LOWER-HIGH TRAP DETECTOR */
function detectLowerHighTrap(candles, price, dir = 'SELL') {
  if (!Array.isArray(candles) || candles.length < 40 || !(price > 0)) return null;
  try {
    const slice = candles.slice(-60);
    const highs = [], lows = [];
    for (let i = 5; i < slice.length - 5; i++) {
      const h = Number(slice[i].h), l = Number(slice[i].l);
      if (slice.slice(i - 5, i).every(c => Number(c.h) <= h) &&
          slice.slice(i + 1, i + 6).every(c => Number(c.h) <= h)) highs.push({ idx: i, price: h });
      if (slice.slice(i - 5, i).every(c => Number(c.l) >= l) &&
          slice.slice(i + 1, i + 6).every(c => Number(c.l) >= l)) lows.push({ idx: i, price: l });
    }
    if (lows.length < 3 || highs.length < 2) return null;
    const LL = lows.slice(-3), LH = highs.slice(-2);
    if (!(LL[1].price < LL[0].price && LL[2].price < LL[1].price &&
          LH[1].price < LH[0].price &&
          LL[0].idx < LH[0].idx && LH[0].idx < LL[1].idx &&
          LL[1].idx < LH[1].idx && LH[1].idx < LL[2].idx)) return null;
    const last = slice.at(-1);
    const rallyInProgress = Number(last.c) > LL[2].price && Number(last.c) < LH[1].price;
    const ranges = slice.slice(-14).map(c => Number(c.h) - Number(c.l)).filter(v => v > 0);
    const atr = ranges.reduce((a, b) => a + b, 0) / Math.max(1, ranges.length);
    if (Math.abs(Number(last.c) - LH[1].price) / atr > 0.75) return null;
    const volAtLL = slice.slice(Math.max(0, LL[2].idx - 2), LL[2].idx + 3)
      .reduce((s, c) => s + (Number(c.v) || 0), 0) / 5;
    const volAvg = slice.reduce((s, c) => s + (Number(c.v) || 0), 0) / slice.length;
    const defended = slice.slice(-12).some(c => {
      const near = Math.abs(Number(c.h) - LH[1].price) / LH[1].price < 0.005;
      const wick = Number(c.h) - Math.max(Number(c.c), Number(c.o));
      return near && wick > Math.abs(Number(c.c) - Number(c.o)) * 0.8;
    });
    const rallyBars = slice.slice(LL[2].idx).filter(c => Number(c.c) > Number(c.o));
    const fading = rallyBars.length >= 3 &&
      Number(rallyBars.at(-1).c) - Number(rallyBars.at(-1).o) <
      Number(rallyBars.at(-3).c) - Number(rallyBars.at(-3).o);
    const score = [volAtLL < volAvg * 1.2, defended, fading, rallyInProgress].filter(Boolean).length;
    if (score < 2) return null;
    return {
      direction: 'SELL', pattern: 'CONTINUATION_LOWER_HIGH_TRAP',
      entry: Math.min(Number(last.c), LH[1].price),
      stop: LH[1].price + atr * 0.6,
      targets: [LL[2].price, LL[2].price - (LL[1].price - LL[2].price), LL[1].price],
      trapScore: score, rallyTarget: LH[1].price, thirdLow: LL[2].price,
      confidence: Math.round(55 + score * 10),
      reason: `Third lower low failed to break prior lower high ${LH[1].price.toPrecision(6)}. Trap score ${score}/4.`,
    };
  } catch (error) { console.warn('LowerHighTrap error:', error.message); return null; }
}
