/* 5) SPRING TRAP DETECTOR */
function detectSpringTrap(candles, price, dir = 'BUY') {
  if (!Array.isArray(candles) || candles.length < 50 || !(price > 0) || dir !== 'BUY') return null;
  try {
    const slice = candles.slice(-80);
    const ranges = slice.slice(-14).map(c => Number(c.h) - Number(c.l)).filter(v => v > 0);
    const atr = ranges.reduce((a, b) => a + b, 0) / Math.max(1, ranges.length);
    const highs = [], lows = [];
    for (let i = 5; i < slice.length - 5; i++) {
      const h = Number(slice[i].h), l = Number(slice[i].l);
      if (slice.slice(i - 5, i).every(c => Number(c.h) <= h) &&
          slice.slice(i + 1, i + 6).every(c => Number(c.h) <= h)) highs.push({ idx: i, price: h });
      if (slice.slice(i - 5, i).every(c => Number(c.l) >= l) &&
          slice.slice(i + 1, i + 6).every(c => Number(c.l) >= l)) lows.push({ idx: i, price: l });
    }
    if (lows.length < 3 || highs.length < 2) return null;
    const LL = lows.slice(-3);
    if (!(LL[2].price < LL[1].price && LL[1].price < LL[0].price)) return null;
    const candidates = highs.filter(h => h.idx > LL[1].idx && h.idx < LL[2].idx);
    if (!candidates.length) return null;
    const brokenLH = candidates.reduce((a, b) => a.price > b.price ? a : b);
    const bosIndex = slice.findIndex((c, i) => i > LL[2].idx && Number(c.c) > brokenLH.price);
    if (bosIndex < 0) return null;
    const afterBos = slice.slice(bosIndex + 1);
    let start = -1, end = -1, redCount = 0;
    for (let i = 0; i < Math.min(afterBos.length, 5); i++) {
      if (Number(afterBos[i].c) < Number(afterBos[i].o)) {
        if (start < 0) start = bosIndex + 1 + i;
        end = bosIndex + 1 + i;
        redCount++;
      } else if (start >= 0) break;
    }
    if (redCount < 2 || redCount > 3) return null;
    const pullback = slice.slice(start, end + 1);
    const pullbackLow = Math.min(...pullback.map(c => Number(c.l)));
    const bosHigh = Math.max(Number(slice[bosIndex].h), ...slice.slice(bosIndex + 1, start).map(c => Number(c.h)));
    const range = Math.max(bosHigh - LL[2].price, 1e-9);
    const retrace = (bosHigh - pullbackLow) / range;
    const bosVolume = Number(slice[bosIndex].v) || 0;
    const pullbackVolume = pullback.reduce((s, c) => s + (Number(c.v) || 0), 0) / pullback.length;
    const lastRed = slice[end];
    const redBody = Math.abs(Number(lastRed.c) - Number(lastRed.o));
    const lowerWick = Math.min(Number(lastRed.c), Number(lastRed.o)) - Number(lastRed.l);
    const recovery = slice[end + 1];
    const rules = [
      retrace >= 0.30 && retrace <= 0.65,
      bosVolume > 0 && pullbackVolume < bosVolume * 0.85,
      redBody > 0 && lowerWick >= redBody * 1.5,
      pullbackLow > brokenLH.price * 0.998,
      Boolean(recovery && Number(recovery.c) > Number(recovery.o) &&
        Number(recovery.c) > Number(lastRed.o)),
    ];
    const rulesPassed = rules.filter(Boolean).length;
    if (rulesPassed < 4) return null;
    const priorHighs = highs.filter(h => h.idx < LL[0].idx).map(h => h.price);
    const target = priorHighs.length ? Math.max(...priorHighs) : bosHigh + range * 2;
    const entry = Math.max(pullbackLow, Number(recovery?.c || lastRed.c) - atr * 0.1);
    return {
      direction: 'BUY', pattern: 'SPRING_TRAP',
      entry, stop: Math.min(pullbackLow - atr * 0.5, brokenLH.price - atr * 0.2),
      tp1: brokenLH.price + (target - brokenLH.price) * 0.33,
      tp2: brokenLH.price + (target - brokenLH.price) * 0.66,
      tp3: target, rulesPassed, retracePct: Math.round(retrace * 1000) / 10,
      brokenLH: brokenLH.price, thirdLow: LL[2].price, targetHH: target,
      confidence: Math.round(55 + rulesPassed * 8),
      reason: `Third low → BOS ${brokenLH.price.toPrecision(6)} → ${redCount} red pause → spring recovery (${rulesPassed}/5 rules).`,
    };
  } catch (error) { console.warn('SpringTrap error:', error.message); return null; }
}
