/* 7) TELEGRAM COMMANDS */
const _integratedUpgradeHandler = EnhancedQuantumTelegramInterface.prototype.handleEnhancedCommand;
EnhancedQuantumTelegramInterface.prototype.handleEnhancedCommand = async function(message) {
  const text = String(message?.text || '').trim();
  const args = text.split(/\s+/);
  const cmd = (args[0] || '').toLowerCase().replace(/@[^\s]+$/, '');
  const chatId = message?.chat?.id;
  if (cmd === '/dtg' || cmd === '/governor') {
    if (!isAdminMessage(message)) return;
    if ((args[1] || '').toLowerCase() === 'reset') {
      _dtgState.tradesToday = 0;
      _dtgState.lastTradeSymbol = null;
      _dtgState.lastTradeDir = null;
      _dtgState.dayKey = _dtgTodayKey();
      _dtgSave();
      await this.sendMessage(chatId, '✅ DTG reset. One trade is now available today.');
      return;
    }
    const s = dtgStatus();
    await this.sendMessage(chatId, [
      '📋 <b>DAILY TRADE GOVERNOR</b>',
      `Day: <b>${s.dayKey}</b>`,
      `Trades today: <b>${s.tradesToday}/${s.maxPerDay}</b>`,
      `Remaining: <b>${s.remaining}</b>`,
      `Fixed risk: <b>$${s.riskAmount}</b> (${s.riskPct}%)`,
      s.lastTradeAt ? `Last: <b>${s.lastTradeSymbol} ${s.lastTradeDir}</b>` : 'No trades logged today.',
      '',
      s.remaining === 0 ? '🛑 <b>DAY CLOSED</b>' : '✅ <b>ARMED</b>',
      '<code>/dtg reset</code> — manual reset only when no trade was taken',
    ].join('\n'));
    return;
  }
  if (cmd === '/masterplan' || cmd === '/mp') {
    if (!isAdminMessage(message)) return;
    const symbol = normalizeAnalysisSymbol(args[1]);
    const dir = String(args[2] || '').toUpperCase();
    if (!symbol || (dir && !['BUY', 'SELL'].includes(dir))) {
      await this.sendMessage(chatId, 'Usage: <code>/masterplan SYMBOL [BUY|SELL]</code>\nDirection may be omitted; the closed 4H structure will infer it.');
      return;
    }
    try {
      await this.sendMessage(chatId, `🎯 Running integrated master plan for <b>${symbol}${dir ? ` ${dir}` : ''}</b>...`);
      const masterPlan = await withTimeout(
        buildMasterPlan(symbol, dir || null),
        MASTERPLAN_TOTAL_TIMEOUT_MS,
        `masterplan ${symbol} ${dir || 'AUTO'}`
      ).catch(error => ({
        error: `Master Plan timed out after ${Math.round(MASTERPLAN_TOTAL_TIMEOUT_MS / 1000)} seconds.`,
        symbol, dir: dir || 'AUTO', partial: true, detail: error.message,
      }));
      const card = formatMasterPlan(masterPlan);
      for (const chunk of splitTelegramText(card)) {
        await this.sendMessage(chatId, chunk);
      }
    } catch (error) {
      await this.sendMessage(chatId, `❌ Master plan error: ${error.message}`);
    }
    return;
  }
  return _integratedUpgradeHandler.call(this, message);
};
