/* ══════════════════════════════════════════════════════════════════════════
   EXECUTION LAYER
   ──────────────────────────────────────────────────────────────────────────
   Adapted from the supplied execution-layer applier. The applier itself is
   not copied into this bot: its plan builder, pending-entry alerts, journal,
   Main Brain feedback, and Telegram commands are installed natively here.
   ══════════════════════════════════════════════════════════════════════════ */

 /*
  * Master-plan entry resolver.
  *
  * A SELL LIMIT must sit above the live price and a BUY LIMIT must sit below
  * it. The 4H structure mapper normally guarantees that geometry, but a
  * stale/partial structure object or a caller-supplied price can otherwise
  * leak a target from the wrong side into the execution plan.
  *
  * Keep the resolver source-agnostic: every asset gets the same validation,
  * and invalid source levels use the existing guarded safe-limit engine.
  */
 function _resolveMasterPlanEntry(mp, structure, price, dir, opts = {}) {
   const candidates = [
     { value: opts.entry, source: 'EXPLICIT_ENTRY' },
     { value: structure?.entry, source: '4H_STRUCTURE_ENTRY' },
     { value: mp.validatorWinner?.price, source: 'VALIDATED_LIQUIDITY' },
     { value: mp.requestedPrice, source: 'REQUESTED_PRICE' },
   ];
   const isValid = value => {
     const n = Number(value);
     return Number.isFinite(n) && n > 0 &&
       (dir === 'BUY' ? n < price : n > price);
   };

   for (const candidate of candidates) {
     if (isValid(candidate.value)) {
       return {
         price: Number(candidate.value),
         source: candidate.source,
         fallback: false,
       };
     }
   }

   // No source level is usable. Use the same guarded limit calculator used
   // by the rest of the engine; never invent a stale symbol-specific price.
   const validatorScore = Number(mp.validatorWinner?.score);
   const safe = typeof selectBestLimitGuarded === 'function'
     ? selectBestLimitGuarded(price, dir, {
         // A missing validator score is an unknown, not a zero-confidence
         // score. Preserve the safe-limit engine's normal fallback in that
         // case; an explicitly low score remains gated as before.
         cert: Number.isFinite(validatorScore) && validatorScore > 0
           ? validatorScore : null,
       })
     : null;
   if (safe && isValid(safe.price)) {
     return {
       price: Number(safe.price),
       source: safe.source || 'SAFE_PULLBACK',
       fallback: true,
       label: safe.label || 'Guarded safe-limit fallback',
     };
   }

   // Returning null is safer than turning an invalid directional level into
   // an executable plan.
   return null;
 }

 function assembleTradePlan(mp, candles, opts = {}) {
  if (!mp || mp.error) return null;
  const dir = mp.dir || mp.direction;
  const price = Number(mp.price);
  if (!['BUY', 'SELL'].includes(dir) || !(price > 0)) return null;

  const structure = mp.structure4h || mp.structure || null;
   // A mapped level is not an executable plan. Do not render an entry for a
   // touched, already-broken, stale, or still-distant structure state.
   if (structure?.state && !structure.actionable) return null;
   const entryInfo = _resolveMasterPlanEntry(mp, structure, price, dir, opts);
   if (!entryInfo) return null;
   const entry = entryInfo.price;
  const exit = Number(
    opts.exit || structure?.target || mp.primaryExit || mp.validatorWinner?.price
  );
   if (!(entry > 0) || !(exit > 0) ||
       (dir === 'BUY' ? exit <= entry : exit >= entry)) return null;

  let stopInfo = null;
  try {
    stopInfo = computeStructureStopDistance(
      Array.isArray(candles) ? candles : [], entry, dir, null
    );
  } catch (_) {}
  const stopPct = Number(stopInfo?.stopDistancePct || RNPS_CONFIG.defaultStopPct);
  const stop = dir === 'BUY'
    ? entry * (1 - stopPct / 100)
    : entry * (1 + stopPct / 100);
  const sizing = computeRiskNormalizedPosition(entry, stopPct);
  const rewardPct = Math.abs(exit - entry) / entry * 100;
  const rr = stopPct > 0 ? rewardPct / stopPct : null;
  const notional = sizing.positionSize * entry;
  const distanceToEntryPct = Math.abs(price - entry) / price * 100;
  const confirming = [];

  const governor = dtgCanTrade(mp.symbol, dir);
  if (!governor.allowed) confirming.push(`DTG: ${governor.reason}`);
  else confirming.push(`DTG: ${governor.tradesRemaining} trade available today`);
  if (mp.verdict?.startsWith('WATCH')) confirming.push('Verdict is WATCH — wait for state upgrade');
  if (structure?.state && structure.state !== 'BREAK_CONFIRMED') {
    confirming.push(`Structure state: ${structure.state} — wait for the 4H break trigger`);
  }
  if (mp.validatorWinner?.score && mp.validatorWinner.score < 95) {
    confirming.push(`Validator: ${mp.validatorWinner.score}% (<95% confluence gate)`);
  }
   if (entryInfo.fallback) {
     confirming.push(
       `${entryInfo.label || 'Guarded safe-limit fallback'} used because source levels were invalid for ${dir}`
     );
   }

  return {
    symbol: mp.symbol, dir, livePrice: price, entry,
     entrySource: entryInfo.source,
     entryFallback: entryInfo.fallback,
    sweep: mp.validatorWinner?.price && Number(mp.validatorWinner.price) !== entry
      ? Number(mp.validatorWinner.price) : null,
    exit, stop, stopPct, rewardPct, rr,
    size: sizing.positionSize, riskUsd: sizing.riskAmount, notional,
    ifWin: notional * rewardPct / 100, ifLoss: sizing.riskAmount,
    distanceToEntryPct, verdict: mp.verdict,
    state: structure?.state || null,
    trigger: structure?.trigger || null,
    validatorScore: mp.validatorWinner?.score || 0,
    atlasTier: mp.atlasTier || 'N/A', apexTier: mp.apexTier || 'N/A',
    stopReason: stopInfo?.reason || 'RNPS structural stop',
    confirming, generatedAt: Date.now(),
  };
}

function formatAssembledPlan(plan) {
  if (!plan) return '❌ No trade plan assembled.';
  const f = value => {
    const n = Number(value);
    if (!Number.isFinite(n)) return '?';
    if (Math.abs(n) >= 1000) return n.toFixed(2);
    if (Math.abs(n) >= 1) return n.toFixed(4);
    return n.toFixed(6);
  };
  const pct = value => value == null ? '?' :
    `${value >= 0 ? '+' : ''}${Number(value).toFixed(2)}%`;
  const usd = value => value == null ? '?' :
    `${value >= 0 ? '+$' : '-$'}${Math.abs(Number(value)).toFixed(2)}`;
  return [
    '━━━ 📋 ASSEMBLED TRADE PLAN ━━━',
    `${plan.symbol} ${plan.dir} · Live: <code>${f(plan.livePrice)}</code>`,
    `Distance to entry: <b>${pct(-plan.distanceToEntryPct)}</b>`,
    '',
    `📍 <b>ENTRY:</b> <code>${f(plan.entry)}</code>`,
    plan.sweep ? `🎯 <b>SWEEP:</b> <code>${f(plan.sweep)}</code>` : '',
    `🏁 <b>EXIT:</b> <code>${f(plan.exit)}</code> (${pct(plan.rewardPct)})`,
    `🛑 <b>STOP:</b> <code>${f(plan.stop)}</code> (-${Number(plan.stopPct).toFixed(2)}%)`,
    plan.trigger ? `⚡ <b>BREAK TRIGGER:</b> <code>${f(plan.trigger)}</code>` : '',
    '',
    `📦 <b>SIZE:</b> <code>${f(plan.size)}</code> units`,
    `💵 <b>NOTIONAL:</b> <code>$${Number(plan.notional).toFixed(2)}</code>`,
    `⚠️ <b>RISK:</b> <code>${usd(plan.riskUsd)}</code>`,
    `💰 <b>IF WIN:</b> ${usd(plan.ifWin)} · <b>IF LOSS:</b> ${usd(-plan.ifLoss)}`,
    `📊 <b>R:R:</b> <code>1:${plan.rr == null ? '?' : Number(plan.rr).toFixed(2)}</code>`,
    '',
    '━━━ ⏳ CONFIRMATION GATE ━━━',
    ...(plan.confirming || []).map(item => `• ${item}`),
    '',
    '━━━ 🏛️ SOURCE ENGINES ━━━',
    `Verdict: <b>${String(plan.verdict || 'WAIT').replace(/_/g, ' ')}</b> · State: ${plan.state || 'n/a'}`,
    `Validator: ${plan.validatorScore}% · ATLAS: ${plan.atlasTier} · APEX: ${plan.apexTier}`,
    `<i>${plan.stopReason}</i>`,
  ].filter(Boolean).join('\n');
}

/* Pending approach alerts are keyed by symbol and direction so a refreshed
   plan does not create duplicate notifications. */
const PLAN_ALERTS_FILE = storagePath('plan_alerts.json');
try { STORAGE_LIMITS['plan_alerts.json'] = 128 * 1024; } catch (_) {}
const _planAlerts = new Map();
function _planAlertsSave() {
  writeJsonBounded(PLAN_ALERTS_FILE, Array.from(_planAlerts.values()).slice(-200), {
    maxBytes: 128 * 1024,
  });
}
function _planAlertsLoad() {
  try {
    if (!fs.existsSync(PLAN_ALERTS_FILE)) return;
    const rows = JSON.parse(fs.readFileSync(PLAN_ALERTS_FILE, 'utf8'));
    if (!Array.isArray(rows)) return;
    for (const row of rows) {
      if (row?.symbol && row?.dir && Number(row.entry) > 0) {
        _planAlerts.set(`${row.symbol}:${row.dir}`, row);
      }
    }
  } catch (error) { console.warn('Plan alert load skipped:', error.message); }
}
function registerPlanAlert(plan, source = 'masterplan') {
  if (!plan || !plan.symbol || !plan.dir || !(plan.entry > 0)) return null;
  const key = `${plan.symbol}:${plan.dir}`;
  const existing = _planAlerts.get(key);
  if (existing && Math.abs(existing.entry - plan.entry) / plan.entry < 0.001) return existing;
  const row = {
    symbol: plan.symbol, dir: plan.dir, entry: plan.entry,
    exit: plan.exit, stop: plan.stop, stopPct: plan.stopPct, rr: plan.rr,
    registeredAt: Date.now(), firedAt: null, source,
  };
  _planAlerts.set(key, row);
  _planAlertsSave();
  return row;
}
async function checkPendingAlerts() {
  if (!_planAlerts.size) return;
  const now = Date.now();
  for (const [key, alert] of _planAlerts) {
    if (alert.firedAt) continue;
    if (now - alert.registeredAt > 7 * 24 * 60 * 60 * 1000) {
      _planAlerts.delete(key);
      continue;
    }
    try {
      const live = Number(await fetchLivePrice(alert.symbol).catch(() => 0));
      if (!(live > 0)) continue;
      const distancePct = Math.abs(live - alert.entry) / live * 100;
      if (distancePct > Number(process.env.PLAN_ALERT_DISTANCE_PCT || '0.5')) continue;
      alert.firedAt = now;
      _planAlertsSave();
      if (typeof tg === 'function' && process.env.TELEGRAM_CHAT_ID) {
        const f = value => Number(value).toPrecision(6);
        await tg('sendMessage', {
          chat_id: process.env.TELEGRAM_CHAT_ID,
          text: [
            `🚨 <b>PLAN APPROACHING ENTRY — ${alert.symbol} ${alert.dir}</b>`,
            `Live: <code>${f(live)}</code> · Entry: <code>${f(alert.entry)}</code> (${distancePct.toFixed(3)}% away)`,
            alert.stop ? `Stop: <code>${f(alert.stop)}</code> (-${Number(alert.stopPct || 0).toFixed(2)}%)` : '',
            alert.exit ? `Exit: <code>${f(alert.exit)}</code>` : '',
            alert.rr ? `R:R: <b>1:${Number(alert.rr).toFixed(2)}</b>` : '',
            '',
            '⏳ Wait for the required 4H break trigger before treating this as executable.',
            `📝 Use /took ${alert.symbol} ${alert.dir} <entry> when executed.`,
          ].filter(Boolean).join('\n'),
          parse_mode: 'HTML',
          disable_web_page_preview: true,
        }).catch(() => {});
      }
    } catch (_) {}
  }
}
_planAlertsLoad();
