/* Persistent manual trade journal. Closing a trade also updates the Main
   Brain calibration ledger when a matching plan exists. */
const TRADE_JOURNAL_FILE = storagePath('trade_journal.json');
try { STORAGE_LIMITS['trade_journal.json'] = 256 * 1024; } catch (_) {}
const _tradeJournal = [];
try {
  if (fs.existsSync(TRADE_JOURNAL_FILE)) {
    const saved = JSON.parse(fs.readFileSync(TRADE_JOURNAL_FILE, 'utf8'));
    if (Array.isArray(saved)) _tradeJournal.push(...saved.slice(-2000));
  }
} catch (error) { console.warn('Trade journal load skipped:', error.message); }
function _tradeJournalSave() {
  while (_tradeJournal.length > 2000) _tradeJournal.shift();
  writeJsonBounded(TRADE_JOURNAL_FILE, _tradeJournal, { maxBytes: 256 * 1024 });
}
function journalRecordEntry(symbol, dir, entry, opts = {}) {
  try {
    const sql = globalThis.__neonState?.client;
    if (sql) {
      sql`
        INSERT INTO trade_journal (symbol, direction, entry, stop, exit)
        VALUES (${String(symbol).toUpperCase()}, ${String(dir).toUpperCase()},
          ${Number(entry) || null}, ${Number(opts.stop) || null}, ${Number(opts.exit) || null})
      `.catch(err => console.warn('[NEON] journal insert failed:', err.message));
    }
  } catch (_) {}

  const row = {
    id: `TJ-${Date.now()}-${_tradeJournal.length}`,
    symbol, dir, entry: Number(entry),
    stop: opts.stop == null ? null : Number(opts.stop),
    exit: opts.exit == null ? null : Number(opts.exit),
    size: opts.size == null ? null : Number(opts.size),
    riskUsd: opts.riskUsd == null ? null : Number(opts.riskUsd),
    rr: opts.rr == null ? null : Number(opts.rr),
    verdict: opts.verdict || null, state: opts.state || null,
    enteredAt: Date.now(), closedAt: null, closePrice: null,
    outcome: null, pnlUsd: null, pnlPct: null, note: opts.note || null,
  };
  _tradeJournal.push(row);
  _tradeJournalSave();
  return row;
}
function journalCloseTrade(id, closePrice, note = null) {
  const row = _tradeJournal.find(item => item.id === id);
  const close = Number(closePrice);
  if (!row || row.closedAt || !(close > 0)) return null;
  row.closedAt = Date.now();
  row.closePrice = close;
  row.pnlPct = row.dir === 'BUY'
    ? (close - row.entry) / row.entry * 100
    : (row.entry - close) / row.entry * 100;
  row.pnlUsd = row.size ? row.pnlPct / 100 * row.entry * row.size : null;
  row.outcome = row.pnlPct > 0.05 ? 'WIN' : row.pnlPct < -0.05 ? 'LOSS' : 'BREAKEVEN';
  if (note) row.note = note;
  _tradeJournalSave();

  try {
    const sql = globalThis.__neonState?.client;
    if (sql && row.symbol && row.dir) {
      sql`
        UPDATE trade_journal
           SET exit = ${Number(close) || null}, outcome = ${row.outcome}, pnl_pct = ${Number(row.pnlPct) || null}
         WHERE id = (
           SELECT id FROM trade_journal
            WHERE symbol = ${String(row.symbol).toUpperCase()} AND direction = ${String(row.dir).toUpperCase()} AND exit IS NULL
            ORDER BY created_at DESC LIMIT 1
         )
      `.catch(err => console.warn('[NEON] journal update failed:', err.message));
    }
  } catch (_) {}
  try {
    if (row.outcome !== 'BREAKEVEN' && typeof _mbRecordOutcome === 'function') {
      _mbRecordOutcome(row.symbol, row.dir, row.outcome === 'WIN', row.entry);
    }
  } catch (_) {}
  return row;
}
function journalStats() {
  const closed = _tradeJournal.filter(row => row.closedAt);
  const wins = closed.filter(row => row.outcome === 'WIN');
  const losses = closed.filter(row => row.outcome === 'LOSS');
  const breakeven = closed.filter(row => row.outcome === 'BREAKEVEN');
  const totalPnl = closed.reduce((sum, row) => sum + (Number(row.pnlUsd) || 0), 0);
  return {
    total: _tradeJournal.length, open: _tradeJournal.filter(row => !row.closedAt).length,
    closed: closed.length, wins: wins.length, losses: losses.length, breakeven: breakeven.length,
    winRate: closed.length ? Math.round(wins.length / closed.length * 100) : 0,
    totalPnlUsd: Number(totalPnl.toFixed(2)),
    avgWinUsd: wins.length ? Number((wins.reduce((s, r) => s + (r.pnlUsd || 0), 0) / wins.length).toFixed(2)) : 0,
    avgLossUsd: losses.length ? Number((losses.reduce((s, r) => s + (r.pnlUsd || 0), 0) / losses.length).toFixed(2)) : 0,
    expectancyUsd: closed.length ? Number((totalPnl / closed.length).toFixed(2)) : 0,
  };
}

