/* ===== Integrated from Pasted Wyckoff Institutional Footprint v3.0 ===== */
/* ═══════════════════════════════════════════════════════════════════════════
   WYCKOFF INSTITUTIONAL FOOTPRINT ENGINE v3.0
   ─────────────────────────────────────────────────────────────────────────
   Synthesises all prior Wyckoff layers into ONE coherent institutional
   narrative per asset per scan. This is the "desk view" layer — the way a
   composite operator sees the market.

   8 modules:
   1. Composite Operator Intent Scorer      — who is in control?
   2. Wyckoff Phase Sequence Tracker        — 9-step schematic state machine
   3. Causal Chain Detection                — Accum → Markup → Dist → Markdown
   4. Cross-Asset Sector Correlation        — is this a sector-wide footprint?
   5. Smart Money vs Retail Divergence      — positioning asymmetry
   6. Volume Spread Analysis (VSA)          — Tom Williams layer
   7. Time-Cycle Alignment                  — Wyckoff time/price relationship
   8. Institutional Execution Simulator     — what a desk would do NOW
   ═══════════════════════════════════════════════════════════════════════════ */

const WYCKOFF_FOOTPRINT_ENABLED = process.env.WYCKOFF_FOOTPRINT_ENABLED !== '0';
const WYCKOFF_FOOTPRINT_CACHE = new Map();
const WYCKOFF_FOOTPRINT_CACHE_TTL = 3 * 60 * 1000;

/* ══════════════════════════════════════════════════════════════════════════
   MODULE 1 — COMPOSITE OPERATOR INTENT SCORER
   ─────────────────────────────────────────────────────────────────────────
   The composite operator is the entity (or coordinated group) that is
   accumulating or distributing. We can't see them directly. We infer intent
   from the relationship between:
     - Price action (what happened)
     - Volume (how much conviction)
     - Time (how long they've been working)
     - Location (where in the range)
     - Follow-through (did the move stick?)

   Output: intent vector [accumulate, distribute, markup, markdown]
   with confidence per dimension.
   ══════════════════════════════════════════════════════════════════════════ */
function _wyfootCompositeOperatorIntent(bars, atr) {
  if (!bars || bars.length < 60 || !(atr > 0)) {
    return { intent: 'UNKNOWN', confidence: 0, vector: { accumulate: 0, distribute: 0, markup: 0, markdown: 0 } };
  }

  const slice = bars.slice(-60);
  const recent = slice.slice(-20);
  const currentPrice = slice.at(-1).c;
  const rangeHigh = Math.max(...slice.map(c => c.h));
  const rangeLow = Math.min(...slice.map(c => c.l));
  const rangeWidth = rangeHigh - rangeLow;
  const rangePos = rangeWidth > 0 ? (currentPrice - rangeLow) / rangeWidth : 0.5;

  const avgVol60 = slice.reduce((s, c) => s + c.v, 0) / slice.length;
  const recentVol = recent.reduce((s, c) => s + c.v, 0) / recent.length;
  const volExpansion = avgVol60 > 0 ? recentVol / avgVol60 : 1;

  // Trend via EMA slope over the slice
  const ema20 = _tdEma(slice.map(c => c.c), 20);
  const ema50 = _tdEma(slice.map(c => c.c), 50);
  const trendUp = ema20 > ema50;
  const slope = slice.slice(-10).reduce((s, c, i, arr) =>
    i === 0 ? 0 : s + (c.c - arr[i - 1].c), 0) / 9;

  // Accumulation signals: price at lows, volume expanding, but no breakdown
  const accumScore = Math.max(0, (1 - rangePos) * 60) +
    (volExpansion > 1.15 ? 20 : 0) +
    (slope > -atr * 0.15 ? 20 : 0);

  // Distribution signals: price at highs, volume expanding, but no breakout
  const distScore = Math.max(0, rangePos * 60) +
    (volExpansion > 1.15 ? 20 : 0) +
    (slope < atr * 0.15 ? 20 : 0);

  // Markup signals: strong uptrend, high follow-through, volume on up-moves
  const upBars = recent.filter(c => c.c > c.o);
  const upVol = upBars.reduce((s, c) => s + c.v, 0) / Math.max(1, upBars.length);
  const markupScore = (trendUp ? 40 : 0) +
    (slope > atr * 0.3 ? 30 : 0) +
    (upVol > avgVol60 * 1.2 ? 30 : 0);

  // Markdown signals: strong downtrend
  const downBars = recent.filter(c => c.c < c.o);
  const downVol = downBars.reduce((s, c) => s + c.v, 0) / Math.max(1, downBars.length);
  const markdownScore = (!trendUp ? 40 : 0) +
    (slope < -atr * 0.3 ? 30 : 0) +
    (downVol > avgVol60 * 1.2 ? 30 : 0);

  const vector = {
    accumulate: Math.min(100, Math.round(accumScore)),
    distribute: Math.min(100, Math.round(distScore)),
    markup:     Math.min(100, Math.round(markupScore)),
    markdown:   Math.min(100, Math.round(markdownScore)),
  };

  const entries = Object.entries(vector);
  const [dominant, confidence] = entries.reduce((best, curr) =>
    curr[1] > best[1] ? curr : best, entries[0]);

  // Require clear dominance — if 2nd is close, intent is ambiguous
  const sorted = entries.sort((a, b) => b[1] - a[1]);
  const isAmbiguous = sorted[1][1] > sorted[0][1] * 0.85;

  return {
    intent: isAmbiguous ? 'AMBIGUOUS' : dominant.toUpperCase(),
    confidence: isAmbiguous ? Math.round(sorted[0][1] * 0.5) : confidence,
    vector,
    rangePos: Number(rangePos.toFixed(3)),
    volExpansion: Number(volExpansion.toFixed(2)),
    trend: trendUp ? 'UP' : 'DOWN',
    slope: Number((slope / atr).toFixed(3)),
  };
}

/* ══════════════════════════════════════════════════════════════════════════
   MODULE 2 — WYCKOFF PHASE SEQUENCE TRACKER (9-STEP SCHEMATIC)
   ─────────────────────────────────────────────────────────────────────────
   Wyckoff defined the accumulation/distribution schematic as a SPECIFIC
   SEQUENCE of events, not individual signals. This module tracks where in
   the sequence the market currently is.

   ACCUMULATION:  PS → SC → AR → ST → Spring → Test → SOS → LPS → BU
   DISTRIBUTION:  PSY → BC → AR → ST → UT → UTAD → SOW → LPSY → BU

   Each phase has a specific character. The engine identifies the LAST
   confirmed phase, and reports what must happen for the NEXT phase to fire.
   ══════════════════════════════════════════════════════════════════════════ */
function _wyfootPhaseSequence(bars, atr, direction = 'BUY') {
  if (!bars || bars.length < 80 || !(atr > 0)) {
    return { phase: 'UNKNOWN', position: -1, nextPhase: null, sequence: [] };
  }
  const slice = bars.slice(-100);
  const rangeWindow = slice.slice(0, 60);
  const rangeHigh = Math.max(...rangeWindow.map(c => c.h));
  const rangeLow = Math.min(...rangeWindow.map(c => c.l));
  const rangeWidth = rangeHigh - rangeLow;
  if (!(rangeWidth > atr * 1.5)) return { phase: 'NO_RANGE', position: -1, nextPhase: null, sequence: [] };

  const postRange = slice.slice(60);
  const avgVolume = rangeWindow.reduce((sum, c) => sum + c.v, 0) / rangeWindow.length;
  const barVolume = c => avgVolume > 0 ? c.v / avgVolume : 1;
  const barRange = c => Math.max(c.h - c.l, Number.EPSILON);
  const nearLow = c => c.l <= rangeLow + atr * 0.55;
  const nearHigh = c => c.h >= rangeHigh - atr * 0.55;
  const hasSpring = postRange.some(c => c.l < rangeLow - atr * 0.10 && c.c > rangeLow + atr * 0.05);
  const hasUpthrust = postRange.some(c => c.h > rangeHigh + atr * 0.10 && c.c < rangeHigh - atr * 0.05);
  const sosIndex = postRange.findIndex(c => c.c > rangeHigh + atr * 0.15);
  const sowIndex = postRange.findIndex(c => c.c < rangeLow - atr * 0.15);
  const hasSOS = sosIndex >= 0;
  const hasSOW = sowIndex >= 0;
  const hasLPS = hasSOS && postRange.slice(sosIndex + 1)
    .some(c => c.l <= rangeHigh + atr * 0.10 && c.c > rangeHigh);
  const hasLPSY = hasSOW && postRange.slice(sowIndex + 1)
    .some(c => c.h >= rangeLow - atr * 0.10 && c.c < rangeLow);
  const hasBU = hasSOS && postRange.slice(-5).every(c => c.c > rangeHigh);
  const hasBD = hasSOW && postRange.slice(-5).every(c => c.c < rangeLow);

  let phases;
  if (direction === 'SELL') {
    const bcIndex = rangeWindow.findIndex(c =>
      nearHigh(c) && barVolume(c) >= 1.5 && (c.h - c.c) / barRange(c) >= 0.35
    );
    const bc = bcIndex >= 0 ? rangeWindow[bcIndex] : null;
    const arIndex = bcIndex >= 0
      ? rangeWindow.findIndex((c, i) => i > bcIndex && c.l <= bc.h - atr * 1.5)
      : -1;
    const hasAR = arIndex >= 0;
    const hasST = hasAR && rangeWindow.slice(arIndex + 1)
      .some(c => nearHigh(c) && (!bc || c.h <= bc.h + atr * 0.1));
    const hasPSY = rangeWindow.some(c =>
      nearHigh(c) && barVolume(c) >= 1.2 && c.c > c.o
    );
    phases = [
      { name: 'PSY', present: hasPSY, desc: 'Preliminary Supply' },
      { name: 'BC', present: Boolean(bc), desc: 'Buying Climax' },
      { name: 'AR', present: hasAR, desc: 'Automatic Reaction' },
      { name: 'ST', present: hasST, desc: 'Secondary Test' },
      { name: 'Upthrust', present: hasUpthrust, desc: 'Upthrust / UTAD' },
      { name: 'SOW', present: hasSOW, desc: 'Sign of Weakness' },
      { name: 'LPSY', present: hasLPSY, desc: 'Last Point of Supply' },
      { name: 'BU', present: hasBD, desc: 'Breakdown continuation' },
    ];
  } else {
    const scIndex = rangeWindow.findIndex(c =>
      nearLow(c) && barVolume(c) >= 1.5 &&
      (c.c < c.o || (c.c - c.l) / barRange(c) >= 0.55)
    );
    const sc = scIndex >= 0 ? rangeWindow[scIndex] : null;
    const arIndex = scIndex >= 0
      ? rangeWindow.findIndex((c, i) => i > scIndex && c.h >= sc.l + atr * 1.5)
      : -1;
    const hasAR = arIndex >= 0;
    const hasST = hasAR && rangeWindow.slice(arIndex + 1)
      .some(c => c.l >= sc.l && c.l <= sc.l + atr * 0.75);
    const hasPS = rangeWindow.some(c =>
      nearLow(c) && barVolume(c) >= 1.2 && c.c < c.o
    );
    const springIndex = postRange.findIndex(c =>
      c.l < rangeLow - atr * 0.10 && c.c > rangeLow + atr * 0.05
    );
    const hasTest = springIndex >= 0 && postRange.slice(springIndex + 1)
      .some(c => c.l >= postRange[springIndex].l && c.l <= postRange[springIndex].l + atr * 0.5 && c.c > c.l);
    phases = [
      { name: 'PS', present: hasPS, desc: 'Preliminary Support' },
      { name: 'SC', present: Boolean(sc), desc: 'Selling Climax' },
      { name: 'AR', present: hasAR, desc: 'Automatic Rally' },
      { name: 'ST', present: hasST, desc: 'Secondary Test' },
      { name: 'Spring', present: hasSpring, desc: 'Spring / Shakeout' },
      { name: 'Test', present: hasTest, desc: 'Test of Spring' },
      { name: 'SOS', present: hasSOS, desc: 'Sign of Strength' },
      { name: 'LPS', present: hasLPS, desc: 'Last Point of Support' },
      { name: 'BU', present: hasBU, desc: 'Backup / Breakout' },
    ];
  }
  let position = -1;
  phases.forEach((p, i) => { if (p.present) position = i; });

  const nextPhase = phases[position + 1] || null;

  return {
    phase: phases[position]?.name || 'RANGE',
    desc: phases[position]?.desc || (direction === 'SELL' ? 'Distribution Range' : 'Accumulation Range'),
    position,
    nextPhase: nextPhase ? { name: nextPhase.name, desc: nextPhase.desc } : null,
    sequence: phases.map(p => ({ name: p.name, present: p.present })),
    hasSpring, hasSOS, hasLPS, hasBU: direction === 'SELL' ? hasBD : hasBU,
    hasUpthrust, hasSOW, hasLPSY,
    rangeHigh: _wyckoffRound(rangeHigh),
    rangeLow: _wyckoffRound(rangeLow),
  };
}

/* ══════════════════════════════════════════════════════════════════════════
   MODULE 3 — CAUSAL CHAIN DETECTION
   ─────────────────────────────────────────────────────────────────────────
   Every Wyckoff cycle is: ACCUMULATION → MARKUP → DISTRIBUTION → MARKDOWN.
   Each phase CAUSES the next. This module measures where we are in the
   4-phase cycle and how mature each phase is.
   ══════════════════════════════════════════════════════════════════════════ */
function _wyfootCausalChain(bars, atr) {
  if (!bars || bars.length < 100 || !(atr > 0)) {
    return { stage: 'UNKNOWN', maturityPct: 0, nextStage: null };
  }
  const slice = bars.slice(-150);
  // Segment into quarters
  const q = Math.floor(slice.length / 4);
  const q1 = slice.slice(0, q);
  const q2 = slice.slice(q, q * 2);
  const q3 = slice.slice(q * 2, q * 3);
  const q4 = slice.slice(q * 3);

  const avg = arr => arr.length ? arr.reduce((s, c) => s + c.c, 0) / arr.length : 0;
  const avgV = arr => arr.length ? arr.reduce((s, c) => s + c.v, 0) / arr.length : 0;

  const p1 = avg(q1), p2 = avg(q2), p3 = avg(q3), p4 = avg(q4);
  const v1 = avgV(q1), v2 = avgV(q2), v3 = avgV(q3), v4 = avgV(q4);

  // Determine current stage by comparing quarters
  let stage = 'ACCUMULATION';
  let maturityPct = 25;

  if (p4 > p1 * 1.05 && v4 > v1) {
    stage = 'MARKUP';
    maturityPct = Math.min(90, Math.round((p4 / p1 - 1) * 200));
  } else if (p4 > p1 && v4 < v1) {
    stage = 'DISTRIBUTION';
    maturityPct = Math.min(85, Math.round((v1 / v4 - 1) * 100 + 40));
  } else if (p4 < p1 * 0.95 && v4 > v1) {
    stage = 'MARKDOWN';
    maturityPct = Math.min(90, Math.round((1 - p4 / p1) * 200));
  } else {
    stage = 'ACCUMULATION';
    const compression = Math.abs(p4 - p1) / p1;
    maturityPct = Math.min(80, Math.round((1 - compression * 10) * 60 + 20));
  }

  const nextMap = {
    ACCUMULATION: 'MARKUP',
    MARKUP: 'DISTRIBUTION',
    DISTRIBUTION: 'MARKDOWN',
    MARKDOWN: 'ACCUMULATION',
  };

  return {
    stage,
    maturityPct: Math.max(10, Math.min(95, maturityPct)),
    nextStage: nextMap[stage],
    quarterPrices: [p1, p2, p3, p4].map(v => Number(v.toPrecision(6))),
    quarterVols: [v1, v2, v3, v4].map(v => Number(v.toFixed(0))),
  };
}

/* ══════════════════════════════════════════════════════════════════════════
   MODULE 4 — CROSS-ASSET SECTOR CORRELATION
   ─────────────────────────────────────────────────────────────────────────
   Institutions don't accumulate single assets in isolation. When smart
   money rotates into a sector, they work the WHOLE sector: BTC → ETH →
   large alts → sector leaders → mid caps → small caps.

   If your asset shows Spring but the entire sector is in Markdown, the
   Spring is likely a fake. If sector-leading peers are all in Accumulation
   too, the Spring is confirmed.
   ══════════════════════════════════════════════════════════════════════════ */
const WYCKOFF_SECTOR_PEERS = {
  'BTCUSDT':  ['ETHUSDT', 'BNBUSDT'],
  'ETHUSDT':  ['BTCUSDT', 'ARBUSDT', 'OPUSDT', 'MATICUSDT'],
  'SOLUSDT':  ['JUPUSDT', 'BONKUSDT', 'WIFUSDT'],
  'BNBUSDT':  ['CAKEUSDT'],
  'ARBUSDT':  ['OPUSDT', 'MATICUSDT', 'ETHUSDT'],
  'OPUSDT':   ['ARBUSDT', 'MATICUSDT', 'ETHUSDT'],
  'AVAXUSDT': ['SOLUSDT', 'NEARUSDT'],
  'LINKUSDT': ['UNIUSDT', 'AAVEUSDT'],
  'DOGEUSDT': ['SHIBUSDT', 'PEPEUSDT'],
  'PEPEUSDT': ['DOGEUSDT', 'SHIBUSDT', 'BONKUSDT'],
  'WIFUSDT':  ['BONKUSDT', 'PEPEUSDT'],
  'TAOUSDT':  ['FETUSDT', 'RENDERUSDT', 'WLDUSDT'],
  'FETUSDT':  ['TAOUSDT', 'RENDERUSDT', 'AGIXUSDT'],
};

async function _wyfootSectorCorrelation(symbol, direction, timeframe = WYCKOFF_TIMEFRAME) {
  const peers = WYCKOFF_SECTOR_PEERS[symbol];
  if (!peers || !peers.length) {
    return { hasPeers: false, agreement: null, peers: [] };
  }

  const results = await Promise.all(peers.slice(0, 3).map(async peer => {
    try {
      const bars = _wyckoffClosedCandles(
        await fetchCandlesCached(peer, timeframe, 100).catch(() => null),
        timeframe
      );
      if (bars.length < 40) return { peer, bias: 'UNKNOWN' };
      const atr = _wyckoffAtr(bars, bars.length);
      const intent = _wyfootCompositeOperatorIntent(bars, atr);
      const alignsWithDir = (direction === 'BUY' && ['ACCUMULATE', 'MARKUP'].includes(intent.intent)) ||
        (direction === 'SELL' && ['DISTRIBUTE', 'MARKDOWN'].includes(intent.intent));
      return {
        peer,
        intent: intent.intent,
        confidence: intent.confidence,
        aligns: alignsWithDir,
      };
    } catch (_) {
      return { peer, bias: 'ERROR' };
    }
  }));

  const aligned = results.filter(r => r.aligns).length;
  const total = results.filter(r => r.intent && r.intent !== 'UNKNOWN').length;
  const agreement = total > 0 ? Math.round(aligned / total * 100) : null;

  return {
    hasPeers: true,
    agreement,
    peers: results,
    verdict: agreement == null ? 'NO_DATA'
      : agreement >= 66 ? 'SECTOR_CONFIRMED'
      : agreement >= 33 ? 'SECTOR_MIXED'
      : 'SECTOR_OPPOSING',
  };
}

/* ══════════════════════════════════════════════════════════════════════════
   MODULE 5 — SMART MONEY vs RETAIL POSITIONING DIVERGENCE
   ─────────────────────────────────────────────────────────────────────────
   When smart money and retail are on OPPOSITE sides of a range, the smart
   money wins. This module measures:
     - Retail proxy: funding rate extremes, crowd positioning on lower TFs
     - Smart money proxy: HTF structure, absorption, silent accumulation
   ══════════════════════════════════════════════════════════════════════════ */
async function _wyfootSmRtDivergence(symbol, direction, funding) {
  // Retail proxy: extreme funding = retail chasing
  const fr = funding?.fundingRate;
  const frPct = fr != null ? fr * 100 : null;
  const retailExtreme = frPct != null && Math.abs(frPct) > 0.05;
  const retailSide = frPct == null ? 'NEUTRAL'
    : frPct > 0.05 ? 'LONG'
    : frPct < -0.05 ? 'SHORT' : 'NEUTRAL';

  // Smart money side = the HTF structure bias. If direction is BUY and retail
  // is SHORT → classic smart-vs-retail setup (whale accumulation).
  let divergence = 'NONE', score = 0, label = '';
  if (retailSide !== 'NEUTRAL') {
    const opposite = (direction === 'BUY' && retailSide === 'SHORT') ||
                     (direction === 'SELL' && retailSide === 'LONG');
    if (opposite) {
      divergence = 'SMART_VS_RETAIL';
      score = Math.min(100, Math.round(Math.abs(frPct) * 800));
      label = `Smart money ${direction} while retail is ${retailSide} (funding ${frPct >= 0 ? '+' : ''}${frPct.toFixed(4)}%)`;
    } else if (retailSide === direction) {
      divergence = 'CROWDED_SAME_SIDE';
      score = 55;
      label = `Retail crowded on ${retailSide} side — reduce size, risk of squeeze`;
    }
  }

  return {
    divergence,
    score,
    label: label || 'No extreme positioning detected',
    fundingPct: frPct != null ? Number(frPct.toFixed(4)) : null,
    retailSide,
  };
}

/* ══════════════════════════════════════════════════════════════════════════
   MODULE 6 — VOLUME SPREAD ANALYSIS (VSA) — Tom Williams Layer
   ─────────────────────────────────────────────────────────────────────────
   VSA is the modern refinement of Wyckoff. Specific bar patterns reveal
   institutional intent:
     - No Demand (up bar + narrow spread + low volume) = weakness
     - No Supply (down bar + narrow spread + low volume) = strength
     - Stopping Volume (down bar + wide spread + very high volume) = demand
     - Buying Climax (up bar + wide spread + very high volume) = supply
     - Upthrust / Shakeout — confirmed Wyckoff events
   ══════════════════════════════════════════════════════════════════════════ */
function _wyfootVsa(bars) {
  if (!bars || bars.length < 30) return { events: [], signal: 'NEUTRAL' };
  const recent = bars.slice(-30);
  const avgVol = recent.reduce((s, c) => s + c.v, 0) / recent.length;
  const avgRange = recent.reduce((s, c) => s + (c.h - c.l), 0) / recent.length;
  const events = [];

  // Scan the last 6 bars
  for (let i = recent.length - 6; i < recent.length; i++) {
    if (i < 1) continue;
    const c = recent[i], prev = recent[i - 1];
    const range = c.h - c.l;
    const body = Math.abs(c.c - c.o);
    const upperWick = c.h - Math.max(c.c, c.o);
    const lowerWick = Math.min(c.c, c.o) - c.l;
    const volRatio = avgVol > 0 ? c.v / avgVol : 1;
    const rangeRatio = avgRange > 0 ? range / avgRange : 1;
    const isUp = c.c > c.o;
    const isDown = c.c < c.o;

    // No Demand: up bar, narrow range, low volume
    if (isUp && rangeRatio < 0.7 && volRatio < 0.7) {
      events.push({ bar: i, type: 'NO_DEMAND', signal: 'SELL', desc: 'Up bar on low volume + narrow range — no institutional demand' });
    }
    // No Supply: down bar, narrow range, low volume
    if (isDown && rangeRatio < 0.7 && volRatio < 0.7) {
      events.push({ bar: i, type: 'NO_SUPPLY', signal: 'BUY', desc: 'Down bar on low volume + narrow range — no institutional supply' });
    }
    // Stopping Volume: down bar, wide range, very high volume
    if (isDown && rangeRatio > 1.3 && volRatio > 1.8) {
      events.push({ bar: i, type: 'STOPPING_VOLUME', signal: 'BUY', desc: 'Wide-range down bar on ultra-high volume — institutional demand absorbing' });
    }
    // Buying Climax: up bar, wide range, very high volume
    if (isUp && rangeRatio > 1.3 && volRatio > 1.8) {
      events.push({ bar: i, type: 'BUYING_CLIMAX', signal: 'SELL', desc: 'Wide-range up bar on ultra-high volume — institutional supply distributing' });
    }
    // Selling Climax (VSA definition): down bar, wide range, high volume + close in upper half
    if (isDown && rangeRatio > 1.2 && volRatio > 1.5 && (c.c - c.l) / range > 0.5) {
      events.push({ bar: i, type: 'SELLING_CLIMAX', signal: 'BUY', desc: 'Selling climax — wide down bar closing in upper half = demand stepped in' });
    }
    // Upthrust (VSA): up bar, high volume, closes near low
    if (isUp && volRatio > 1.5 && (c.h - c.c) / range > 0.6) {
      events.push({ bar: i, type: 'UPTHRUST', signal: 'SELL', desc: 'Upthrust — high volume up bar closing near low = supply overwhelming' });
    }
    // Shakeout (VSA): down bar, high volume, closes near high
    if (isDown && volRatio > 1.5 && (c.c - c.l) / range > 0.6) {
      events.push({ bar: i, type: 'SHAKEOUT', signal: 'BUY', desc: 'Shakeout — high volume down bar closing near high = demand absorbed sellers' });
    }
  }

  // Aggregate signal
  const buys = events.filter(e => e.signal === 'BUY').length;
  const sells = events.filter(e => e.signal === 'SELL').length;
  const signal = buys > sells ? 'BUY' : sells > buys ? 'SELL' : 'NEUTRAL';

  return {
    events: events.slice(-4),
    signal,
    buyEvents: buys,
    sellEvents: sells,
    strength: Math.min(100, Math.abs(buys - sells) * 20 + events.length * 10),
  };
}

/* ══════════════════════════════════════════════════════════════════════════
   MODULE 7 — WYCKOFF TIME-CYCLE ALIGNMENT
   ─────────────────────────────────────────────────────────────────────────
   Wyckoff emphasised time as much as price. A range that has been building
   for 40 bars has more "cause" than one that's only 10 bars old. And a
   Spring that comes too early (before the cause is built) tends to fail.

   This module measures:
     - Bars in current range (cause duration)
     - Time since last Spring/Upthrust
     - Whether current event fires within the ideal time window
   ══════════════════════════════════════════════════════════════════════════ */
function _wyfootTimeCycle(bars, setup) {
  if (!bars || bars.length < 60) return { phase: 'UNKNOWN', barsInRange: 0, ideal: false };
  const slice = bars.slice(-100);
  const rangeWindow = slice.slice(0, 60);
  const rangeHigh = Math.max(...rangeWindow.map(c => c.h));
  const rangeLow = Math.min(...rangeWindow.map(c => c.l));

  // Count how many consecutive bars have closed within the range
  let barsInRange = 0;
  for (let i = slice.length - 1; i >= 60; i--) {
    if (slice[i].c >= rangeLow && slice[i].c <= rangeHigh) barsInRange++;
    else break;
  }

  const barsSinceEvent = setup?.freshnessBars ?? 0;
  // Ideal: range has had time to build (>=15 bars), and event is fresh (<5 bars)
  const causeBuilt = barsInRange >= 15;
  const eventFresh = barsSinceEvent <= 5;
  const ideal = causeBuilt && eventFresh;

  return {
    phase: !causeBuilt ? 'CAUSE_BUILDING' : eventFresh ? 'EVENT_FRESH' : 'EVENT_AGING',
    barsInRange,
    barsSinceEvent,
    causeBuilt,
    eventFresh,
    ideal,
    quality: ideal ? 100 : causeBuilt ? 60 : 30,
  };
}

/* ══════════════════════════════════════════════════════════════════════════
   MODULE 8 — INSTITUTIONAL EXECUTION SIMULATOR
   ─────────────────────────────────────────────────────────────────────────
   Given all the analytical layers above, what would a DESK do RIGHT NOW?

   The simulator outputs ONE of:
     - ACCUMULATE   : start scaling in (small tranches, wide stops)
     - HOLD         : already in position — hold
     - HOLD_RUNNER  : hold remaining position with trailing stop
     - SCALE_OUT    : take partial profits here
     - DISTRIBUTE   : start scaling out (reverse of ACCUMULATE)
     - FLATTEN      : close everything (thesis invalidated)
     - WAIT         : nothing to do — no edge
   ══════════════════════════════════════════════════════════════════════════ */
function _wyfootExecutionSimulator(layers, direction) {
  const {
    compositeIntent, phaseSequence, causalChain, sectorCorrelation,
    smRtDivergence, vsa, timeCycle,
  } = layers;

  // Count confluent signals
  const confluencePoints = [];
  let bullPoints = 0, bearPoints = 0;

  // Composite Operator
  if (compositeIntent.intent === 'ACCUMULATE') { bullPoints += 2; confluencePoints.push('Composite operator accumulating'); }
  if (compositeIntent.intent === 'MARKUP')     { bullPoints += 1; confluencePoints.push('Composite operator marking up'); }
  if (compositeIntent.intent === 'DISTRIBUTE') { bearPoints += 2; confluencePoints.push('Composite operator distributing'); }
  if (compositeIntent.intent === 'MARKDOWN')   { bearPoints += 1; confluencePoints.push('Composite operator marking down'); }

  // Phase Sequence
  if (phaseSequence.phase === 'Spring' || phaseSequence.phase === 'Test') { bullPoints += 2; confluencePoints.push(`Wyckoff phase: ${phaseSequence.desc}`); }
  if (phaseSequence.phase === 'SOS')    { bullPoints += 2; confluencePoints.push('Sign of Strength confirmed'); }
  if (phaseSequence.phase === 'LPS')    { bullPoints += 2; confluencePoints.push('Last Point of Support — final entry'); }
  if (phaseSequence.phase === 'Upthrust') { bearPoints += 2; confluencePoints.push('Upthrust confirmed'); }
  if (phaseSequence.phase === 'SOW')    { bearPoints += 2; confluencePoints.push('Sign of Weakness confirmed'); }

  // Causal Chain
  if (causalChain.stage === 'ACCUMULATION')  { bullPoints += 1; confluencePoints.push(`Causal chain: ${causalChain.stage} (${causalChain.maturityPct}% mature)`); }
  if (causalChain.stage === 'MARKUP')        { bullPoints += 1; confluencePoints.push('Causal chain: markup underway'); }
  if (causalChain.stage === 'DISTRIBUTION')  { bearPoints += 1; confluencePoints.push('Causal chain: distribution underway'); }
  if (causalChain.stage === 'MARKDOWN')      { bearPoints += 1; confluencePoints.push('Causal chain: markdown underway'); }

  // Sector Correlation
  if (sectorCorrelation.verdict === 'SECTOR_CONFIRMED') { direction === 'BUY' ? bullPoints++ : bearPoints++; confluencePoints.push('Sector-wide footprint confirmed'); }
  if (sectorCorrelation.verdict === 'SECTOR_OPPOSING')  { direction === 'BUY' ? bearPoints++ : bullPoints++; confluencePoints.push('Sector-wide footprint opposing'); }

  // SM vs Retail Divergence
  if (smRtDivergence.divergence === 'SMART_VS_RETAIL') { direction === 'BUY' ? bullPoints += 2 : bearPoints += 2; confluencePoints.push(smRtDivergence.label); }
  if (smRtDivergence.divergence === 'CROWDED_SAME_SIDE') { confluencePoints.push('Crowd on same side — squeeze risk'); bullPoints -= 1; bearPoints -= 1; }

  // VSA
  if (vsa.signal === direction && vsa.strength > 50) {
    direction === 'BUY' ? bullPoints += 2 : bearPoints += 2;
    confluencePoints.push(`VSA: ${vsa.events.map(e => e.type).join(', ')}`);
  }

  // Time Cycle
  if (timeCycle.ideal) { direction === 'BUY' ? bullPoints += 2 : bearPoints += 2; confluencePoints.push('Time-cycle alignment: cause built + event fresh'); }
  else if (timeCycle.phase === 'EVENT_AGING') { confluencePoints.push('Event is aging — reduce size'); bullPoints -= 1; bearPoints -= 1; }

  // Determine desk action
  const directionalPoints = direction === 'BUY' ? bullPoints : bearPoints;
  const opposingPoints = direction === 'BUY' ? bearPoints : bullPoints;

  let action, reasoning;
  if (opposingPoints >= directionalPoints + 3) {
    action = 'FLATTEN';
    reasoning = 'Opposing layers dominate — thesis invalidated';
  } else if (directionalPoints >= 9 && opposingPoints <= 1) {
    action = 'ACCUMULATE';
    reasoning = 'All institutional layers confirm — maximum conviction entry';
  } else if (directionalPoints >= 7 && opposingPoints <= 2) {
    action = direction === 'BUY' ? 'ACCUMULATE' : 'DISTRIBUTE';
    reasoning = 'Strong multi-layer confirmation — scale in';
  } else if (directionalPoints >= 5 && opposingPoints <= 2) {
    action = 'HOLD';
    reasoning = 'Layers confirm but not maxed — position size moderate';
  } else if (directionalPoints >= 3) {
    action = 'WAIT';
    reasoning = 'Thin edge — no institutional footprint confirmed';
  } else {
    action = 'WAIT';
    reasoning = 'No clear institutional direction';
  }

  return {
    action,
    reasoning,
    directionalPoints,
    opposingPoints,
    confluencePoints,
    maxPossible: 16,
  };
}

/* ══════════════════════════════════════════════════════════════════════════
   SYNTHESIS — MAIN FOOTPRINT PIPELINE
   ══════════════════════════════════════════════════════════════════════════ */
async function _wyfootSynthesize(
  symbol, bars, atr, setup, funding, timeframe = WYCKOFF_TIMEFRAME
) {
  const [sectorCorrelation, smRtDivergence] = await Promise.all([
    _wyfootSectorCorrelation(symbol, setup.direction, timeframe).catch(() => ({ hasPeers: false, verdict: 'NO_DATA' })),
    _wyfootSmRtDivergence(symbol, setup.direction, funding).catch(() => ({ divergence: 'NONE', score: 0 })),
  ]);

  const compositeIntent = _wyfootCompositeOperatorIntent(bars, atr);
  const phaseSequence = _wyfootPhaseSequence(bars, atr, setup.direction);
  const causalChain = _wyfootCausalChain(bars, atr);
  const vsa = _wyfootVsa(bars);
  const timeCycle = _wyfootTimeCycle(bars, setup);

  const layers = {
    compositeIntent, phaseSequence, causalChain, sectorCorrelation,
    smRtDivergence, vsa, timeCycle,
  };

  const deskSim = _wyfootExecutionSimulator(layers, setup.direction);

  // Composite institutional footprint score
  const footprintScore = Math.min(100, Math.round(
    Math.min(compositeIntent.confidence, 100) * 0.15 +
    (phaseSequence.position >= 5 ? phaseSequence.position / 8 * 100 : 0) * 0.10 +
    Math.min(causalChain.maturityPct, 100) * 0.10 +
    (sectorCorrelation.agreement ?? 50) * 0.10 +
    Math.min(smRtDivergence.score, 100) * 0.10 +
    Math.min(vsa.strength, 100) * 0.10 +
    timeCycle.quality * 0.10 +
    Math.min(deskSim.directionalPoints / deskSim.maxPossible * 100, 100) * 0.25
  ));

  const footprintGrade = footprintScore >= 90 ? 'INSTITUTIONAL_ALIGNED'
    : footprintScore >= 75 ? 'HIGH_CONFLUENCE'
    : footprintScore >= 60 ? 'MODERATE_CONFLUENCE'
    : footprintScore >= 45 ? 'LOW_CONFLUENCE'
    : 'NO_FOOTPRINT';

  return {
    ...layers,
    deskSim,
    footprintScore,
    footprintGrade,
    synthesizedAt: Date.now(),
  };
}

/* ══════════════════════════════════════════════════════════════════════════
   WIRE INTO EXISTING EVALUATE PATH
   ══════════════════════════════════════════════════════════════════════════ */
const _wyfootOrigEvaluate = _wyckoffEvaluateSymbol;
_wyckoffEvaluateSymbol = async function(symbol, requestedDirection = null) {
  const base = await _wyfootOrigEvaluate(symbol, requestedDirection);
  if (!WYCKOFF_FOOTPRINT_ENABLED || !base?.setup) return base;

  try {
    // Cache by symbol + direction + entry to avoid recompute per scan
    const cacheKey = `wyfoot_${symbol}_${base.setup.direction}_${base.setup.entry}`;
    const cached = WYCKOFF_FOOTPRINT_CACHE.get(cacheKey);
    if (cached && Date.now() - cached.ts < WYCKOFF_FOOTPRINT_CACHE_TTL) {
      base.setup.footprint = cached.data;
      return base;
    }

    const bars = _wyckoffClosedCandles(
      Array.isArray(base._rawCandles)
        ? base._rawCandles
        : await fetchCandlesCached(symbol, WYCKOFF_TIMEFRAME, WYCKOFF_CANDLE_LIMIT).catch(() => null),
      WYCKOFF_TIMEFRAME
    );
    if (bars.length < 100) return base;

    const atr = _wyckoffAtr(bars, bars.length);
    const funding = Object.prototype.hasOwnProperty.call(base, '_funding')
      ? base._funding
      : await fetchFundingRateAndOI(symbol).catch(() => null);

    const footprint = await _wyfootSynthesize(symbol, bars, atr, base.setup, funding);
    base.setup.footprint = footprint;
    base.setup.institutionalScore = Math.max(
      base.setup.institutionalScore || 0,
      footprint.footprintScore
    );

    WYCKOFF_FOOTPRINT_CACHE.set(cacheKey, { data: footprint, ts: Date.now() });
    // Bound cache
    if (WYCKOFF_FOOTPRINT_CACHE.size > 300) {
      WYCKOFF_FOOTPRINT_CACHE.delete(WYCKOFF_FOOTPRINT_CACHE.keys().next().value);
    }
  } catch (error) {
    console.warn(`Wyckoff footprint synthesis failed [${symbol}]:`, error.message);
  }
  return base;
};

/* ══════════════════════════════════════════════════════════════════════════
   EXTEND ALERT FORMAT WITH FOOTPRINT LAYER
   ══════════════════════════════════════════════════════════════════════════ */
const _wyfootOrigAlertText = _wyckoffAlertText;
_wyckoffAlertText = function(setup, livePrice, scannedCount = null) {
  const base = _wyfootOrigAlertText(setup, livePrice, scannedCount);
  const fp = setup.footprint;
  if (!fp) return base;

  const fmt = v => Number.isFinite(Number(v)) ? _wyckoffFormatPrice(v) : 'N/A';
  const lines = [base, ''];

  // Institutional Footprint header
  const gradeIcon = fp.footprintGrade === 'INSTITUTIONAL_ALIGNED' ? '🏛️💎'
    : fp.footprintGrade === 'HIGH_CONFLUENCE' ? '🏛️🥇'
    : fp.footprintGrade === 'MODERATE_CONFLUENCE' ? '🏛️🥈'
    : fp.footprintGrade === 'LOW_CONFLUENCE' ? '🏛️🥉'
    : '🏛️⚪';

  lines.push(`━━━ ${gradeIcon} INSTITUTIONAL FOOTPRINT: ${fp.footprintGrade.replace(/_/g,' ')} (${fp.footprintScore}/100) ━━━`);

  // Desk simulation
  lines.push('');
  lines.push('━━━ 🎯 DESK SIMULATION — WHAT WOULD A DESK DO ━━━');
  const deskIcon = fp.deskSim.action === 'ACCUMULATE' ? '🟢'
    : fp.deskSim.action === 'HOLD' ? '🟡'
    : fp.deskSim.action === 'SCALE_OUT' ? '🟠'
    : fp.deskSim.action === 'DISTRIBUTE' ? '🔴'
    : fp.deskSim.action === 'FLATTEN' ? '⛔'
    : '⏸️';
  lines.push(`${deskIcon} <b>${fp.deskSim.action}</b> — ${fp.deskSim.reasoning}`);
  lines.push(`Confluence: ${fp.deskSim.directionalPoints}/${fp.deskSim.maxPossible} directional points`);
  if (fp.deskSim.confluencePoints.length) {
    fp.deskSim.confluencePoints.slice(0, 6).forEach(p => lines.push(`• ${p}`));
  }

  // Composite Operator Intent
  if (fp.compositeIntent) {
    lines.push('');
    lines.push('━━━ 🏛️ COMPOSITE OPERATOR INTENT ━━━');
    lines.push(`Dominant intent: <b>${fp.compositeIntent.intent}</b> (${fp.compositeIntent.confidence}%)`);
    const vec = fp.compositeIntent.vector;
    lines.push(`Accumulate ${vec.accumulate}% · Distribute ${vec.distribute}% · Markup ${vec.markup}% · Markdown ${vec.markdown}%`);
    lines.push(`Range position: ${(fp.compositeIntent.rangePos * 100).toFixed(0)}% · Volume expansion ${fp.compositeIntent.volExpansion}×`);
  }

  // Phase Sequence
  if (fp.phaseSequence) {
    lines.push('');
    lines.push('━━━ 📊 WYCKOFF PHASE SEQUENCE ━━━');
    lines.push(`Current phase: <b>${fp.phaseSequence.phase}</b> (${fp.phaseSequence.desc})`);
    if (fp.phaseSequence.nextPhase) {
      lines.push(`Next expected: <b>${fp.phaseSequence.nextPhase.name}</b> (${fp.phaseSequence.nextPhase.desc})`);
    }
    const seqStr = fp.phaseSequence.sequence.map(p => p.present ? `✅${p.name}` : `⬜${p.name}`).join(' → ');
    lines.push(seqStr);
  }

  // Causal Chain
  if (fp.causalChain) {
    lines.push('');
    lines.push('━━━ 🔗 CAUSAL CHAIN ━━━');
    lines.push(`Stage: <b>${fp.causalChain.stage}</b> (${fp.causalChain.maturityPct}% mature)`);
    lines.push(`Next stage: ${fp.causalChain.nextStage}`);
  }

  // Sector Correlation
  if (fp.sectorCorrelation?.hasPeers) {
    lines.push('');
    lines.push('━━━ 🌐 SECTOR CORRELATION ━━━');
    const verdictIcon = fp.sectorCorrelation.verdict === 'SECTOR_CONFIRMED' ? '✅'
      : fp.sectorCorrelation.verdict === 'SECTOR_MIXED' ? '⚠️'
      : fp.sectorCorrelation.verdict === 'SECTOR_OPPOSING' ? '🚫' : '❓';
    lines.push(`${verdictIcon} <b>${fp.sectorCorrelation.verdict.replace(/_/g,' ')}</b> (${fp.sectorCorrelation.agreement ?? '—'}% agreement)`);
    fp.sectorCorrelation.peers.forEach(p => {
      const icon = p.aligns ? '✅' : p.intent ? '⚠️' : '❓';
      lines.push(`  ${icon} ${p.peer}: ${p.intent || 'NO_DATA'} ${p.confidence ? `(${p.confidence}%)` : ''}`);
    });
  }

  // SM vs Retail
  if (fp.smRtDivergence?.divergence !== 'NONE') {
    lines.push('');
    lines.push('━━━ 🎭 SMART MONEY vs RETAIL ━━━');
    const divIcon = fp.smRtDivergence.divergence === 'SMART_VS_RETAIL' ? '⚡' : '⚠️';
    lines.push(`${divIcon} <b>${fp.smRtDivergence.divergence.replace(/_/g,' ')}</b>`);
    lines.push(fp.smRtDivergence.label);
  }

  // VSA
  if (fp.vsa?.events?.length) {
    lines.push('');
    lines.push('━━━ 📈 VOLUME SPREAD ANALYSIS ━━━');
    lines.push(`Signal: <b>${fp.vsa.signal}</b> · Strength ${fp.vsa.strength}%`);
    fp.vsa.events.forEach(e => {
      const icon = e.signal === 'BUY' ? '🟢' : e.signal === 'SELL' ? '🔴' : '⚪';
      lines.push(`  ${icon} <b>${e.type}</b>: ${e.desc}`);
    });
  }

  // Time Cycle
  if (fp.timeCycle) {
    lines.push('');
    lines.push('━━━ ⏱️ TIME-CYCLE ALIGNMENT ━━━');
    const tcIcon = fp.timeCycle.ideal ? '✅' : fp.timeCycle.causeBuilt ? '⏳' : '⏸️';
    lines.push(`${tcIcon} <b>${fp.timeCycle.phase.replace(/_/g,' ')}</b> (quality ${fp.timeCycle.quality}%)`);
    lines.push(`Cause built: ${fp.timeCycle.barsInRange} bars · Event fresh: ${fp.timeCycle.barsSinceEvent} bars`);
  }

  lines.push('');
  lines.push('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━');
  lines.push(`<i>Heuristic OHLCV-based analysis; this does not prove institutional activity or predict the future. Respect the stop.</i>`);

  return lines.join('\n');
};

