/* ============================================================================
   INDEPENDENT SWING WYCKOFF ENGINE
   ----------------------------------------------------------------------------
   Reuses the deterministic spring/upthrust → SOS/SOW detector, but analyzes
   closed daily candles with weekly structure context and its own thresholds,
   scan cursor, alert history, and persistence. It never modifies or vetoes the
   intraday Wyckoff engine and never arms or places an exchange order.
   ========================================================================== */
const WYCKOFF_SWING_ENGINE_ENABLED =
  !['0', 'false', 'off', 'no'].includes(
    String(process.env.WYCKOFF_SWING_ENGINE_ENABLED ?? 'true').trim().toLowerCase()
  );
const WYCKOFF_SWING_TIMEFRAME = '1day';
const WYCKOFF_SWING_HTF_TIMEFRAME = '1week';
const _wyckoffSwingEnvInt = (name, fallback, min, max) => {
  const value = Number.parseInt(process.env[name] || String(fallback), 10);
  return Number.isFinite(value) ? Math.max(min, Math.min(max, value)) : fallback;
};
const _wyckoffSwingEnvNumber = (name, fallback, min, max) => {
  const value = Number(process.env[name]);
  return Number.isFinite(value) ? Math.max(min, Math.min(max, value)) : fallback;
};
const WYCKOFF_SWING_CANDLE_LIMIT =
  _wyckoffSwingEnvInt('WYCKOFF_SWING_CANDLE_LIMIT', 220, 120, 300);
const WYCKOFF_SWING_WEEKLY_LIMIT =
  _wyckoffSwingEnvInt('WYCKOFF_SWING_WEEKLY_LIMIT', 104, 40, 200);
const WYCKOFF_SWING_SCAN_INTERVAL_MS =
  _wyckoffSwingEnvInt(
    'WYCKOFF_SWING_SCAN_INTERVAL_MS', WYCKOFF_SCAN_INTERVAL_MS,
    60 * 1000, 24 * 60 * 60 * 1000
  );
const WYCKOFF_SWING_SCAN_BATCH_SIZE =
  _wyckoffSwingEnvInt(
    'WYCKOFF_SWING_SCAN_BATCH_SIZE', WYCKOFF_SCAN_BATCH_SIZE, 1, 500
  );
const WYCKOFF_SWING_CONCURRENCY =
  _wyckoffSwingEnvInt('WYCKOFF_SWING_CONCURRENCY', 4, 1, 6);
const WYCKOFF_SWING_SYMBOL_TIMEOUT_MS =
  _wyckoffSwingEnvInt('WYCKOFF_SWING_SYMBOL_TIMEOUT_MS', 60_000, 15_000, 180_000);
const WYCKOFF_SWING_MIN_SCORE_MIN = 60;
const WYCKOFF_SWING_MIN_SCORE_MAX = 98;
let WYCKOFF_SWING_MIN_SCORE =
  _wyckoffSwingEnvInt('WYCKOFF_SWING_MIN_SCORE', 76, 60, 98);
function _wyckoffSwingNormalizeMinimumScore(value) {
  const raw = String(value ?? '').trim().replace(/%$/, '').trim();
  if (!/^\d+$/.test(raw)) return null;
  const score = Number(raw);
  return score >= WYCKOFF_SWING_MIN_SCORE_MIN &&
    score <= WYCKOFF_SWING_MIN_SCORE_MAX ? score : null;
}
const WYCKOFF_SWING_MIN_RR =
  _wyckoffSwingEnvNumber('WYCKOFF_SWING_MIN_RR', 2.0, 1.5, 10);
const WYCKOFF_SWING_STOP_ATR_BUFFER =
  _wyckoffSwingEnvNumber('WYCKOFF_SWING_STOP_ATR_BUFFER', 1.1, 0.5, 2);
const WYCKOFF_SWING_REQUIRE_INSTITUTIONAL =
  process.env.WYCKOFF_SWING_REQUIRE_INSTITUTIONAL === undefined
    ? WYCKOFF_REQUIRE_INSTITUTIONAL
    : ['1', 'true', 'yes', 'on'].includes(
      String(process.env.WYCKOFF_SWING_REQUIRE_INSTITUTIONAL).trim().toLowerCase()
    );
const WYCKOFF_SWING_ALERT_COOLDOWN_MS =
  _wyckoffSwingEnvInt(
    'WYCKOFF_SWING_ALERT_COOLDOWN_MS', 24 * 60 * 60 * 1000,
    60 * 60 * 1000, 30 * 24 * 60 * 60 * 1000
  );
const WYCKOFF_SWING_STATE_FILE = storagePath('wyckoff_swing_engine.json');
try { STORAGE_LIMITS['wyckoff_swing_engine.json'] = 256 * 1024; } catch (_) {}

const WYCKOFF_SWING_DETECTOR_SETTINGS = {
  horizon: 'SWING',
  candleLimit: WYCKOFF_SWING_CANDLE_LIMIT,
  minimumBars: 120,
  rangeLookback: 90,
  eventWindow: 14,
  recentBreakWindow: 60,
  minimumRangeBars: 35,
  retestWindow: 14,
  retestFreshnessBars: 5,
  maximumBreakFreshnessBars: 7,
  minimumScore: WYCKOFF_SWING_MIN_SCORE,
  requireInstitutionalEvidence: WYCKOFF_SWING_REQUIRE_INSTITUTIONAL,
  maximumRangeAtr: 18,
  minimumRR: WYCKOFF_SWING_MIN_RR,
  stopAtrBuffer: WYCKOFF_SWING_STOP_ATR_BUFFER,
  allowRetestEntry: true,
};

const _wyckoffSwingState = {
  running: false,
  enabled: WYCKOFF_SWING_ENGINE_ENABLED,
  cursor: 0,
  universeSize: 0,
  universeSource: null,
  cycles: 0,
  scanned: 0,
  setupsFound: 0,
  alertsSent: 0,
  lastScanAt: 0,
  lastScanDurationMs: 0,
  lastScanSummary: null,
  lastResults: [],
  lastError: null,
  alerts: {},
};

try {
  if (fs.existsSync(WYCKOFF_SWING_STATE_FILE)) {
    const saved = JSON.parse(fs.readFileSync(WYCKOFF_SWING_STATE_FILE, 'utf8'));
    if (saved && typeof saved === 'object') Object.assign(_wyckoffSwingState, saved);
  }
} catch (error) {
  console.warn('Swing Wyckoff state load skipped:', error.message);
}
const _savedSwingMinimumScore =
  _wyckoffSwingNormalizeMinimumScore(_wyckoffSwingState.minimumScore);
if (_savedSwingMinimumScore !== null) {
  WYCKOFF_SWING_MIN_SCORE = _savedSwingMinimumScore;
}
WYCKOFF_SWING_DETECTOR_SETTINGS.minimumScore = WYCKOFF_SWING_MIN_SCORE;
_wyckoffSwingState.minimumScore = WYCKOFF_SWING_MIN_SCORE;
_wyckoffSwingState.running = false;
_wyckoffSwingState.enabled = WYCKOFF_SWING_ENGINE_ENABLED;
if (!Array.isArray(_wyckoffSwingState.lastResults)) _wyckoffSwingState.lastResults = [];
if (!_wyckoffSwingState.alerts || typeof _wyckoffSwingState.alerts !== 'object') {
  _wyckoffSwingState.alerts = {};
}

function _wyckoffSwingSaveState() {
  try {
    _wyckoffSwingState.lastResults = _wyckoffSwingState.lastResults.slice(-100);
    // Drop alerts older than 2x the cooldown first, then cap the remainder.
    const _alertCutoff = Date.now() - WYCKOFF_SWING_ALERT_COOLDOWN_MS * 2;
    _wyckoffSwingState.alerts = Object.fromEntries(
      Object.entries(_wyckoffSwingState.alerts)
        .filter(([, v]) => Number(v?.sentAt) >= _alertCutoff)
        .slice(-300)
    );
    writeJsonBounded(WYCKOFF_SWING_STATE_FILE, _wyckoffSwingState, {
      maxBytes: 256 * 1024,
    });
  } catch (error) {
    console.warn('Swing Wyckoff state save skipped:', error.message);
  }
}

function _wyckoffSwingSetMinimumScore(value) {
  const score = _wyckoffSwingNormalizeMinimumScore(value);
  if (score === null) return false;
  WYCKOFF_SWING_MIN_SCORE = score;
  WYCKOFF_SWING_DETECTOR_SETTINGS.minimumScore = score;
  _wyckoffSwingState.minimumScore = score;
  _wyckoffSwingState.minimumScoreUpdatedAt = Date.now();
  _wyckoffSwingSaveState();
  return true;
}

function getSwingWyckoffStatus() {
  return {
    ok: true,
    engine: 'SWING_WYCKOFF',
    independentFrom: 'INTRADAY_WYCKOFF',
    enabled: WYCKOFF_SWING_ENGINE_ENABLED,
    timeframe: WYCKOFF_SWING_TIMEFRAME,
    higherTimeframe: WYCKOFF_SWING_HTF_TIMEFRAME,
    candleLimit: WYCKOFF_SWING_CANDLE_LIMIT,
    weeklyCandleLimit: WYCKOFF_SWING_WEEKLY_LIMIT,
    batchSize: WYCKOFF_SWING_SCAN_BATCH_SIZE,
    intervalMs: WYCKOFF_SWING_SCAN_INTERVAL_MS,
    concurrency: WYCKOFF_SWING_CONCURRENCY,
    minimumScore: WYCKOFF_SWING_MIN_SCORE,
    minimumRR: WYCKOFF_SWING_MIN_RR,
    stopAtrBuffer: WYCKOFF_SWING_STOP_ATR_BUFFER,
    requireInstitutionalEvidence: WYCKOFF_SWING_REQUIRE_INSTITUTIONAL,
    watchlistSize: WATCH.size,
    bitgetUniverseSize: Array.isArray(_rankedSymbols) ? _rankedSymbols.length : 0,
    state: {
      ..._wyckoffSwingState,
      running: _wyckoffSwingState.running,
      alerts: Object.keys(_wyckoffSwingState.alerts).length,
    },
  };
}

async function _enrichSwingWyckoffSetup(symbol, setup, daily, weekly) {
  const atr = _wyckoffAtr(daily, daily.length);
  let funding = null;
  try { funding = await fetchFundingRateAndOI(symbol).catch(() => null); } catch (_) {}

  if (WYCKOFF_UPGRADE_ENABLED) {
    try {
      const swingTimeframes = [
        { tf: '1week', label: 'W', candles: WYCKOFF_SWING_WEEKLY_LIMIT, weight: 5 },
        { tf: '1day', label: 'D', candles: WYCKOFF_SWING_CANDLE_LIMIT, weight: 3 },
      ];
      const [multiTF, relativeStrength, orderflow] = await Promise.all([
        _wyUpgradeMultiTFPhases(symbol, weekly, {
          cacheSuffix: 'SWING',
          timeframes: swingTimeframes,
          preloadedBars: { '1week': weekly, '1day': daily },
        }).catch(() => null),
        _wyUpgradeRelativeStrength(symbol, daily, WYCKOFF_SWING_TIMEFRAME).catch(() => null),
        _wyUpgradeOrderflow(symbol, daily, funding).catch(() => null),
      ]);
      const effort = _wyUpgradeEffortResult(daily);
      const causeEffect = _wyUpgradeCauseEffect(daily, atr);
      const liquidityChain = _wyUpgradeLiquidityChain(
        daily, setup.direction, setup.entry, atr
      );
      const upgrades = {
        multiTF,
        effort,
        causeEffect,
        relativeStrength,
        orderflow,
        liquidityChain,
        institutionalEvidence: setup.institutionalEvidence,
      };
      const verdict = _wyUpgradeComposeVerdict(setup, upgrades);
      const ladder = _wyUpgradeBuildLadder(
        setup.entry,
        setup.stop,
        liquidityChain.chain.map(row => row.level),
        setup.direction
      );
      setup.institutional = {
        ...verdict,
        multiTF,
        effort,
        causeEffect,
        relativeStrength,
        orderflow,
        liquidityChain,
        ladder,
      };
      setup.score = Math.max(setup.score, verdict.institutionalScore);
      setup.institutionalScore = verdict.institutionalScore;
      setup.grade = verdict.grade;
    } catch (error) {
      console.warn(`Swing Wyckoff institutional enrichment failed [${symbol}]:`, error.message);
    }
  }

  if (WYCKOFF_FOOTPRINT_ENABLED) {
    try {
      setup.footprint = await _wyfootSynthesize(
        symbol, daily, atr, setup, funding, WYCKOFF_SWING_TIMEFRAME
      );
      setup.institutionalScore = Math.max(
        setup.institutionalScore || 0,
        setup.footprint.footprintScore
      );
    } catch (error) {
      console.warn(`Swing Wyckoff footprint synthesis failed [${symbol}]:`, error.message);
    }
  }
  return setup;
}

async function _evaluateSwingWyckoffSymbol(symbol, requestedDirection = null) {
  const [live, rawDaily, rawWeekly] = await Promise.all([
    fetchLivePrice(symbol).catch(() => null),
    fetchCandlesCached(
      symbol, WYCKOFF_SWING_TIMEFRAME, WYCKOFF_SWING_CANDLE_LIMIT
    ).catch(() => null),
    fetchWeeklyMacroCached(
      symbol, WYCKOFF_SWING_WEEKLY_LIMIT
    ).catch(() => null),
  ]);
  const daily = _wyckoffClosedCandles(rawDaily, WYCKOFF_SWING_TIMEFRAME);
  const weekly = _wyckoffClosedCandles(rawWeekly, WYCKOFF_SWING_HTF_TIMEFRAME);
  const livePrice = Number(live) || daily.at(-1)?.c || null;
  if (daily.length < WYCKOFF_SWING_DETECTOR_SETTINGS.minimumBars) {
    return {
      symbol, livePrice, setup: null,
      reason: `Need at least ${WYCKOFF_SWING_DETECTOR_SETTINGS.minimumBars} closed daily candles; received ${daily.length}.`,
    };
  }
  if (weekly.length < 30) {
    return {
      symbol, livePrice, setup: null,
      reason: `Need at least 30 closed weekly context candles; received ${weekly.length}.`,
    };
  }

  const marketContext = {
    timeframe: WYCKOFF_SWING_TIMEFRAME,
    htfCandles: weekly,
    htfTimeframe: WYCKOFF_SWING_HTF_TIMEFRAME,
    candleLimit: WYCKOFF_SWING_CANDLE_LIMIT,
    engineSettings: WYCKOFF_SWING_DETECTOR_SETTINGS,
  };
  const setup = detectWyckoffStructureBreak(
    daily, livePrice, requestedDirection, marketContext
  );
  if (setup) {
    setup.symbol = symbol;
    setup.horizon = 'SWING';
    setup.timeframe = WYCKOFF_SWING_TIMEFRAME;
    setup.higherTimeframe = WYCKOFF_SWING_HTF_TIMEFRAME;
    await _enrichSwingWyckoffSetup(symbol, setup, daily, weekly);
  }
  return {
    symbol,
    livePrice,
    setup,
    weeklyBias: marketContext.evidenceByDirection || {},
  };
}

function _wyckoffSwingAlertKey(setup) {
  return `${setup.symbol}:SWING:${setup.direction}`;
}

function _wyckoffSwingShouldAlert(setup) {
  const prior = _wyckoffSwingState.alerts[_wyckoffSwingAlertKey(setup)];
  if (!prior) return true;
  const entryDrift = Number(prior.entry) > 0
    ? Math.abs(Number(prior.entry) - Number(setup.entry)) / Number(prior.entry)
    : 1;
  return prior.stage !== setup.stage ||
    entryDrift > 0.004 ||
    Date.now() - Number(prior.sentAt || 0) >= WYCKOFF_SWING_ALERT_COOLDOWN_MS;
}

function _wyckoffSwingAlertText(setup, livePrice, scannedCount = null) {
  return _wyckoffAlertText(setup, livePrice, scannedCount);
}

async function _wyckoffSwingSendAlert(setup, livePrice, scannedCount) {
  if (!_wyckoffSwingShouldAlert(setup)) return false;
  if (!TELEGRAM_TOKEN || !TELEGRAM_CHAT_ID || typeof tg !== 'function') {
    console.log(
      `🏛️ SWING WYCKOFF SETUP (Telegram unavailable): ${setup.symbol} ${setup.direction} entry=${setup.entry} stop=${setup.stop} tp=${setup.takeProfit}`
    );
    return false;
  }
  try {
    const response = await tg('sendMessage', {
      chat_id: TELEGRAM_CHAT_ID,
      text: _wyckoffSwingAlertText(setup, livePrice, scannedCount),
      parse_mode: 'HTML',
      disable_web_page_preview: true,
    });
    if (!response?.ok) {
      console.warn(
        `Swing Wyckoff Telegram alert rejected for ${setup.symbol}:`,
        response?.description || 'unknown response'
      );
      return false;
    }
    _wyckoffSwingState.alerts[_wyckoffSwingAlertKey(setup)] = {
      stage: setup.stage,
      entry: setup.entry,
      stop: setup.stop,
      takeProfit: setup.takeProfit,
      score: setup.score,
      sentAt: Date.now(),
    };
    _wyckoffSwingState.alertsSent++;
    _wyckoffSwingSaveState();
    console.log(`✅ Swing Wyckoff alert sent: ${setup.symbol} ${setup.direction} ${setup.stage}`);
    return true;
  } catch (error) {
    console.warn(`Swing Wyckoff Telegram alert failed for ${setup.symbol}:`, error.message);
    return false;
  }
}

async function runSwingWyckoffScan({
  force = false, symbols = null, manual = false,
} = {}) {
  if (_wyckoffSwingState.running) {
    return { ok: false, skipped: true, reason: 'Swing Wyckoff scan already running' };
  }
  if (!manual && !WYCKOFF_SWING_ENGINE_ENABLED) {
    return { ok: false, skipped: true, reason: 'Swing Wyckoff automatic engine is disabled' };
  }
  if (!manual && typeof _telegramPollingOwner !== 'undefined' && !_telegramPollingOwner) {
    return { ok: false, skipped: true, reason: 'Passive instance; another process owns Telegram polling' };
  }

  _wyckoffSwingState.running = true;
  const startedAt = Date.now();
  try {
    const loadedUniverse = await _wyckoffLoadCombinedUniverse(symbols);
    const universe = loadedUniverse.symbols;
    const universeSource = loadedUniverse.source;
    if (!universe.length) throw new Error('Swing Wyckoff Bitget USDT-M universe is empty');

    _wyckoffSwingState.universeSource = universeSource;
    _wyckoffSwingState.universeSize = universe.length;
    const batchSize = force
      ? Math.min(WYCKOFF_FORCE_SCAN_MAX_BATCH, universe.length)
      : Math.min(WYCKOFF_SWING_SCAN_BATCH_SIZE, universe.length);
    const start = _wyckoffSwingState.cursor % universe.length;
    const selected = Array.from({ length: batchSize }, (_, index) =>
      universe[(start + index) % universe.length]
    );
    _wyckoffSwingState.cursor = (start + batchSize) % universe.length;

    const results = [];
    for (let offset = 0; offset < selected.length; offset += WYCKOFF_SWING_CONCURRENCY) {
      const group = selected.slice(offset, offset + WYCKOFF_SWING_CONCURRENCY);
      const rows = await Promise.all(group.map(async symbol => {
        try {
          return await raceDeadline(
            _evaluateSwingWyckoffSymbol(symbol),
            WYCKOFF_SWING_SYMBOL_TIMEOUT_MS,
            `swingWyckoff:${symbol}`
          );
        } catch (error) {
          return { symbol, setup: null, livePrice: null, error: error.message };
        }
      }));
      results.push(...rows);
      if (offset + WYCKOFF_SWING_CONCURRENCY < selected.length) await sleep(200);
    }

    const candidates = results.filter(row => row.setup);
    const blocked = candidates.filter(row =>
      row.setup.institutionalEvidence?.hardBlock === true
    );
    const setups = candidates.filter(row =>
      row.setup.institutionalEvidence?.hardBlock !== true
    );
    _wyckoffSwingState.lastScanAt = Date.now();
    _wyckoffSwingState.lastScanDurationMs = Date.now() - startedAt;
    _wyckoffSwingState.cycles++;
    _wyckoffSwingState.scanned += selected.length;
    _wyckoffSwingState.setupsFound += setups.length;
    _wyckoffSwingState.lastError = null;
    _wyckoffSwingState.lastScanSummary = {
      selected: selected.length,
      candidates: candidates.length,
      setups: setups.length,
      blockedByWeeklyConflict: blocked.length,
      noSetup: results.filter(row => !row.setup && !row.error).length,
      errors: results.filter(row => row.error).length,
    };
    _wyckoffSwingState.lastResults = setups.map(row => ({
      ...row.setup,
      livePrice: row.livePrice,
      scannedAt: Date.now(),
    }));

    let alertsSent = 0;
    for (const row of setups) {
      if (await _wyckoffSwingSendAlert(row.setup, row.livePrice, selected.length)) {
        alertsSent++;
      }
    }
    _wyckoffSwingState.lastScanSummary.alertsSent = alertsSent;
    _wyckoffSwingSaveState();
    console.log(
      `🏛️ Swing Wyckoff scan complete: ${selected.length}/${universe.length} assets, ` +
      `${setups.length} setups, ${blocked.length} weekly-context blocks, ${alertsSent} alerts`
    );
    return {
      ok: true,
      force,
      horizon: 'SWING',
      timeframe: WYCKOFF_SWING_TIMEFRAME,
      higherTimeframe: WYCKOFF_SWING_HTF_TIMEFRAME,
      scanned: selected.length,
      universeSize: universe.length,
      universeSource,
      universeBreakdown: {
        bitgetRanked: loadedUniverse.bitgetCount,
        watchlist: loadedUniverse.watchlistCount,
        watchlistOnly: loadedUniverse.watchlistOnlyCount,
      },
      setups: setups.map(row => ({ ...row.setup, livePrice: row.livePrice })),
      blockedByWeeklyConflict: blocked.length,
      scanSummary: _wyckoffSwingState.lastScanSummary,
      nextCursor: _wyckoffSwingState.cursor,
      generatedAt: Date.now(),
    };
  } catch (error) {
    _wyckoffSwingState.lastError = error.message;
    console.error('Swing Wyckoff scan failed:', error.message);
    return { ok: false, error: error.message, generatedAt: Date.now() };
  } finally {
    _wyckoffSwingState.running = false;
    _wyckoffSwingState.completedAt = Date.now();
    _wyckoffSwingSaveState();
  }
}

const _swingWyckoffPreviousHandler =
  EnhancedQuantumTelegramInterface.prototype.handleEnhancedCommand;
EnhancedQuantumTelegramInterface.prototype.handleEnhancedCommand = async function(message) {
  const text = String(message?.text || '').trim();
  const parts = text.split(/\s+/);
  const command = String(parts[0] || '').toLowerCase().replace(/@[^\s]+$/, '');
  const chatId = message?.chat?.id;
  if (command === '/swingwythreshold' || command === '/swingwyckoffthreshold') {
    if (typeof isAdminMessage === 'function' && !isAdminMessage(message)) return;
    const requested = parts[1];
    if (requested == null || requested === '') {
      await this.sendMessage(chatId,
        `🏛️ <b>Swing Wyckoff quality threshold:</b> ${WYCKOFF_SWING_MIN_SCORE}%\n` +
        `Only swing setups scoring ${WYCKOFF_SWING_MIN_SCORE}% or higher pass.\n` +
        `Usage: <code>/swingwythreshold 60%-98%</code>`
      );
      return;
    }
    const nextScore = _wyckoffSwingNormalizeMinimumScore(requested);
    if (nextScore === null) {
      await this.sendMessage(chatId,
        `❌ Swing Wyckoff threshold must be a whole number from ` +
        `${WYCKOFF_SWING_MIN_SCORE_MIN}% to ${WYCKOFF_SWING_MIN_SCORE_MAX}%.\n` +
        `Current: <b>${WYCKOFF_SWING_MIN_SCORE}%</b>`
      );
      return;
    }
    _wyckoffSwingSetMinimumScore(nextScore);
    await this.sendMessage(chatId,
      `✅ <b>Swing Wyckoff threshold set to ${WYCKOFF_SWING_MIN_SCORE}%</b>\n` +
      `Only swing setups scoring ${WYCKOFF_SWING_MIN_SCORE}% or higher will pass.\n` +
      `Intraday Wyckoff threshold remains ${WYCKOFF_MIN_SCORE}% and is unchanged.\n` +
      `💾 Saved and will persist after restart.`
    );
    return;
  }
  const symbolCommands = ['/swingwyckoff', '/wyckoffswing', '/swingwy'];
  const scanCommands = ['/swingwyckoffscan', '/swingwyscan'];
  if (symbolCommands.includes(command)) {
    if (typeof isAdminMessage === 'function' && !isAdminMessage(message)) return;
    const symbol = parts[1] ? normalizeAnalysisSymbol(parts[1]) : null;
    const direction = String(parts[2] || '').toUpperCase();
    if (!symbol || (direction && !['BUY', 'SELL'].includes(direction))) {
      await this.sendMessage(chatId, [
        '🏛️ <b>SWING WYCKOFF ENGINE</b>',
        'Usage: <code>/swingwyckoff SYMBOL [BUY|SELL]</code>',
        'Example: <code>/swingwyckoff BTCUSDT BUY</code>',
        'Analysis: closed 1D candles with independent 1W structure context.',
      ].join('\n'));
      return;
    }
    try {
      await this.sendMessage(
        chatId,
        `🏛️ Mapping an independent 1D/1W swing Wyckoff setup for <b>${symbol}</b>...`
      );
      const row = await _evaluateSwingWyckoffSymbol(symbol, direction || null);
      const hardBlock = row.setup?.institutionalEvidence?.hardBlock === true;
      if (!row.setup || hardBlock) {
        const evidence = row.setup?.institutionalEvidence;
        const reason = row.reason || (evidence?.htfStructureConflict
          ? `Weekly structure conflict: ${evidence.htfStructure}.`
          : evidence?.htfPhaseConflict
            ? `Weekly phase conflict: ${evidence.htfPhase}.`
            : 'No fresh swing setup met its independent entry, quality, and risk/reward rules.');
        await this.sendMessage(chatId, [
          `⏳ No approved swing setup for <b>${symbol}</b>.`,
          `Horizon: <b>1D setup / 1W context</b>.`,
          reason,
          evidence
            ? `Weekly evidence: <b>${evidence.score}/100</b> · ${evidence.htfStructure} · ${evidence.htfPhase}`
            : '',
          'The intraday Wyckoff engine is separate and was not changed by this result.',
        ].filter(Boolean).join('\n'));
      } else {
        await this.sendMessage(
          chatId,
          _wyckoffSwingAlertText(row.setup, row.livePrice),
          { parse_mode: 'HTML', disable_web_page_preview: true }
        );
      }
    } catch (error) {
      await this.sendMessage(chatId, `❌ Swing Wyckoff error: ${error.message}`);
    }
    return;
  }
  if (scanCommands.includes(command)) {
    if (typeof isAdminMessage === 'function' && !isAdminMessage(message)) return;
    await this.sendMessage(
      chatId,
      `🔎 Starting a separate swing Wyckoff scan across the combined ranked Bitget universe + watchlist (up to ${WYCKOFF_FORCE_SCAN_MAX_BATCH} assets this run; rotation continues next time)...`
    );
    const result = await runSwingWyckoffScan({ force: true, manual: true });
    const setups = result.setups || [];
    await this.sendMessage(chatId, result.ok
      ? setups.length
        ? `✅ <b>Swing Wyckoff scan complete</b>\n` +
          `Found <b>${setups.length}</b> independent 1D/1W setup(s).\n\n` +
          setups.slice(0, 8).map(row =>
            `🏛️ ${row.symbol} ${row.direction} · Entry <code>${_wyckoffFormatPrice(row.entry)}</code> · TP <code>${_wyckoffFormatPrice(row.takeProfit)}</code> · ${row.score}%`
          ).join('\n')
        : '📭 <b>Swing Wyckoff scan complete</b>\nNo fresh actionable 1D/1W setups found.'
      : `❌ Swing Wyckoff scan failed: ${result.error || result.reason || 'unknown error'}`);
    return;
  }
  if (command === '/swingwyckoffstatus') {
    if (typeof isAdminMessage === 'function' && !isAdminMessage(message)) return;
    const status = getSwingWyckoffStatus();
    await this.sendMessage(chatId, [
      '🏛️ <b>SWING WYCKOFF STATUS</b>',
      `Automatic: <b>${status.enabled ? 'ON' : 'OFF'}</b>`,
      `Setup/context: <b>${status.timeframe} / ${status.higherTimeframe}</b>`,
      `Quality threshold: <b>${status.minimumScore}%</b>`,
      `Batch: <b>${status.batchSize}</b> every <b>${Math.round(status.intervalMs / 60_000)} min</b>`,
      `Scanned: <b>${status.state.scanned || 0}</b> · Setups: <b>${status.state.setupsFound || 0}</b> · Alerts: <b>${status.state.alertsSent || 0}</b>`,
      status.state.lastError ? `Last error: ${status.state.lastError}` : '',
      'Intraday Wyckoff has separate settings, state, and alerts.',
    ].filter(Boolean).join('\n'));
    return;
  }
  return _swingWyckoffPreviousHandler.call(this, message);
};

